/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180702-6","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"区民委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４７号議案 品川区印鑑条例の一部を改正する条例","agenda":"第４７号議案 品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"改めてというところもありますけれども、新たに印鑑登録証をつくる人というのは、全員一元化されて１つのカードになってしまうのかというところを確認させていただきたいと思います。今ご説明があった中で、申し出があった場合というお話でしたけれども、実際、窓口ではどういった説明がされるのかということも伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"申し出があった場合ということで、今ご説明したとおりですけれども、申し出があった場合に限って、一元化をすると。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"希望者の方がカードを一元化できるということで、申し出があったときの窓口での対応において、申請書自体が、１つになって出されるような形にならないかというところを危惧しておりまして、そこのところでしっかりと、選べるのだということを説明することになるのか、そこのところを確認させていただきたいと思います。マイナンバーと印鑑登録証がリンクすることはないと。","respondent":"提坂戸籍住民課長","answer":"窓口に印鑑登録を希望される方がいらっしゃった場合、もちろん、個人番号カードをお持ちということが前提ですけれども、その場合、一元化できるということをご説明させていただいて、お近くのコンビニで早朝から深夜まで。","voiceIndex":9,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"希望者の方はカードを一元化できるということで、万が一、それを一元化した後に、やはりもとに戻したいということもできるのか、伺いたいと思います。空き部分は具体的にはわからないという話でしたけれども、大体何割ぐらい空いているとか、どのくらい使っているというのがもしわかれば、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"その際は、既に登録しているということで、手数料はいただきません。空き部分については、まだまだ活用の部分がかなりあるということで、区役所でもまだまだ活用の余地があると思いますので、かなりの空きはあると考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"わかりました。あわせて、新旧対照表を見ると、カードの一元化をすると、登録内容の変更が代理人はできなくなってしまって、本人しか変更できなくなると私は理解したのですけれども、その認識が正しいかというところの確認と、ほかに登録者にとって今までとの変更点があれば伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"登録内容の変更のところで、代理人を認めないということで、第４条のところで印鑑登録の代理人による申請ができる旨を規定していますけれども、第９条の２の第３項のところで。","voiceIndex":13,"id":"exchange-004"},{"speaker":"のだて委員","kind":"意見","question":"登録した内容の変更が代理人ではできなくなるのかということと、ほかに変更点があるかどうかということです。","respondent":"提坂戸籍住民課長","answer":"登録内容の変更につきましては、今申し上げたとおり、本人申請に限るです。一元化の手続については大きな変更はございません。","voiceIndex":16,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"最後に、印鑑登録原票のほうも伺いたいのですが、パソコンの中で管理されるということになると、セキュリティの問題があると思うのですけれども、サイバー攻撃とか、何らかの形でデータが消えてしまったという場合などへの対応は、どのようになっているのか、また、原票の電子化で区民への影響はあるのかを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"セキュリティにつきましては、区の委託しているベンダーのほうで２４時間、監視システムということを行ってございまして、セキュリティ対策は万全と考えています。ダウンした場合も、バックアップのデータを保管しておりますので、その辺の対応も万全になっております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"バックアップもあるということですが、そのバックアップは、委託している監視システムのところでされているということでしょうか。","respondent":"提坂戸籍住民課長","answer":"失礼しました。バックアップシステムにつきましては、ベンダーの監視センターというのですが、そちらでも保管していますし、区でも参照系データというデータをもってございまして、万が一のダウンに備えてあります。","voiceIndex":20,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"そもそも論をお伺いしたいのですけれども、欧米ではいろいろな契約だとか、そういうものにサイン等ではないですか。日本は印鑑、実印とか、今日は実印のという形の印鑑条例ですけれども、なぜこう日本は印鑑を重視する文化なのか、教えていただきたいのが１点と、これが一元化されて便利にはなるのでしょう、簡素化されると思うのですけれども、安全性は改めて担保されるのでしょうかということ。","respondent":"提坂戸籍住民課長、菅生活安全担当課長","answer":"万が一なくした場合は、印鑑登録証に限ったことではないですけれども、個人番号カードを紛失されたということで警察に届けていただくのと、コールセンターがございまして。関係者が多数いるということですので、今後捜査が進展するものと考えております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、生活安全担当課長。こういう施策が出てきて、簡素化、便利、一元化になるという形にはなっていくのですが、今の担当として、生活安全という意味で、詐欺という意味も含めて、こういう施策に対してどういうお考えか、しないほうがいいのかなとか、したほうがいいですねとか、率直に、現場にいた方としてどう思われるか、感想でいいのでお伺いしたいと思っています。","respondent":"提坂戸籍住民課長、菅生活安全担当課長","answer":"安全性の担保ですけれども、一元化されたマイナンバーカード兼印鑑登録証をお使いになる場合は、４桁の暗証番号を入力していただいて、カードを機械にタッチすることによって確認をして、印鑑証明をお出しするということなので。ただ、個人情報にしても、先ほどのセキュリティの関係にしても、絶対漏れない、１００％絶対安全とは言い切れない世の中だと考えていますので、いろいろな施策をやっていただきながら。","voiceIndex":25,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"印鑑登録原票の電子化について伺いたいのですけれども、原票を磁気ディスク化することによって、今カードを持っている方に関して、またそのカードが変わるとか、そういうこともあるのか、それとも今のままで、事務作業上のことが変化するというだけなのかということを教えてください。","respondent":"提坂戸籍住民課長","answer":"印鑑登録原票の電子化については、あくまでも内部の事務作業を変えるということでございまして、印鑑登録されているお客様の印鑑登録証を変えるとか、そういうことではございません。","voiceIndex":28,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど答弁の中で、コンビニ交付が進んでいる状況にあるということだったのですけれども、現状を教えていただきたいのと、さっき安全性の担保のお話があったのですけれども、４桁の暗証番号を入れることと、２４時間のコールセンターがあるので対応もできる、そこら辺で安全性の担保が確保されるというお話だったのですけれども、これでは安全性の担保が確保されているとは。","respondent":"提坂戸籍住民課長","answer":"安全性、セキュリティの関係ですけれども、コールセンターのご説明が足りなくて申し訳ございませんでした。","voiceIndex":30,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認をさせていただきたいのが、手数料は要らないということだったので、改めて、手数料は要らないということだったかどうかの確認と、電子化するための費用というのがどのくらいかかるのか。","respondent":"提坂戸籍住民課長","answer":"今後は１万件、さらに伸ばしたいところですけれども、区民の方の４分の１とか５分の１ぐらいの普及率を目指して、その中で印鑑登録している人についても、今後コンビニのご利用をお願いして、窓口の混雑緩和を図っていきたいと考えています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"大倉委員","kind":"質問","question":"今後さらに進めていきたいというところでいうと、コストもそんなにかからないというところで、一元化取扱窓口というのを、今、ここだけになっていますけれども、これは今後、このままの数で進めていくのか、それとももう少し、逆に言うと、ここを増やしていくと、かなり費用がかかってしまうのか、利便性というところでいうと、区民の利便性というところで。","respondent":"提坂戸籍住民課長","answer":"現在、区に地域センターが１３カ所ございまして、以前はどこの地域センターでも転入とか転出の異動届、印鑑登録、それから住民票とか印鑑証明の発行をしてございましたけれども、事務の見直しを行った結果、転入・転出の異動届と印鑑登録ができる窓口は。","voiceIndex":34,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。先ほどから安全性の担保というところで、コールセンターに２４時間電話してもらえれば、いつでも止められますというところで、コールセンターへの案内とか、その辺はどうやって知ったらいいのでしょうかということを教えていただきたい。","respondent":"提坂戸籍住民課長","answer":"区のホームページを見ていただければ、コールセンターの連絡先を示していますけれども、今後、コンビニ交付とかマイナンバーカードの普及を図る広報をするときに、その辺もあわせて周知を図ってまいりたいと考えております。","voiceIndex":36,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問","question":"もう１個は、大倉委員が今おっしゃられた取扱窓口のセンターのばらつきが、ぱっと見たときに大丈夫なのかと思って、ご説明を聞いていて、そういうものなのかと思ったので、これは興味を含めて、普通に考えたら、ばらついていたらと思うので、それを補完する形でコンビニがあるからもう担保できていますと言い切れるのか、その辺のところをもう一度、詳しく教えてください。","respondent":"提坂戸籍住民課長","answer":"安全性の担保につきましても、一元化をするにあたっては本庁の窓口と６地域センターで十分に本人確認を行って、説明をし尽くさせていただいた上でお受けしますので、安全性は担保されると考えています。","voiceIndex":38,"id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問","question":"最初のところはわかりました。ないに等しいから、一元化していって縮小してきました。全部でやるとコストの問題があるというと、区民サービスもコストありきに聞こえてしまうので、多分そうではないと思うので、その辺を教えてください。こういうことには、なぜこうなのか、理由を簡単に言っていただいたほうが、最もわかりやすい気がします。その点だけ教えてください。","respondent":"提坂戸籍住民課長","answer":"先ほども申し上げたのですけれども、十数年前に地域センターの事務の見直しを行った際に、住民異動ですとか戸籍とか、納課税証明書の発行とか、いわゆる行政事務と、地域センターは地域事務と両方の事務を行っているわけでございまして、その辺のバランスを考えて。","voiceIndex":40,"id":"exchange-016"},{"speaker":"浅野副委員長","kind":"質問","question":"今回、印鑑登録証の件ということで、若干聞きそびれたところもあるので、そういうのも教えていただければと思います。これまでは紙媒体で印鑑登録原票を保存していたということですけれども、今まで多分、事故なく行われてきたと思うのですが、特に気を遣われた部分とか、費用がかかった部分とか、そういうものがあれば、少し教えていただければと思います。","respondent":"提坂戸籍住民課長","answer":"現在の住民登録とか印鑑登録が電算化されたというのは、約３０年前ですけれども、その際、システムダウンが頻繁に発生したということで、印鑑登録原票についても内容変更があったら、毎日内容を差し替えたりしていることがございまして、その後。","voiceIndex":43,"id":"exchange-017"},{"speaker":"浅野副委員長","kind":"質問","question":"ここのところがどうだったのかなというのがわからなかったので、教えていただいたのですけれども、それだけの作業があって、大変な何かをやられてきたということを改めて認識しました。その中で、光ディスクですか、こちらのものを使うということで、「調製」という、あまり聞きなれない言葉が出ていたので、どういうことかなと思ったのですけれども、今、大体認識はできました。","respondent":"提坂戸籍住民課長","answer":"今回のディスクをもって調製するということで、あくまでもこれは住民情報システムの中に格納するものでございまして、先ほどもご説明させていただいたのですけれども、データの監視センターで常に２４時間３６５日監視をしていくということと。","voiceIndex":45,"id":"exchange-018"},{"speaker":"浅野副委員長","kind":"意見","question":"万全な体制で臨まれているということで、安心できる状況だと思うのですけれども、品川区内でも２３区でも、いろいろと調製というのはどういう形で行われているのか、結構調べてみたのですけれども、条例などを読んでみると、結構早くからやられていたりとか、２３区外でも、地方のほうでもこういう形で調製をしているということが出ていたので、品川区の場合は満を持して。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどのご答弁の中で、ほかの委員とのやりとりの中で、マイナンバーの普及率が１５％弱というお話を伺ったと思うのですけれども、区内での普及率だったり、ここ何年間かの推移とかそういうのは、今もし数字があったら教えていただきたいなと思うのですけれども。","respondent":"提坂戸籍住民課長","answer":"ですから、差し引くと平成２９年度１年間と５月末までで、１万数千人の申請があったということで、少しペースは落ちていますけれども、着実にマイナンバーカードの普及は進んでいると考えています。","voiceIndex":48,"id":"exchange-020"},{"speaker":"のだて委員","kind":"意見","question":"反対です。マイナンバーのように個人情報を番号によって一元管理する制度は、アメリカでも行われておりますけれども、ほかの国でも行われておりますが、プライバシーの侵害ですとか、詐欺やなりすまし、犯罪にも利用されておりますので、この制度は廃止にこそすべきであって、普及させるべきではないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"印鑑登録原票の電子化については、流れとして賛成したいのですが、個人番号カード、マイナンバーと、印鑑登録証の一元化については、やはり情報漏えいの危険性が高まることなどが考えられることと、生活者ネットワークは個人番号制度に反対をしているため、こちらのほうは反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-022"}]},{"id":"topic-02","title":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"振り込め詐欺などの例は、ずっと気をつけてくださいということで啓発を続けてきていると思うのですけれども、どうして件数や被害額が倍以上になってしまったのか、区の認識を伺いたいと思います。先ほども、設置したところでは被害がないというお話もありましたが、もう少しほかに、この自動通話録音機を設置する効果について、あれば伺いたいと思います。","respondent":"菅生活安全担当課長","answer":"この自動通話録音機を設置しているということを犯人側が認識することで、この家は防犯意識が高いというか、警戒しているなということを知らしめるという効果もあると考えております。","voiceIndex":62,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"情報が行き渡っていないという話もありましたけれども、そこのところは区としても、さらに注意喚起をしていただきたいと思います。手口がいろいろと巧妙化しているというところで、被害をどう防ぐかと考えたときに、まず話をしない、通話をしないというのが、一番重要かなと思いますので、ぜひこれについては、その対策の一助になると思いますので、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"今回、補正予算になったのは、都からの補助金が入ってきた時期とか、そういうことで補正になったのかということと、被害発生状況についてなのですけれども、これは固定電話に限った被害状況の数字なのかということを聞きたいです。区内で被害が出ているところの地域性とかはあるのか、もしもわかれば、これも教えてください。","respondent":"菅生活安全担当課長","answer":"地域性ということなのですけれども、細かい住所とかそういうものは追えませんが、警察署単位でいきますと、品川警察署と大井警察署管内におきまして２３件ずつ発生をしておりまして、大崎署管内では８件、それから荏原警察署管内では２９件という状況になっているものです。","voiceIndex":65,"id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"今、発生の地域性というところで数字が出てきたのですが、効果的な貸与の考え方というのをどういうふうに考えているか、どうやって貸していくかというところをお聞かせいただきたいと思うのと、これは多分、前も何かで聞いたときに、５００台つくると５００台、大体出ていくというところでいうと、この効果があるのであれば、区民の財産が１億６,０００万円なくなるというところでいうと。","respondent":"菅生活安全担当課長","answer":"それと、一気に台数を増やしたほうがいいのではないかという考え方は、確かにあるかと思いますけれども、これは東京都の予算を使って、補助金を活用するということでもありますし、また、各警察署とも連携しながら配布をしていくということでございまして、あと。","voiceIndex":67,"id":"exchange-026"},{"speaker":"大倉委員","kind":"質問","question":"それはわかるのですが、本当に区民の財産がこれだけ犯罪に奪われているというところを考えると、納期の問題はありますが、コスト的には非常に効果があるのではないかなと思うのです。納期とか、区の、都の予算がとかいうことではなくて、品川区としてどうやってこの財産を守っていくかということを、効果があるわけですから、今後どうやっていくかというところだけ、最後に教えてもらえれば。","respondent":"菅生活安全担当課長","answer":"台数につきましては、増やせれば増やしていきたいと考えておりますけれども、中には電話の回線の問題で、どうしても設置できないご家庭もあったり、あるいは、いろいろなセキュリティ機器をつけていることで設置できないとか、あるいは。","voiceIndex":69,"id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"自動通話録音機の周知はどのようにされていたのでしょうか。すみません、そこだけ確認させてください。","respondent":"菅生活安全担当課長","answer":"区のホームページでも周知をしていましたが、広報紙でも自動通話録音機を入荷次第、また掲載することにしております。","voiceIndex":71,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"当事者の６５歳以上の方たちに、確実にというか、届くような周知方法というのは、どのようにされているのかというのを伺いたくて、ホームページもなかなか開いたりしないのかなとも思うので、どのような工夫がされているのか、そこだけ聞かせてください。","respondent":"菅生活安全担当課長","answer":"これは各警察署にも配布をするということでございまして、各警察署で実施をしております区の高齢者を対象とした防犯講話といったところでも、紹介をしていただいておりますし、また、民生委員協議会におきましても。","voiceIndex":73,"id":"exchange-029"},{"speaker":"浅野副委員長","kind":"質問","question":"ほとんど質問は出てしまったのですけれども、１点だけお伺いしたいのが、こちらの録音機につきまして、例えばその方が転居したとか、そういう場合もあると思うのですけれども、このような場合に、形は貸与なので、基本的に自動通話録音機は返却をするものだと考えているのですけれども、このようなケースについてはどのような対応をされているのか、されていくのか、教えていただければと思います。","respondent":"菅生活安全担当課長","answer":"転居した場合なのですけれども、同じ品川区内であれば、特に問題ないかなと考えています。","voiceIndex":75,"id":"exchange-030"},{"speaker":"浅野副委員長","kind":"質問","question":"貸与ということなので、確かに戻さなければならないという状況になるかと思うのですけれども、知らない間に転居した場合、どうしようもないかなと思うのですけれども、この場合まで追いかけてというのは、転居先がわからない限りは難しいかなと思いますけれども、この点についてはいかがでしょうか。","respondent":"菅生活安全担当課長","answer":"最初に貸与するときに、一応説明書といいますか、取り決めといいますか、他の区に転居するときには返却してくださいということは説明をしておりますので、その辺は、信じるしかないと考えているところです。","voiceIndex":77,"id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"これは、私はすばらしい施策だと思っているのですけれども、１点、貸し出しっ放しが一番よくないと思っているのです。だから、せめて貸し出した後、１カ月後ぐらいに１回電話を入れて、きちんと稼働しているかという確認はするべきだと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"菅生活安全担当課長","answer":"それと、電話の確認ということなのですけれども、一応、実際に取りつけていただいてから、本当にその機能がきちんと使えるかどうかは、今後対応していきたいと考えております。","voiceIndex":79,"id":"exchange-032"},{"speaker":"田中委員","kind":"確認","question":"すみません、先ほどの質疑にもあったのですけれども、貸し出して、お引っ越しされた場合とかの返却率というか、今どのぐらいきちんと返ってきているのかなというのを確認したいのですけれども、どうなのでしょうか。わかる範囲で教えてください。","respondent":"菅生活安全担当課長","answer":"返却率ということなのですけれども、実際に転居によって返却したものだけというのは、統計をとっていませんのでわかりませんけれども、それよりは、どうしても機器自体の故障とか、そういった形で返却されているというのが、平成２９年度でいきますと。","voiceIndex":81,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2812#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":22402,"voices":96}},{"id":"h30-20180702-7","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"厚生委員会","time":"午前１０時００分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"第５３号議案のほうの現行で言うホテル営業、旅館営業、簡易宿所営業、下宿営業と４つあるのですけれども、これは区内に何軒、幾つあるかということがわかれば教えていただけますか。","respondent":"鈴木生活衛生課長","answer":"平成２９年度の数字になります。旅館業の中でホテルが４５軒、旅館営業が２２軒、簡易宿所が１７軒、下宿は今、０軒になっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"それぞれ数を聞いたところで、今度、第５４号議案のほうは、改正理由のところに、同日付で構造設備基準などの目安を示した技術的助言ということで、「旅館業における衛生等管理要領」についても改正されたということなのですけれども、この技術的助言というのはどういうことなのか、こういった助言があるということは、区にとっては重みがあるものなのでしょうか。その辺を教えてください。","respondent":"鈴木生活衛生課長","answer":"国の技術的助言に当たる要領ですが、これは具体的な衛生管理または指導をする上で必要な内容を記しているものなので、負担というよりは、具体的な実務に役に立つ基準になるものを示しているものだというふうに認識しております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、助言、役に立つ基準の助言ということで、そこまで区が変えなくてもいい内容、お願いされているぐらいで、そんなに変えなくてもいい内容というものではなくて、こういうふうにどこの区でも旅館業に関する条例の一部をこのように要領にあわせて変えなければいけないものなのか、それともその助言をもとに、ある程度、区で変えるところを選べるというか、選定していけるのかを伺います。","respondent":"鈴木生活衛生課長","answer":"この要領につきましては、もととなる法または政令の基準をさらに詳しく具体的に示すものですので、義務づけられる法令のような強制力はございませんが、基本的には、実務上はこれに準じたものにするというのが基本的な考え方になりますので、ほかの各区。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、区はこの要領によってこの条例を大きく変えているわけですけれども、改正内容のところに、「旅館業法等の改正に伴い」というふうにあるのですけれども、この「等」の中身はどのようなものがあるのか、どのような中身なのか伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"法令等の中に含まれるものですが、第５４号議案の説明資料の１番の改正理由にありますように、旅館業法、旅館業法施行令の政令、旅館業法施行規則の省令、それと管理要領、法律ではありませんが、衛生等の管理要領、これを含めて「等」という表現にしております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、この施行令、施行規則、そして衛生等管理要領が「等」の中に入っているということなのですけれども、これがそれぞれ中身がどういうものなのか簡単に教えていただきたいと思います。だから定めていたのだなというふうに感じたのですけれども、これだけ変わってしまって、そしてこれ、すごく民泊に近づけている感じがするのですけれども、民泊との違いはどういうところなのかを教えてください。","respondent":"鈴木生活衛生課長","answer":"改正の項目が多岐にわたっていろいろ変わるですが、これが最初の質問の旅館業法や政令等の改正の中身と同じ項目を同じように修正をかけたものですので、基本的には先ほどまとめた４項目が主な改正の内容で。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは民泊のことではないのですかと思ったのですけれども、この旅館業の条例の改正の中に入っているのはなぜなのかを伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"実際に６月１５日に住宅宿泊事業法が施行されて、３月から引き続き届出を受けておりますが、それとあわせて、簡易宿所も今、こちらは許可になりますが、二、三軒届出の手続にいらっしゃっておりますので、そちらの規定ということになります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、簡易宿所という新たな宿泊形態への対応ということなら、私、ちょっとわからなかったのですけれども、旅館業で申請するものが、戸建て住宅や集合住宅の１室を活用してできることになっているということですか。では、この独自の規定がなければ、何もなしに戸建て住宅や集合住宅の１室を活用して、新たな宿泊形態ができる形に今はなっているから、この独自規定を設けたのですか。","respondent":"鈴木生活衛生課長","answer":"ただ、本来のホテルや旅館という大規模な施設での旅館業が中心だったのですけれども、民泊などの影響もあって、簡易宿所のような戸建てとか集合住宅の一室を活用するという形態も出てきているという意味でございまして、民泊のことを差すわけではございません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"旅館業法ですからそうですね。数値で規定されていたものが緩和されていく、緩やかになっていく。それをすることで、旅館やホテルが、要は、この旅館業にかかわる者が品川でも増えていくということを見通して、品川での見通しをどうお持ちかなと、今も簡易宿所の手続が二、三軒、来ているということなのですけれども、こういった規制が緩和されたもとでのホテルや旅館が増えていくのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国が進めているのは、そういう観点からこの規制改革推進会議というのですか、そういうものも開かれて、そういった民泊との取り合いというところからも懸念があるから改正していくのだというふうに言われているので、こういった規制が緩和され、旅館業法の中ですけれども、その中でも快適に安全に宿泊できる環境が少しずつ緩めていかれてしまうのだなというふうに私は理解をしているのですけれども、でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、これもこの条例に合わせて、きっと緩いものに緩和されていくのかと思うのですけれども、この中に用途地域もあるのです。見方が複雑でよくわからなくて、なので、多分住居専用地域とか準工業地域とか、そういう形での用途地域、旅館・ホテルが建てられる地域を教えてもらいたいということだったのですが、ここの要綱も変わっていくのかということと、もう１回、用途地域を伺いたいです。","respondent":"鈴木生活衛生課長","answer":"先ほどからご説明しておりますように、規制が緩和されたのは、国の動きのところの丸ポチの３つ目の後段ですが、「感染症対策及び利用者の安全等に必要な規制以外の」、設備の基準は緩和です。ですので、営業関係、そもそもの許可を取ったりだとか、用途地域の変更はございません。","voiceIndex":30,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"確認","question":"そこはわかっています。だから、用途地域が変わっていないというのはわかるのですけれども、その用途地域が、今現在、ホテル・旅館が建てられるところはどこなのかということを確認したかったのですけれども、それはわかりませんか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは複雑で、聞けたらいいなと思って伺ったのです、すみません。わからなければ、では、いいです。で建築のほうに聞いてみますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"},{"speaker":"若林委員","kind":"提案","question":"なので、それが定性的なものになった、そこはきちんとこれまでどおりといいますか、しっかりとした基準を持って、区もチェック体制も含めて、この条例を提案しているのですというところの担保のところ。規制緩和されたけれども、そこはこれでしっかりと担保されていて、旅館業法の目的に沿って品川区の条例もつくられていくのですと、安心できるご説明をいただきたいと思うのですけれども。","respondent":"鈴木生活衛生課長","answer":"今、ご質問の中でもご指摘がありましたように、あくまで数値的な表現だったものが定性的な表現に変わったという部分ですので、その数字の具体的な、例えば照度、明るさだとか、トイレの数だとか、そういうものは数字の規制自体はなくなりますので消えますが。","voiceIndex":34,"id":"exchange-013"},{"speaker":"若林委員","kind":"確認","question":"本当は「旅館業における衛生等管理要領」、この中身も象徴的なところ、ポイントをご紹介していただきながらご説明ということが本来あってもよかったのかなと思うのですけれども、それはもしあれば、今のご説明で私としては納得できるところですけれども、そこの確認と、あとは、今後の品川区の検査体制といいますか、ここら辺もしっかり行っていくというところも担保をとっておきたいと思います。","respondent":"鈴木生活衛生課長","answer":"今回、直接この改正の内容ではございませんが、旅館業法も住宅宿泊事業法も、今までは保健所の権限として書類の提出を求めて指導するというところまでだったのですが、今回、立入検査の権限も付与されましたので、よりしっかりと監視業務、指導業務を続けながら。","voiceIndex":36,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１点だけ。さっき、手数料条例のときに、申請件数等のお話があったのですが、平成２９年度とおっしゃっていたのですけれども、平成３０年に入ってから簡易宿所の申請はどのぐらい出ているのですか。もしわかれば、４月以降、状況を教えてもらいたいと思います。","respondent":"鈴木生活衛生課長","answer":"４月以降、簡易宿所は、私の手元の決裁を通過した件数で記憶しているのは、現在、２件です。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今の説明の資料のところで、４番のところで関連規則の改正というところでは、条例の施行規則は改正するということでご説明がありましたけれども、先ほどから出ている品川区旅館業に関する条例等の運用基準を定める要綱ということで、要綱の中でかなり詳しく今までの規制の中身をさらに詳しくという形で、例えば帳場は今度なくしますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは公園の存する用途地域というふうなことでなっているので、住居専用地域、工業地域、工業専用地域のところでも、隣接したところに公園があると、ここの要綱を見ると、それから、国の要領を見ても、１１０ｍ離れることとかというふうなことが基準として書いてあるのですけれども、そういうことからすると、この不可能地域も公園が隣接した場合は、そこのところから１１０ｍ離れていれば可能ですという。","respondent":"鈴木生活衛生課長","answer":"要綱の改正ですが、ご指摘のとおり、条例施行規則等を改正した後に、それに合わせた改正が必要な部分については、今後、作業を進めていく予定です。","voiceIndex":41,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そういうふうなところは、こういうふうに客室は４０ルクス以上とか、明るさはこういうふうなものとか、調理場を設置することとか、そういうふうな基準が今まではクリアするものが必要だったけれども、今度はそういうふうなことのチェックはなしに許可が出るという、そういうことで考えていいということなのでしょうか。","respondent":"鈴木生活衛生課長","answer":"先ほどからご説明しているように、具体的な数値ではなくて、質の担保ということで定性で規定をしておりますので、そこのチェックは行います。","voiceIndex":43,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"ということは、今まで基準として数値的に確認をされてきた、例えば１人当たり３.３m2とか、そういうふうなところで、この部屋には何人泊まれますみたいな、そういうふうな規定があったわけですけれども、そういうふうなことは取り除かれるので、そういうところのチェックはないし、それから、炭酸ガスですとか、採光ですとか、照明とか。","respondent":"鈴木生活衛生課長","answer":"ご指摘のとおり、数字的なチェックではなくて、設備が衛生や安全を確保できる状態にあるかどうか、法の表現に合わせた設備になっているかというチェックになるです。","voiceIndex":45,"id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"意見","question":"今、いろいろ説明がある中、聞いていても、やはり規制の緩和だということがわかりました。不安です。そして旅館業を営む全国旅館ホテル生活衛生同業組合の皆さんは、たとえ１日であっても、お客さんの命と財産を預かってお泊めするのが宿泊サービスであると。ですので、それを緩和する、こうした皆さんの思いとも逆行するし、そのとおりだと思いますので、共産党はこれに反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-020"}]},{"id":"topic-02","title":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"心身障害者医療費助成制度システム改修について伺いたいのですが、この資料で目的のところの最後のほうに、障害者福祉システムの改修を行ってこの制度を進めていくということなのですけれども、障害者福祉システムというのは、どこにあるもので、どういうものなのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの障害者福祉システムは、障害者福祉課の中にございまして、主に福祉係、こちらの医療費助成制度あるいは手当等を管理しているシステムです。","voiceIndex":64,"id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"２の内容のほうに行きたいのですけれども、今現在、身体障害者手帳１・２級の所持者の方、そして内部障害は３級までと、愛の手帳１・２度所持者の方がこの助成制度を受けているということですけれども、それで今回、精神障害者保健福祉手帳１級所持者が新たに対象になったということなのですが、それぞれの人数を伺いたいです。現在受けてこられた方が、要は、いわゆる助成制度はマル障ですね。","respondent":"松山障害者福祉課長","answer":"申しわけございません、東京都の把握ということになっております。精神障害者については、全てまとまってしまっているのですが、手帳の保持者としましては２,０７５人となっております。そのうち１級で、現在のマル障の対象者につきましては５５人の方が対象です。","voiceIndex":66,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今回の新たな対象の精神障害者保健福祉手帳の１級で、マル障の対象になる方が５５人。そうすると、手帳所持者はもうちょっといるということですか。","respondent":"松山障害者福祉課長","answer":"今回、１級の方が追加されますので、先ほど申した数字は２級、ほかの等級の方も含めてということになります。こちらでつかんでおりますのは、現在１級の方が５５人で、新たに平成３１年１月１日から開始されますので、その間に新たに申請される方が追加される可能性はあります。","voiceIndex":68,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですけれども、今回のものは品川区の障害者福祉課で受付というふうに書いてあるのですけれども、今までの１・２級の方とか、愛の手帳１・２度の方は、品川区申請ではないのですか。品川区にて受け付けられてはいないのですか。","respondent":"松山障害者福祉課長","answer":"精神の手帳の申請は各保健センターなのですけれども、今回、こちらの医療費助成制度につきましては障害者福祉課ということで、東京都からは５５人というご報告が来ています。","voiceIndex":70,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひマル障の受けている方の数も把握していただけたらと思うのですけれども、そうすると、今回対象になられる方は、この自己負担のところです、住民税非課税者の方は自己負担がなしですけれども、皆さん自己負担なしの方、ある方もいるのか、ここを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"もちろん住民税課税の方は１割負担です。","voiceIndex":72,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"意見","question":"１割負担なのですけれども、今回の新たな対象者になる精神障害者保健福祉手帳１級の方の中で住民税課税者、要は、自己負担が発生する方はいるのかどうかということです。","respondent":"松山障害者福祉課長","answer":"まだそこまで詳細には把握してはございません。","voiceIndex":74,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"確認","question":"わかりました。直接本人にしっかりと周知がされたのかどうか、区は確認しているでしょうか。伺います。","respondent":"松山障害者福祉課長","answer":"個別に周知されたのかにつきましては、東京都から個別に発送を対象者の方全員に６月中旬に周知をされているという連絡は東京都から受けております。","voiceIndex":76,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"議員必携で予算の補正を調べますと、補正予算は当初予算確定後のいろいろな政治、経済、社会情勢の変化によって既定の予算に追加し、あるいは変更を加える必要が生じたときにこうした予算編成をするのだということで、例えばということで、災害発生によって必要になった予算措置だとか、国や県の補助金、負担金、交付金の確定がされたからだとか、地方債の合意の見通しが確実となったとか。","respondent":"松山障害者福祉課長","answer":"この度、障害者福祉課だけではなくて、高齢者福祉課関連、あるいは在宅介護支援センターを含めまして、関係機関との調整の見込みが立ったというところで、いち早く相談支援体制をつくり上げるために補正を上げさせていただいた次第です。","voiceIndex":78,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"補正予算のところでの今の相談支援体制の課題が、今、課長もおっしゃられたのですけれども、資料のところの目的に、地域共生社会の実現のため、この相談支援体制を早期に構築するというふうにあるのですけれども、相談支援体制が不足している、そういうことからではなく、地域共生社会の実現のためというところからのこの体制の構築ということの意味を教えてください。","respondent":"松山障害者福祉課長","answer":"いずれにしろ地域はさまざまな方々がお住まいですから、いろいろな課題に対して、世帯丸ごと対応できるような形で地域の相談支援体制を目指してつくっていこうというものです。","voiceIndex":80,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これを業者に委託するということなのですけれども、この業者はどういったところなのか、もう決まっているのか、決まっていれば教えていただきたいと思います。それから、区としての現状把握、課題の整理・分析・評価検討、これは区としてもやられているのか、区がやるべきだと思うのですけれども、そこはいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"２点目につきましては、区といたしましても相談件数や相談内容は把握しておりますが、まだ分析までは至っておりませんので、専門知識を備えたところから知見をいただきながら、分析または整理ということを、区は全く業者に投げるわけではなくて。","voiceIndex":82,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この業者は、専門的知識と技術を有する業者ということなのですけれども、例えば、どういうところなのか、私たちは全くイメージできないのですけれども、今までも区と関係があったところなのであれば、どういうところなのかを、決まっていないのですけれども、例えば言えるのであれば教えていただきたいです。","respondent":"松山障害者福祉課長","answer":"まだ本当に決まってはおりませんので、ただし、品川区の高齢者の在宅介護支援システムの実情、あるいは障害者の今の実情をきちんと踏まえてできる事業者を考えております。","voiceIndex":84,"id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですけれども、その前に、やっぱり委託をする前に、私は区として現状把握、課題の整理、分析、そして評価検討をしていくべきだと思うのですけれども、もう体制が、こういうイメージ図ができている、検討するのに、もうイメージができているというのが、ちょっと理解ができなくて、どのようにこういった業者に検討を投げようとか、あとはこうしたイメージ図をつくろうとか、そういうものはどこで、誰が。","respondent":"松山障害者福祉課長","answer":"こちらのイメージ図につきましては、特に業者がということではなく、区のほうできちんと部の中で、高齢と障害部門が一緒になって話し合って、こういうイメージを持って具体的にやっていきましょうというところで決まったものです。","voiceIndex":86,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"それがどういう形で検討して、現状把握や課題整理や分析や評価検討がされて、こういうイメージが出てきたのかという、これを進めるに当たっての報告ではないですけれども、こういう課題を持っていて、そしてこう分析して、こう検討するのだという区側のそういったものが出てきていないので、何だかこういった全部を業者に丸投げみたいな感じになるのですけれども、こういったイメージや。","respondent":"松山障害者福祉課長、石田（秀）委員長","answer":"このように障害特性に応じた支援を充実を図るとともに、高齢者福祉課との福祉分野との連携というのは重要と考えておりまして、平成２８年度から高齢障害ということで検討を進めてきております。これは補正予算の審議ですので、中身についてはそこで十分できると思いますが、補正予算についての質疑は、それはそれとしてとめるものではありませんが、あまり中に入って、これがどうだ、今の段階でこうだという部分と。","voiceIndex":88,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に。ですので、詳しく聞きたいと思っているのです。このイメージ図がそういうふうに思わせるわけですから。そこをしっかりしていかないと、業者に投げて、こういう形で進めたいと言ったところで、今の相談支援体制がどういうふうになっていってしまうのかという思いなのですけれども、そうした自立支援協議会、また当事者の皆さんとの関係での現状把握や課題整理はどのようにされているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"今はこのイメージのところにあるように、福栄会とグローと品福という３つしか実質動いていないですけれども、品川区にはあります。そうした稼働していない指定特定相談支援事業所にも、今あるのですから、そこをしっかり稼働させていくという検討なども必要だったのではないかというふうに思うのですけれども、その辺はどのように考えてますでしょうか。","respondent":"松山障害者福祉課長","answer":"指定特定相談事業所として登録はされているのですが、実績がない民間の事業者につきましても、どのようにしたら稼働できるのかというのは働きかけていく予定です。","voiceIndex":94,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"台場は株式会社ジャパンケアサービスです。東品川は福栄会、東品川第２は株式会社ホームヘルプサービスです。そうすると、この品川地区の場合も相談支援事業をする事業所はどこになるというふうなイメージなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-036"},{"speaker":"こんの委員","kind":"確認","question":"イメージを持つために確認をしたいと思いますけれども、１つは、この新体制、私は、共生社会をつくるためには、介護の分野と障害の分野と、今までそれぞれに対応されていたのが、交わるようで交われなかった部分が交わっていくということは非常に大事なことだろうというふうに思います。そうしたときに、例えばどういうケースを想定されて、こういうことができてきたのかという確認です。それが１点。","respondent":"松山障害者福祉課長","answer":"ケースの想定です。１つは、先ほど申しましたように、高齢の介護者、例えば７０代、８０代ぐらいの高齢の介護者で、その方も要支援で、５０代、６０代の障害者のお子さんがいる、そういったケースはかなり地域には多いです。","voiceIndex":101,"id":"exchange-037"},{"speaker":"こんの委員","kind":"確認","question":"もう１つが、いわゆる品川区としての体制と、他の自治体と少し比べたことで確認をしたいのですが、全国初と言っているところが、品川区としては、地域包括支援センター、これは区として置いてある。その連携と、区が持っている地域包括支援センターで連携をとる、ここが違うというところで全国初というふうに理解していいのか、そこら辺のところをもう少し教えていただけますでしょうか。","respondent":"松山障害者福祉課長","answer":"プレスの中での全国初という意味合いですが、委員ご指摘のとおり、やはり品川区の場合、直轄で地域包括支援センターを持っているというところで、ケアプランについても７割５分くらいの方々の高齢者のケアプランを区が把握しているということで。","voiceIndex":103,"id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたケアプランまで作成をして、なおかつ、介護も必要な部分も一緒に見ながらというのは非常に大事なことだなというふうに思いますので、どうか品川区に地域包括支援センターを置いているということは、課題も、それから評価も、分析としてデータを集めやすいということがあるかと思いますので、しっかりそこら辺のところを集めた上でこれを進めていただきたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"意見","question":"１点だけ。この障害者相談支援のものをつくっていく対象として、今の最後のご答弁の中でもご高齢のケアプランというお話だった。この障害者相談というところに、高齢ではない方がどういうふうに理解をしていくか、表現の問題なのだけれども、若い人もここの相談支援センターへ行ってしまっていいのかという、そこの仕切りがどうなっているか。言葉の問題なのだけれども。","respondent":"松山障害者福祉課長","answer":"名称のことだと思うのですけれども、確かに高齢者の在宅介護支援センターというところに若い方もどうなのかというところなのですが、そこら辺の課題につきましても、あるいはどうやったら地域に根づくかという、地域の方が行きやすくなるだろうかということを考えますと。","voiceIndex":106,"id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"意見","question":"若い人も全て受けるという部分でいいというふうに判断したのか、それともさっきのご答弁が、ケアプランをつくるというほうに入ってしまったから、そこがどうかなと。","respondent":"松山障害者福祉課長","answer":"そちらにつきましては、今後、種別あるいは年齢等ありますので、今後、高齢者福祉課といかに在宅介護支援センターとヒアリングをし、どこら辺から始めていくのかということにつきましても、今後、検討課題にはなってくるかと思います。","voiceIndex":108,"id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうことからすると、１２０人くらいが対象者になるのではないかと思うのですけれども、その確認をさせていただきたいのが１点です。全体の数でも結構です。","respondent":"松山障害者福祉課長","answer":"医療費助成のことなのですが、平成２９年度末で対象者が２,５８９人、そのうち申請件数としては１,９９２人の方がご申請いただいております。","voiceIndex":110,"id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そうすると、認定のときにだけこれがかかるというのではなくて、もう既に認定されていて、２年目の人も対象になるということで、１２０人ぐらいが対象ということで考えていいということなのかの確認と、それからあと、心身障害者の医療費助成制度というのは、東京都の制度だと思うのですけれども、この医療費の負担は、全部、東京都がもつということでなっているのか、そこの仕組みの、国の負担は全然なくて。","respondent":"松山障害者福祉課長","answer":"先ほどの委員ご指摘のとおり、１２０人ぐらいが対象だです。それから、東京都の負担ですけれども、健康保険に加入しているときに、マル障も一緒に医療機関に提出することにより一部負担金があるということなので、一部負担金を除いた総医療費と保健給付費との差額を助成するです。","voiceIndex":112,"id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。もう１つ、障害者の包括支援相談体制の構築検討についてですけれども、１,２５０万円が予算になっていますけれども、この内訳、どういう内訳になっているのかということを１点お聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"ほとんどが人件費ということになるのですけれども、現状把握、分析のあたりで４２０万円ほど、研修体制や研修プログラムを立案するサポートもしていただきますので、それが４００万円ほどになっております。その他は成果報告書等々になっております。","voiceIndex":117,"id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そこの中に研修プログラムというのも入るということなのですね。では、品川区独自にこの計画相談を組むケアマネジャーというか、相談支援員を養成していく、そういうプログラムをつくる経費が４００万円という、そういうことなのでしょうか。","respondent":"松山障害者福祉課長","answer":"こちらにつきましては、現在のところは、かわるものについては情報収集を行っているところですが、こちらで書かせていただいている研修プログラム等の立案に関しましては、ただ単に在宅介護支援センターに新しい相談支援員を配置するだけで、現実的には、実際。","voiceIndex":119,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ということは、品川区の体制の中でどういうふうにしてスムーズにいくために研修をするかというプログラムをつくっていくのに４００万円という、そこまで検討がされているということなのですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"こういうふうな感じに、ここのところの提案が出てくるというのであれば、それなりにどのような現状、そしてどのような課題で、どのような分析、そしてこれが出ましたという、そういう形にしていただかないと、なかなか、なぜというふうな感じがするのですけれども、そこら辺のところの自立支援協議会とのかかわりとかも含めて。","respondent":"松山障害者福祉課長","answer":"先ほども補正の理由のところで答弁させていただきましたけれども、地域の当事者の声というのは、もう既に聞いております。高齢障害の部分についても課題があることは認識しておりまして、平成２８年度から高齢障害のことを検討しております。","voiceIndex":122,"id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどちょっとお伺いしたのは、自立支援協議会の中の相談支援部会とかというのもあると思うのですけれども、自立支援協議会の部会が、どのような議論をしているかということが公開されていないので、ちょっとわからないので、それはぜひ公開してほしいというのは、団体の皆さんからも要望されていることですので、今後に向けて検討していただきたいと思います。","respondent":"松山障害者福祉課長","answer":"それぞれの部会につきましては、相談支援部会というよりは、こちらの相談支援体制については、やはり高齢者関係の在宅介護支援センターの現場のほうともきちんと意見交換をしなければならないですし、相談支援部会につきましては、やはり相談のあり方につきまして。","voiceIndex":124,"id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"相談支援マニュアルとかは本当に大事なことだと思いますので、それはそれで進めていただきたいと思うのですけれども、でも、相談支援の体制がこのような状況になっている中で、何が課題なのか、それをどう解決していくことが必要なのかというところが一番大事なところで、そこのところは本当に当事者も入れて、どうあるべきなのかという、当事者というのは一部の当事者ではなくて、当事者をもっと広く。","respondent":"永尾福祉部長","answer":"ですので、今年度、まだこれから検討をするので、そのときに当事者のお声はもちろん、自立支援協議会だったり、相談支援部会には、専門の施設の相談支援の方も出席していますので、そういう方のご意見、また皆様議会のご意見。","voiceIndex":126,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"心身障害者のほうのマル障の対象が広がったというのはすごく求められていたものですし、いいのですけれども、やっぱりこちらの在支でやられている相談支援体制、検討はすごく必要なことですし、進めていくべきなのですけれども、やっぱり図が出てきていて、そこで在支ありきで進めていくという感じがすごくしまして本当に不安です。ですので、そうした立場から、この補正予算には反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-050"}]},{"id":"topic-03","title":"第４９号議案 品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"第４９号議案 品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"特養ホーム等は居ながら工事ということで、デイサービスが移転。移転先は２００m2で、今、移転するデイサービスは利用定員が３０人だと思うのですけれども、それも変わらずできるということでした。特養ホームとショートステイのほうの定員の変化はあるのでしょうか。伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"ショートステイのほうは、法人内の他の施設の利用、それから、その他の法人との連携等により、こちらでのショートステイは基本的には工事期間中はやらないという予定で今のところは計画しています。","voiceIndex":139,"id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、７２人の特養が５６名になっていくと、１６名の方はどういう形になるのか。それと、ショートはやらないということになるということでしたか。他の法人でということですけれども、今のショートステイの利用状況というのでしょうか、要は、空きがあるのか、今現在、戸越台を使われているショートステイの方が今までどおり利用したいときに利用できるような利用状況になるのかということを伺います。","respondent":"寺嶋高齢者福祉課長","answer":"この辺は全庁的にも検討したところですけれども、やはり現実的な問題、例えば移転先、これは中学校もありますので、そう簡単に見つかるものではありませんし、金額等も含めまして、現実的にこのやり方が。","voiceIndex":141,"id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"確認","question":"それと、今回ここの戸越台中学と特養の複合施設が大規模改修ということなのですが、ほかの特養ホームとか施設の改修の計画は、この戸越台は中学と一緒だから今の時期なのか、改修の時期の関係です、この戸越台特養のもっと前にできている特養ホームが、成幸ホームとか、かえで荘、晴楓ホームとかあると思うのですけれども、そういうところの改修というか、そういった計画は何か組まれていたり。","respondent":"寺嶋高齢者福祉課長","answer":"１点目、今のご利用者が困るようなことにはならないということは、それは万全を期して対応するよう、区も法人も考えているところです。","voiceIndex":143,"id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今の時点では、来年、再来年とか、近いうちに改修を予定または計画するようなところは、今のところはないということでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"それからあと、荏原複合施設については、どうも空調系の不具合が少し目立ってきていて、夏の時期等に空調がきかないということだと利用者が困るので、荏原のほうは今年度から空調関係を中心に大きな工事が入るという予定はしている。","voiceIndex":145,"id":"exchange-054"}]},{"id":"topic-04","title":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、もうちょっと資料の充実をお願いしたいと思うのですが。税法上の特別控除がここには適用されていないのだなと思ったのですけれども、では、適用されているものは、いろいろあるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"認知症のところの資料をいただいた新旧のところですけれども、２項、３項ができたということで、姿勢や配慮が加わったと先ほどあったのですけれども、でも、この２項などは、認知症の方に「適切な保健医療サービス及び福祉サービスを提供するため、認知症の予防、診断及び治療並びに認知症である者の心身の特性に応じたリハビリテーション」、中身としては。","respondent":"寺嶋高齢者福祉課長","answer":"こちらは今回の改正の部分と直結する部分ではなくて、法改正そのものの内容なので、これは当然全ての保険者が取り組むべき、「努めなければならない」というふうに２項、３項とも締めくくっていますので、努力義務という位置づけにはなっているのですけれども、当然。","voiceIndex":170,"id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからあとは、そういう資格で実際に働いているヘルパー、今までの資格といったら、ヘルパー２級以上が身体介護ができるということになると思うのですけれども、そういうものでない資格で働いている方は、品川でも実際にもういらっしゃるのかどうなのか、その点をお聞かせいただきたいのと、それから、生活援助のみを行うことができる研修課程と。","respondent":"寺嶋高齢者福祉課長","answer":"内容については、項目は、今やっている項目とほぼ一致しているのですけれども、おそらく１つずつの深さが違ってくるのであろうということで、例えば、副委員長がおっしゃったヘルパー２級相当みたいな今現在の資格なのですけれども、項目としては。","voiceIndex":172,"id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"たしか今までも訪問介護の資格は１３０時間の受講をすれば、試験とかはなくて、受講するとその資格が取れたと思うのですけれども、今でもそれは変わらないのか。そしてもう１つ、生活援助のみの研修課程は５９時間ということなのですけれども、それについても、それを受講することで資格が取れるという、そういう資格なのか。","respondent":"寺嶋高齢者福祉課長","answer":"それから順番が逆になりますけれども、１点目ですが、１３０時間受ければ、それで誰でも資格が取れるかというふうな要項の書き込みにはなっていなくて、例えば、実習ももちろんありますし。","voiceIndex":174,"id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"(2)の部分ですけれども、今、定期巡回から夜間、これの区の訪問介護の方の充足率といいますか、訪問介護員は足りているか、足りていないかというところは、今、どのような感じで推移しているかだけ。","respondent":"寺嶋高齢者福祉課長","answer":"夜間対応につきましては、８５名という実人員が実績になっているということで、先ほど申し上げたとおり、ご希望の方につきましては、ケアマネとプランの中で相談して対応できているです。","voiceIndex":177,"id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"いずれにしても、このサービスはまた充実をさせていくという大事な２つの事業だと思いますので、そういう意味では、従事する方がもっと増えてほしいというのはあると思います。","respondent":"寺嶋高齢者福祉課長","answer":"すみません、ちょっと読み込みが不足している部分があったら申しわけないのですけれども、国がこういった形の研修を実施して段階設定をする場合のほとんどのものが、最初の研修に対して。","voiceIndex":179,"id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"私もそのようにほかの資料を見ている中で見ましたので、また一層の充実をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":181,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":47447,"voices":196}},{"id":"h30-20180702-8","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"建設委員会","time":"午前１０時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"自民党・子ども未来は、前例にのっとりまして、冒頭撮影のみということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":2,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"前例のとおり、頭撮りということで、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-002"},{"speaker":"松永副委員長","kind":"意見","question":"私たちの会派も、前例どおり、冒頭のみの撮影でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-003"}]},{"id":"topic-02","title":"第５５号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第５５号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の中にありますＤ地区には、いわゆる１９番地の超高層再開発が計画中なのですけれども、今回はまちづくりの実現性をより確実に担保するためと説明資料にありますが、地区防災道路等の規定と、壁面後退のルールが今回の条例化の中身になっているのですけれども、超高層ビルを建築する高さの規定や容積率などの規定については、どういうふうに条例化されるものなのか、伺いたいというのが１点です。","respondent":"長尾建築課長","answer":"今回条例化する内容につきましては、地区計画の中で定めた建築制限の全てを条例化するものではございませんで、ここに挙げております３つの制限事項についてのみ条例の中に位置づけるという内容となっております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"１点目のほうですけれども、全てを条例化するものではないということですが、今後、先ほど言ったような高さですとか、容積率の規定については、条例化の予定、見通しというのはどうなのかというのをお伺いします。この地区計画案というのは、２９号線の整備を前提としているということなのでしょうか。伺いたいと思います。そうしたお宅に対する支援策というのは何かあるのか、伺いたいと思います。","respondent":"長尾建築課長、東野まちづくり立体化担当課長、高梨木密整備推進課長","answer":"一番最初のご質問についてですけれども、地区計画の中で位置づけている建物の高さの制限であるとか、容積率にかかわる制限については。２９号線と重複する部分につきましては、再開発の中で整備していく。そこについては、公共施設管理者負担金という形での整備を考えてあります。大原通り拡幅により再建不可となる土地なのですが、既に大原通り、５ｍ台の後半、現況幅員がございまして。","voiceIndex":15,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。改めてこの問題というのが、地域の安全性に直結する問題だということが浮き彫りになったと思うのですが、今回、この地域では地区計画に定めるということですが、ルールを定めるということだと思うのですけれども、区全体で、生け垣にしていくというときに、助成制度があったかと思うのですが、その現状について改めてこの場でお伺いしたいと考えています。","respondent":"長尾建築課長、溝口公園課長","answer":"今回、条例化するものにつきましては３つの制限ということで、容積率や高さの制限に関しましては条例化する必要性がないということで、今回は３つ制限をかけるというものになっております。平成２９年度の実績といたしましては、４件となっておりまして、延長としては２３.５ｍやっております。長年続けている事業ですので、引き続き防災性の向上と緑化促進に向けて取り組んでいきたいと考えているものです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"すみません、もう少し事前に研究しておけばよかったのですが、条例化する必要性がないというところなのですけれども、とはいっても、現在の容積率が変更されたり、高さ制限、最高限度をつけたり、そういう変更があるわけですよね。それが今回の条例ではやらないにしても、どういうところで担保されるものなのかというのがわからないので、もう少しわかりやすく教えていただけると幸いです。","respondent":"鈴木都市計画課長","answer":"都市計画法に基づく再開発事業等については、高さですとか、あるいは容積率等々については、その都市計画の中で、手続の中で別個定めていくというものでございまして、今回の中身につきましては、このエリアの中の、今。","voiceIndex":22,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"その理由も教えていただきたいと思います。それから、敷地面積６０m2以下ということで、現状として、建て替えをしようという形、今、一つの敷地を細分化して建物が建てられるという傾向があるものですから、これは非常にありがたいことではあるのですが、実際、今、こういう状況でかかわってしまう、関係してしまう建物があるのかどうかということ、それと、次に、同様に制限がかかっている地域があるのか。","respondent":"高梨木密整備推進課長","answer":"この都市計画につきましては、今回、条例の制定ということで、建築課のほうからご説明をしていますが、都市計画といたしましては、冒頭ご説明させていただいたとおり、本年の３月７日に都市計画の決定告示をもって、効力を発揮しています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"一旦建ってしまうと、２０年、３０年、４０年までもつかどうかわかりませんが、そういう形でなかなか建て替わらないし、そこに居住されますので、ご理解をいただくというのは難しいところになると思うのです。なので、長期にわたっての区としての態度というものは明確にしていったほうがいいのではないかと思うのですが、それに対してのお考えをいただければと思います。","respondent":"高梨木密整備推進課長","answer":"ですので、各課題に沿ったやり方というところを、地域の現状に合わせて進めていきたいと考えております。","voiceIndex":33,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"要望も含めてですが、まちづくりを進めていく中で、結構簡単に道路の線を引っ張るのですよね。そうなったときに、６０m2という制限も、ある程度努力をしていくという形にしていかないと、地域の中でやると、やはり民地ですから、いやいや、細分化してたくさん売って、それでもうけたほうがいいよという形になってしまう可能性がある。そこで建て替えになると、５棟とか６棟とかたくさんできてしまうのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"今までの質疑も聞いておりまして、同じ観点からのものもあるのですけれども、細分化のところだけお伺いをしたいのですが、今年の３月から都市計画としては有効になっているというご説明がありましたが、都市計画の決定、変更に当たって、説明会等を開いていらっしゃるかと思うのですが、当該地区の方で、もしわかれば、どれぐらいの方が参加をされて、大ざっぱでいいのですけれども、要するに。","respondent":"高梨木密整備推進課長","answer":"両説明会につきましては、この地区計画と補助２９号線沿道の都市計画変更、それと、戸越５丁目１９番街区の再開発に係る都市計画をあわせての説明会となっております。","voiceIndex":37,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"一緒に先ほどお聞きすればよかったのですけれども、その中で、細分化の防止策に関して、どちらかというと、嫌だという意見は出たのかどうか、伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"説明会の中では、６０m2に関する賛成、反対というようなストレートな意見はありませんでした。ただ、内容の一つとして、密集化を防ぐ意味での制限なのねという趣旨でのご意見ということでは、発言はあったと記憶をしています。","voiceIndex":39,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"こういうご希望をお持ちだったわけです。それもわかります。地域でも話し合いをしたではないかという、それもわかるのですけれども、でき得る限り、ぜひ知らない人がいないというぐらいに徹底していただきたい。細分化はできないのですということは、これはぜひ皆さんに周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"高梨木密整備推進課長","answer":"そうすると、そういったルールがあるなんて知らなかったということになりますと、非常に個人の方々のこれからの生活設計であったり、いろいろなものが崩れてくるところもありますので、機会を捉えて。","voiceIndex":41,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"この条例が仮に成立したとして、施行はいつぐらいになるのでしょうか。","respondent":"長尾建築課長","answer":"配付資料に記載しておりますが、施行期日は、公布の日からとしております。公布の日から、この条例に関しての制限が適用されるということになりますので、これから新しく建てる建物が施行期日以降で着工するものについては、この条例が適用されるということになります。","voiceIndex":44,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうすると、成立すると、新しい条例が適用されるということになりますので、先ほどほかの委員からもお話が出たとおり、結構強力な私権の制限になりますので、成立後、引き続き影響のある住民に周知をぜひお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"確認だけさせていただきたいと思うのですけれども、先ほど課長のご答弁、お話の中で、今回の地区計画と同種同様な場所はどこですかという質問に対して、豊町・二葉・西大井と小山台ということで出ていますけれども、条例の新旧対照表のところで、小山台の地区、それと、豊町四・五・六等ならびに戸越・豊町地区、これについては、私は若干の内容の違いがあると思うのですけれども。","respondent":"長尾建築課長","answer":"先ほど同種同様のというふうなご説明をしましたところにつきましては、あくまで敷地面積の最低限度が同様に定められているということで、事例として挙げたものとなっております。","voiceIndex":47,"id":"exchange-016"},{"speaker":"大沢委員","kind":"意見","question":"私が聞きたかったのは、文言の違いを聞きたくてお話をさせていただいたのではなくて、今、まさに課長がおっしゃった、地区整備計画が定められた区域、それと、特定建築物地区整備計画、これは私は勉強不足で、ここへお話しする前に調べてくればよかったのですけれども、この２つの意味合いを、簡単で結構なので、そこのところが知りたかったもので、ご答弁をお願いしたい。","respondent":"長尾建築課長","answer":"豊町・二葉・西大井の地区計画であるとか、戸越・豊町地区の地区計画につきましては、いわゆる一般型と呼ばれておりまして、防災性の部分だけに特化しておらず、いろいろな種類の制限がかけられるようなタイプの地区計画となっております。","voiceIndex":49,"id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"反対なのですけれども、態度を表明しますと、今回、地域の防災性向上のために必要なルールも含まれていると認識はしていますが、地域から反対の声も上がり、住み続けたい住民の追い出しや、商店街を削るなど、地域環境の破壊につながる２９号線を前提とし、それを推進するための超高層再開発であるＤ地区を含むものであります。賛成ができません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-018"}]},{"id":"topic-03","title":"第７２号議案、専決処分の承認を求めること","agenda":"第７２号議案、専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそも滞納が発生した状況というのですか、どのように把握しているのか、もう少し聞かせていただければと思います。","respondent":"森住宅課長","answer":"それに対して、漏水事件が起きるような建物については、５万円程度の家賃であろうというふうに一方的に主張されまして、その間、平成２５年ですけれども、退去されるまで５万円程度の使用料を払われていたというところで、その差額が滞納使用料という形になっております。","voiceIndex":63,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"確認","question":"入り組んでいて、あと、前回のこともよくわからなかったのですが、今、若干ご説明があって、何となく事件の概要というものがわかったのですけれども、先ほどご説明の中で、裁判所から１カ月以内に訴訟を起こすよう指導があったというお話があったのですが、それはこれまでの経緯の中で、品川区に優先する債権があるということで通知があったというところで。","respondent":"森住宅課長","answer":"今回の請求に当たりましては、６,０００万円の債務が非常に疑わしいというふうに、５月１１日に出された通知に基づきまして、弁護士と協議をしまして確認をして、このままですと区の債権がとれないということになりますので。","voiceIndex":66,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。細かいところまでは内容がわからないのですが、これは個人的にいろいろお話を伺いたいと思います。品川区としては、一般的に詐害行為取消権のようなものでこの不存在を求めることとなったという訳ですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-021"}]},{"id":"topic-04","title":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。トイレの改修ということで、戸越銀座、西大井、この２つについて、公明党としても、その地域を担当する議員から、会派としてもトイレの改修ということは要望をずっとしてきましたので、大変評価をさせていただきたいと思うのですが、その上で２点ほどお伺いしたいと思います。１年ぐらいかかるのかなと思うのですけれども、この２点、お伺いしたいと思います。","respondent":"溝口公園課長","answer":"戸越公園周辺の４カ所のトイレの洋式化の箇所ですが、三ツ木公園、葦山公園、戸越二丁目広場、戸越台公園、この戸越銀座に近接する４カ所の公園のトイレの洋式化を図っていきたいと考えて、補正予算を組ませていただいております。","voiceIndex":81,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"１点だけです。これ、多目的、誰でもトイレ、どういう形になるのか。それと、あと、小さいお子さんが座れる椅子とかはつくのかどうか。ベビーチェアというのですか、そういうものが全てにつくと期待をしているのですけれども、いかがでしょうか。","respondent":"溝口公園課長","answer":"ほかのところにつきましては、今後、詳細な設計を進めていく中で、できる限り対応していくところは対応していきたいと考えているところです。","voiceIndex":84,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"要望です。西大井については、設置をするという方向と決まっているようですが、そんなにスペースはとらないと思いますので、ほかのところも、可能であればでいいので、ぜひベビーチェアのほうは設置をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-024"},{"speaker":"大沢委員","kind":"確認","question":"確認だけ。誰でもトイレの中で、オストメイトの方が利用できるような環境は整っているのでしょうか。","respondent":"溝口公園課長","answer":"誰でもトイレにつきましては、オストメイトに対応した形で整備を進めておりますので、誰でもトイレがついたところについては、オストメイトをご利用の方もご利用できるような形の整備を進めていきたいと考えております。","voiceIndex":88,"id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"三ツ木公園のほうも、改修を望む声もいただいていましたので、本当によかったなと思うのですけれども、先ほど便器の改修、スピード感という話もありましたが、１カ所の和式トイレを洋式化する際のおおよその改修費用というのは、幾らぐらいかかるのでしょうか。伺いたいと思います。財源なのですけれども、一般財源というふうにあるのですが、補助金などがあるのかないのか、確認させてください。","respondent":"溝口公園課長","answer":"今後の洋式化の考えですけれども、基本的には、オリンピック開催時までに少しでも多くのトイレを洋式化していきたい、そういったところを考えて、さまざまこれまでもご要望いただいてきておりますので、そういったものを受けて。","voiceIndex":90,"id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、西大井の公衆便所は、現時点でも誰でもトイレなのですか。","respondent":"溝口公園課長","answer":"あくまでも身障者対応までのトイレになっておりますので、さらに今回整備することで、オストメイトをつけること、また、ベビーチェアとか、そういったものも整備することによって、誰もが使いやすい誰でもトイレの整備ができると考えているものです。","voiceIndex":94,"id":"exchange-027"},{"speaker":"筒井委員","kind":"確認","question":"今、品川区の総合型地図情報提供サービスというのを見ているのですけれども、西大井公衆便所を検索すると、誰でもトイレという表示が出ているのですが、これは今回、先を見越してというあれなのですかね。その辺、後で確認をお願いします。","respondent":"溝口公園課長","answer":"ただ、一般的に見ますと、車椅子対応だけでも、十分広くブースをとっておりますので、ベビーカーを押された子ども連れのお母さんとか、そういった方が使えたりとかという部分がありますので、一応、誰でもトイレという形でホームページでは表記しているところもありますが。","voiceIndex":96,"id":"exchange-028"},{"speaker":"松永副委員長","kind":"確認","question":"私から１点だけ確認をお願いします。この工事、来年ぐらいに工事が始まる予定ということをお伺いして、その間、仮設のトイレ等が設置される予定はあるのか、それだけ質問します。","respondent":"溝口公園課長","answer":"そういったところでは、仮設というのも１つ必要かとは思っておりますが、今後設計を進めていく中で、また近隣にもトイレがありますので、そういったところへの案内、誘導、それで足りるのか、それとも、やはり仮設が必要なのか。","voiceIndex":99,"id":"exchange-029"}]},{"id":"topic-05","title":"平成３０年請願第１３号、都心・品川上空新飛行ルートの撤回を国交省に求める請願","agenda":"平成３０年請願第１３号、都心・品川上空新飛行ルートの撤回を国交省に求める請願","exchanges":[{"speaker":"筒井委員","kind":"質問・要望","question":"品川区議会、超党派としてこの問題、厳しく追及していきたいと考えておるところなのですけれども、まず、経済効果について、この請願にも書いてあるのですが、品川区にとって全く期待できないという記載があるのですけれども、私も行財政改革特別委員会のときから、品川区への経済効果を出してほしいということを国に伝えてほしいということを、区のほうに再三要望してきたのですけれども、この点。","respondent":"鈴木都市計画課長","answer":"新飛行ルート案、増便計画に伴う経済効果、特に区内での経済効果ですが、具体的な数字を示しての返答ということはございませんが、やはり海外からの来訪者が増える、観光政策的なところで、メリットといいますか、品川区内の経済的な発展ということは。","voiceIndex":114,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"そうした回答がない。先日の一般質問でも、区のご答弁は、やはり経済効果はもちろんのこと、騒音対策や落下物対策についても具体策がないと。今の状態は不十分だというご説明がありましたけれども、私はこれ以上国としてさらなる具体化、十分な対策というのはあまり期待できないと考えておるのですけれども、逆に、どの程度の対策の十分さだったら、区としては納得することができると言えるのでしょうか。","respondent":"鈴木都市計画課長","answer":"今、落下物対策総合パッケージについても、その中身のパブコメが国において行われておりますが、なかなかその中身を見ましても、点検ですとか、あるいは補修ですとか、機種ごとのそういった内容は書かれているようですが、これがいかに海外も含めた航空会社が取り組んで。","voiceIndex":116,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"安倍首相が、今年の国会の施政方針演説、１月２２日でしたけれども、羽田、成田空港の容量を世界最高水準の１００万回にまで拡大する、その目標に向かって、飛行経路の見直しに向けた騒音対策を進め、地元の理解を得て、２０２０年までに８万回の発着枠拡大を実現すると述べているわけですけれども、まず伺いたいのですが、首相が理解を得て進めるという地元の中には、当然。","respondent":"鈴木都市計画課長","answer":"国に品川区に対して丁寧な説明をしていただきたいというところを再三申し上げているとおり、当然ながら、地域の不安払拭の対象が品川区であるということ、そこに住む地域の方々ということは間違いないところです。","voiceIndex":119,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区上空を低高度で飛行する新飛行ルート案を容認することはできません、区議会公明党は、国交省に対して品川区上空を飛行しないルート案の再考を強く求めていきたいと表明されました。それに対して、いずれも区からは、ご質問やご意見を重く受けとめているとの答弁があったのですけれども、もう少し伺いたいのは、区としては何をどう重く受けとめたのかというのを、もう少し伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"さきの本会議の一般質問で答弁させていただきましたとおり、やはり地域の声、区民の方の不安というものは、今回の新ルート案を十分理解したというところには至っていないというところは、区のほうでもしっかり認識しています。","voiceIndex":121,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"公明党からは、今のルートの再考を求めていきたいという宣言というか、表明もあったということで、そこら辺については、区はどのように重く受けとめていらっしゃるのですか。","respondent":"鈴木都市計画課長","answer":"本会議の一般質問で答弁させていただいたとおり、まさに今、委員がおっしゃったとおり、重く受けとめているというところでございまして、その重く受けとめている内容については、区民の方が不安に思っている騒音ですとか、あるいは落下物に対して。","voiceIndex":123,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の計画案ではだめだというような態度表明があったということは非常に重いと思うのですけれども、率直にこの請願に目を転じてみると、計画の撤回を求めるということの１点求めているのですが、この内容と、先ほどの一般質問での非常に踏み込んだ態度表明という意味では、自民党も公明党も一致できると思うのですけれども、ぜひご意見を聞かせていただきたいと思うのですが、自民党と公明党。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"後ほど意見があるということですかね。ご本人からも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"安藤委員、これ、請願審査なのですけれども、それは明日所管質問でやるのですか。今日もう一回言われて。一般質問に関することの態度をもう一回表明しろと先ほどからおっしゃっていますけれども、そういうことなのですか。委員長から促されるのはわかるのですけれども、何でほかの会派の方から言われなければいけないのか。それがちょっと……、いやいや、委員会の性質上、そういうものですよ。違いますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"請願審査の質疑というのは、委員間討議を含めて、議会として、委員会として、この請願をどうするかということなので、そもそも最初から委員間討議というのが普通に行われて当たり前だと私は思っているのですけれども、別に発言しろと言っているわけではなくて、いかがでしょうかと、ちょっと問いかけているというか、そういうことなので、別に強制力はもちろんあるものではないのですけれども、ただ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問をさせていただきたいのですけれども、事実関係の確認というところで、内容的には、今、安藤委員からもありましたとおり、私どももこれを拝見させていただいて、共感する部分は確かにあります。もう一点、大気汚染、これについては、現状はまだ増えていないわけですから、何とも言えないのですけれども、何か大気汚染について増えるような兆候があるのか。","respondent":"鈴木都市計画課長、小林環境課長","answer":"航空機騒音に関連した不動産価値についてですが、区内の状況について、私もいろいろ、例えば、さきの行革委員会の中でもご説明いたしましたが、特に不動産関係の方の相談が多い建築課の窓口等々で確認をさせていただきましたが。区内では、現在６カ所、大気測定局を設置して、常時監視をしているところでございまして、極端に悪いデータが出ているということは無く、特に最近では改善傾向になっているというのが現状かと考えています。","voiceIndex":132,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。これは誰に責任があるかといったら、それは報道した側に責任があるのでしょうけれども、一般質問のときにも申し上げたのですが、問題は問題として、区民の声は区民の声として、私たちもしっかり受けとめたいと思っているのですが、いたずらに不安をあおるような、正しくない議論をしては、これはやはり価値が下がってしまうというか、しっかりした話が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"意見","question":"ちょっと発言が遮られてしまったのですが、そういう議論の価値を下げてしまうようなことは、これは避けるべきだと私は考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":137,"id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"それを区としてはどういう認識を持っておられるでしょうか。２つ目が、国と東京都、品川区、この３者があるわけです。今回、国交省への申し入れを求める内容になっている。では、国の考え方はどうなのか。国交省ですから、国はそういう状況で、国政の中ではそうなってくるのでしょうけれども、東京都はどうなるのか。それも教えてください。それから、ほかの区との関係はどうなっているのか、教えてください。","respondent":"鈴木都市計画課長","answer":"この２回、区長が出向いていって、国の方に強く求めたものは、やはり地域への丁寧な説明と、騒音等の軽減に向けた具体的な取り組み、あるいは落下物防止対策についての具体的な取り組み、これを求めたものです。","voiceIndex":139,"id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"東京都のほうも、しっかり各自治体がというところで説明を求めているということがわかりました。フェーズをいろいろ変えて、第４フェーズまでですか、やって、国交省は説明をしているということなのでしょう。ただ、品川区としてどうするのかといったときに、もうそろそろ決断しなければいけない時期にあるのではないでしょうか。なので、それを品川区は態度としてどうするのですかという話だと思うのです。","respondent":"鈴木都市計画課長","answer":"やはり対話型の説明会、これも一定効果があったと国のほうは申していますが、やはり例えば、時間を決めて、質問を受けながらそれに答える教室型の説明会ですとか、あるいは、場合によっては、区内に常設の展示ブースを設けていただくとか。","voiceIndex":141,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、この８割以上ということも本当ですかと私は思います。だから、国は地方との交渉をするときに、地方の意見というのを、よく十分に理解を求めているということは確かだと思うのです。ならば、品川区の中での総意というものをどうやってこれからつくっていくのでしょうかという話です。というのが１つあります。これは品川区ではできない範疇ですけれども、でも、もう少し広く考えてはいかがでしょうか。","respondent":"たけうち委員長","answer":"ちょっとすみません。先ほどから携帯が鳴っていますので、申しわけありませんが、切るか、マナーモードにしていただいて、わからなければ、近くの方に聞いていただいて、操作をお願いできますか。３回目ですので、すみません。では、続けてください。","voiceIndex":143,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"要望になります。もちろん国の、地方があるし、品川区としての範疇、権限があります。ここは、ただ、それを踏まえた形で、品川区の態度をどうしていくべきなのかということだと思うのです。私の意見として言いますと、やはり確かに説明をしていただく、それは国の役割だ。ならば、一歩でも二歩でも前に進んでいくためには、国の責任下において説明は説明できちんとしていただきたい。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"そもそものこの請願に戻って、確認だけさせていただきたいと思いますけれども、先ほど来、課長のご答弁の中で、これは国が推進する事業、国が主体となる国策としての事業だという旨のお言葉をいただきましたけれども、そもそも請願内容におけます「都心・品川低空飛行する新ルートを撤回してください」、この撤回する、これは確かに議会に来た請願でありますが。","respondent":"鈴木都市計画課長","answer":"その過程で、例えば、都市計画の再開発等を進めるときに、地元の都市計画審議会に意見を聞くとか、都市計画の手続き上はありますが、私のほうでも、この羽田新飛行ルート案について、法的な何か決定において、この手続が必要かどうかというのは、国のほうにも確認。","voiceIndex":148,"id":"exchange-046"},{"speaker":"筒井委員","kind":"質問・要望","question":"４点目としましては、最近、国土交通省からの発表で、情報発信拠点というのが、川崎市とか板橋区とか、また、最近では豊島区で設置されるようですけれども、情報発信拠点がなぜ一番被害をこうむり得る品川区で設置が行われていないのかということなので、ぜひとも情報発信拠点の設置、そして、一番被害をこうむる品川区ですから、３日とか２日とか短い期間ではなく、先ほど課長からもご答弁ありましたとおり。","respondent":"鈴木都市計画課長","answer":"ご質問の対案についてですが、これは委員のご質問の中で、区も学識者等を入れて、しっかりした対案を打ち出して、国民に求めていくべきではないかですが、国のほうで機能強化、新ルート案に至るまで、当然ながらさまざまな検討を重ねて、説明会の中での資料でもありますが。","voiceIndex":151,"id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただ黙って、品川区が指をくわえているのでは、国にとっては、同意したのだなということにも捉えられかねないので、ぜひ積極的に、こうした方策もあるとか、もう少し期間を置いてじっくり考えていったほうがいいとか、そうした対案を積極的に出していって、今後、交渉を重ねていくということが必要だと思っていますので、ぜひやっていきたいのですけれども、その点、どうお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"世論調査、これも先ほど私のほうでお話しさせていただきましたが、教室型の説明会ですとか、あるいは区内に常設の展示説明ブースの設置ですとか、こういったところをやっていただいて、区民の声として、一体どういう不安がまだ払拭できないのか等々を含めて。","voiceIndex":153,"id":"exchange-048"},{"speaker":"筒井委員","kind":"質問・要望","question":"区が納得する一つのラインという落下物ゼロということも、現時点では不可能ということなので、現時点ではこれ、撤回を求める表明をせざるを得ないと私は考えているのですけれども、リミットも２０２０年東京オリンピック・パラリンピック開催に合わせてということであれば、非常に時間がないということなので、区としては、今までの国のそうしたある意味不誠実な態度についてどう思っているのか、そして。","respondent":"鈴木都市計画課長","answer":"その点については、担当レベルでも何度も話をして、近々にそういった打ち合わせを行うというところまで、説明をどうしていただけるかというところをしっかり具体的な打ち合わせをしながら、説明を求めるだけではなくて。","voiceIndex":155,"id":"exchange-049"},{"speaker":"筒井委員","kind":"質問","question":"このままだと納得しかねるということを、国に伝えると。そういった理解でよろしいのでしょうか。","respondent":"鈴木都市計画課長","answer":"このままやはり何もやっていただけなければ納得できませんというのは、しっかり伝えたいと思います。その上で、丁寧な説明を具体的に行っていただける方法を国のほうで提示していただいて、実際行っていただけるように取り組んでいきたいです。","voiceIndex":157,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"さきの一般質問で、前回の委員会では私たちも紹介しましたけれども、今後２０２０年までの具体化に向けては、現在とまっている国の協議会が開かれる予定で、その協議会の前に、先ほど区からも紹介がありましたけれども、東京都の連絡会というのが開かれるという流れになっていくわけですが、今後の予定というところで、２０２０年の実施まであと少しなわけですから、もう少しそこら辺を具体的に。","respondent":"鈴木都市計画課長","answer":"今、口頭で担当者レベルで聞いているのは、次のフェーズの説明会を行う予定だです。","voiceIndex":160,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"今後のことについては、ほとんど聞かされていないという状況なのかなと思ったのです。近隣区との打ち合わせみたいな、情報共有みたいなものをやっているという話もありましたけれども、目的というのもよくわからないなと思ったのですが、もう少しそこら辺、何のために集まって、どういうことを目指しているのか、そこはもう一度聞かせていただきたいというのがあります。そこだけ最後にお願いします。","respondent":"鈴木都市計画課長","answer":"やはり１つは、こういうときは、ほかの区にこういう説明があったのにこちらには何もなかったとか、担当者レベルで行っていますといろいろなお話もあるでしょうから、そういったところを情報共有して。","voiceIndex":162,"id":"exchange-052"},{"speaker":"安藤委員","kind":"提案","question":"３,０００筆というのは、本当に会の方々も、何度も何度も街頭に出て集めて、本当に一筆一筆にこの問題に対する不安や、何とかしてほしいという思いが入って大変重いものですから、ぜひ賛成するにしても、反対するにしても、いろいろあると思いますが、しっかり態度表明をされる際は、今はこういうことですということでも構いませんが、ぜひその理由も述べていただきたいと私は思いますし、お願いしたいと。","respondent":"たけうち委員長","answer":"申しわけないのだけれども、今、請願審査でかなりの時間をかけていて、そういう別の話をされても今すぐに決められないと思いますので、後ほど正副で検討します。請願についての質問があれば、続けてください。よろしいですか。ほかによろしいでしょうか。","voiceIndex":164,"id":"exchange-053"},{"speaker":"大沢委員","kind":"確認","question":"自民党・子ども未来は、本日、結論を出すでお願いします。結論は、不採択でお願いいたします。理由を申し述べます。請願内容の前文については、先ほど一つ一つの事象を確認させていただきました。その事実確認の上で、不安という心情に対しては、大いに共感をするところであります。一般質問におきまして、地域への説明の不足が否めないという旨の質問を、私どもの会派の一員がさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど来、共産党の安藤委員から丁寧なご説明をいただきまして、私どもの質問の書き起こしですかね、それとあと、答弁についても、おおむね間違っていない内容だと思いますけれども、一応、念のため役所側の答弁を確認いたしますと、私が書き取ったものだと、「今回の議員のご意見を重く受けとめ」というところ、ちょっと中略しますけれども、「今後。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-055"},{"speaker":"安藤委員","kind":"提案","question":"区民の方ですから、いろいろ表現が至らないところですとか、不正確なところもあるかもしれません。ただ、私は、例えば、確かに品川区は撤回はできません。ですから、文言の問題だと私は思っています。意見書をさらに進化させていきながら、改めて一致できるところで区議会の意思を示していくということは、やはり私も大事だと考えていますので、先ほどの提案の件もぜひ検討をいただきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":168,"id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択といたします。しかし、区民への周知は早急に行われなければならないものと考えておりまして、そのためにも、今後、国に対して改めて教室型説明会などの周知策をとるよう要望していただきたいと考えておりますので、その辺、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"私は、継続審議です。この表題を見ていただきたいのですけれども、「新飛行ルートの撤回を国交省に求める請願」と書いてあるので、国交省に求めたいのですという請願なのです。これは特別委員会で、行革の中で、２年ですか、３年ですか、議論されて、今回、所管が変わりました。２０２０年ということで、時間はないにしろ、やはりこれから品川区の態度というものもしっかり示していかなければいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。それを踏まえて、そうした区の意思、区民の意思というのを踏みにじるのかどうか、無視するのかどうかは最終的に国が決めることで、それは国政のほうの審判にかかってくると思いますけれども、反対する働きかけ、撤回を求めるということ自体は認められると考えております。そういう理由で採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-059"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということの決定がありましたが、この趣旨というのは、非常に私は賛同するところがありますので、本来は継続的に審議をしていきたいところでありますが、採択という形でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":174,"id":"exchange-060"}]},{"id":"topic-06","title":"平成３０年陳情第９号、大森駅前住宅前駐輪場移設の具体的な検討についての陳情","agenda":"平成３０年陳情第９号、大森駅前住宅前駐輪場移設の具体的な検討についての陳情","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"その中でちょっと幾つか確認をさせていただきたいのですけれども、今回の陳情の中で、今年度から部分的段階的にでも現在の駅前住宅前の駐輪機器、現在のものを移設ができないのでしょうかということが陳情の要旨の一番目に出ているのですけれども、ここについてのお考えを伺いたいと思います。はそこを伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"段階的な移設の検討というよりも、まずは利用状況等をしっかり精査しながらやっていかないと、移設と撤去ということに関してはやはり利用状況をしっかり把握をして、どれだけ需要があってどれだけとめられるのかというのを今後もやはりしっかり把握をして。","voiceIndex":182,"id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"年間の放置状況のデータは出ているというところです。それと、２点目に陳情の要旨の２番目には、今おっしゃっておられた利用状況について早急に分析をしていただいて移設の検討をしてくださいと、そういうご要望があるのですけれども、これはもっともなことかなと思うのですが、先ほど利用状況を見きわめたいということだと思うのですけれども、今後利用状況についてどういう形で見きわめをされていくのか。","respondent":"古郡交通安全担当課長","answer":"期間につきましては、分析をするには１年ぐらいのスパンの利用状況を勘案しなければならないと思っています。","voiceIndex":184,"id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問","question":"済みません、１年というのは何から１年ということですか。この陳情から１年ということなのでしょうか。","respondent":"古郡交通安全担当課長","answer":"４月２９日に大森駅水神口の駐輪場の整備が全て完了し、供用を開始していますので、そこから１年と考えています。","voiceIndex":186,"id":"exchange-063"},{"speaker":"あくつ委員","kind":"確認","question":"わかりました。確認ですけれども、そうするとめどとしては来年の春ぐらいには大体の状況が見えてくる。その上で、この今の移設のところについても、その分析を踏まえて考えていく、こういうことでよろしいのでしょうか。","respondent":"古郡交通安全担当課長","answer":"そうですね。１年ぐらいを見て、その利用状況等を踏まえてそういったことを検討していきたいと思います。","voiceIndex":188,"id":"exchange-064"},{"speaker":"大沢委員","kind":"質問","question":"今課長のご答弁の中で、利用状況を踏まえてというお話がありましたけれども、いただいた資料の右下のほうに利用状況とありますが、その横に放置状況ということでおのおのパーセンテージが出ているわけですけれども、おおむね大体どれぐらいになったらかじを切るというような数値目標というのはおありなのか教えてください。","respondent":"古郡交通安全担当課長","answer":"数値については、いまだ状況の分析が終わっていませんので、数値に関してはちょっとまだお答えはできないような状況です。","voiceIndex":190,"id":"exchange-065"},{"speaker":"あくつ委員","kind":"確認","question":"何回も質問して申しわけない。さっき聞き忘れてしまったのですが、大森駅前住宅前駐輪場を設置した業者、あと指定管理をしている事業者との契約というのは、たしかもう５年くらいだったと思うのですけれども、これはどのタイミングで切りかわるのか、確認をさせてください。","respondent":"古郡交通安全担当課長","answer":"指定管理委託をしておりますので、５年間継続で、平成２９年度にやっておりますので、そこから５年になります。５年ごとでやっておりますので、そこでまたかわるということです。","voiceIndex":192,"id":"exchange-066"},{"speaker":"あくつ委員","kind":"確認","question":"本当に申しわけない、これで最後ですから。確認ですけれども、平成２９年度に切りかわったのですか。平成２９年度から始めているから５年間ということで３３年度までということなのでしょうか。ちょっとごめんなさい、確認させてください。","respondent":"古郡交通安全担当課長","answer":"そうです。指定管理者として指定しておりますので、そこでかわるです。〔「平成２９年からか。平成２８年度に決定をしまして、平成２９年度からですので、平成２９年度から５年間指定管理者ということです。","voiceIndex":194,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"利用状況を直近のものでいいのですが、パーセンテージというのですか、それも今お伺いしたところでわかれば教えてください。","respondent":"古郡交通安全担当課長","answer":"当日利用については４４４台が公園を含めてとめられるような状況となっております。直近の利用状況ですが、住宅前の北側ですが、それについては２３％、住宅前の南側が８３％、日立前が１３２％、全体で１６５台、全体でいきますと７４％です。","voiceIndex":197,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。こちら請願された方々が調査をされたということで数字を伺ったのですが、この５月のようですが、１カ月間台数を数えたそうです。台数を聞いたのは、当日だけではなくて、公園内に何台台数が用意されているのか、そちらのほうのパーセンテージは大体どれぐらいなのかと伺ったので、ちょっと後でわかれば教えていただきたいと思います。","respondent":"古郡交通安全担当課長","answer":"駐輪場全体の台数ですが、先ほど説明した部分と定期利用などをあわせて１,２４７台となっております。その中で現在までのところは全体の利用率が７３.３％になります。地下機械式については６５.９％が利用されている状況です。","voiceIndex":199,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。やはり新たな駐輪場整備などで改善が進んでいるのかなと思います。地下式がやはりすごく少ないですよね。１点お伺いしたいと思います。陳情にも書いているのですけれども、区としてはこれらの周辺住環境にとっての問題点についてどのように認識をしているのかもあわせてお伺いします。","respondent":"古郡交通安全担当課長","answer":"安全上に関しては、自転車が高速度で走行することで危ないということですので、パイプ柵を設置して走行抑制を図っている状況です。ですので、今後もそういった形で自転車の走行に関して広報・啓発活動を行ってまいりたいと思います。","voiceIndex":201,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"デイサービスの送迎車のことについては把握していますか。ここがやはり駐輪場になってしまっていると乗り降りできないのですよね。これが２点目です。最後ですけれども、３点目ですが、マンション建設の状況、結構増えていると、これから増えるという話も聞きますけれども、こういうのはどういうふうに区としては影響というのですか、それを調査・把握していくお考えなのか伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"今後の予定につきましては、南大井で１３棟で７４３戸できる予定になっていますので、この辺の動向を踏まえながら考えていきたいと考えております。","voiceIndex":203,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"苦情は来ていないということですけれども、実際今回陳情という形になりましたが、これも実際住んでいる方の、利用者の苦情になると思いますので、先ほどの柵の問題もあります。自転車レーンはあるのですけれども、そこに駐車している車とかがあると自転車もやはり歩道を通っていくと。ですから、ちょっとこういった区民の声と実態というのをぜひ正面から受けとめていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-072"},{"speaker":"西本委員","kind":"確認","question":"確認をいたします。この陳情の中の理由の２段落目でしょうか、「住民、周辺保育園の園児たち、近くのホテルに向かう旅行者などの安全を脅かしております」という文言があります。先ほどのご答弁ではデイケアサービスの送迎に関してのクレームといいますか問題提起はないような状況なのですが、ここに書かれているようなそういうものに関してはいかがでしょうか。","respondent":"古郡交通安全担当課長","answer":"ですので、あとは自転車の走行に関しては、やはり注意喚起をしていただくという形でやっていきたいと考えておりますけれども、安全を脅かすというか、歩道は３.５ｍと広くなっておりますので、それについては確保されていると認識をしております。","voiceIndex":206,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"ということは、これは「脅かしております」というのは違うということの認識でよろしいでしょうか。具体的にいろいろなことがあって危ないよという警告をされていることなのかなと見たのですけれども、区は、いや、そういうことではないですよという認識でよろしいでしょうか。","respondent":"古郡交通安全担当課長","answer":"区のほうにそこが危険で看板を設置してくれだとかそういった苦情等はありませんので、そういった認識です。","voiceIndex":208,"id":"exchange-074"},{"speaker":"西本委員","kind":"確認","question":"わかりました。なので、大森駅水神公園の整備がなされてから１年ぐらいは様子を見るということだったのですけれども、それ以上に、周りの環境を見たときに、様子を見なければいけない時期というのは１年以上必要なのではないでしょうか。なぜかというと、やはり人口の増え方を見ないとなかなかこれは撤去していいかどうかという判断にはならないのではないかと思うのですが、１年で十分でしょうか。","respondent":"古郡交通安全担当課長","answer":"１年で判断するというのではなくて、１年間で利用状況を把握しながら今後検討していくですので、ですので１年で利用状況を見て、また人口の動向だとかそういったものを加味しながら検討していくという形になりますので、今現在では判断がつかないというような状況です。","voiceIndex":210,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"多分この大森周辺の放置自転車の状況というのはいろいろ変わってくるのだと思うのです。そこにとめなければいけないわけですから。そこを撤去してしまったら、あ、ここに置いていいのかなとなってしまうので、逆に放置自転車を促すような形になってしまうのではないかと思いますので、その辺の見立てについてはいかがですか。","respondent":"古郡交通安全担当課長","answer":"委員ご指摘のとおり、やはり放置状況だとか収容し切れない状況を生まないように、それを慎重に検討していきたい。分析をして、利用がないからといって直ちに撤去できるかというと、やはりそれは難しいのかなというところで考えております。","voiceIndex":212,"id":"exchange-076"},{"speaker":"筒井委員","kind":"質問・要望","question":"今いろいろなお話が出まして、もうちょっと分析は必要かなと考えております。もう一つ、交通の安全性とともにこの陳情者が述べている美観の件なのですけれども、区としては、個人の感性によるかもしれないのですが、美観について損なっているとお考えなのでしょうか。美観が損なわれているという区民のお声というのは入っているのでしょうか。","respondent":"古郡交通安全担当課長","answer":"美観の関係ですが、私のほうとしては、駐輪場のラック幅も広くとって置きやすい駐輪場としております。ですので、整然と自転車が並んでいるような状況ですので、美観を損ねているという考えはございません。そういった美観を損ねているという声は陳情者の方からは入っておりますが、そのほかの方から入ってはおりません。","voiceIndex":214,"id":"exchange-077"},{"speaker":"筒井委員","kind":"質問・要望","question":"認識がかなり食い違っているのかなと感じましたけれども、もう一度そのあたり総合的に１年間ないし１年以上の分析でこの点もぜひ確認していっていただきたいと考えております。","respondent":"今井土木管理課長","answer":"ただ、今後公園等の改修、または近隣の公有地等の確認を含めて、ぜひ駅周辺に置きたいと考えています。ただ、現時点で明確に置けるという状況ではございません。引き続き大森駅に限らず駅周辺のポート設置について取り組んでまいります。","voiceIndex":217,"id":"exchange-078"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。なかなかちょっとこの問題は対応するにも時間がかかる、難しい問題かなと考えております。ぜひとも難しい問題ですけれども、いろいろ分析やシェアサイクル等ほかの代替手段とかあらゆる方法でこうした駐輪場の問題にぜひ取り組んでいっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"確認","question":"本当に時間を使って申しわけないですが、もう一回確認させてください。もう平成３０年度で切りかわっているのかどうか。何でこういう質問をするかというと、契約のタイミングで、何か契約が変わる時点で変更等がきく可能性があるのではないかということでさっきお聞きしたのですけれども、大森駅水神口駐輪場はできたばかりですから別にそれは構わないのですが、この駐輪場をもう一回その考え方。","respondent":"古郡交通安全担当課長","answer":"指定管理者については、平成２４年から変わっておりませんので、ＮＣＤ（日本コンピュータ・ダイナミクス）というところでやっておりますので、そこは変わっておりません。平成３３年度の末までです。平成３４年の３月です。平成２９年度から平成３３年度まで５年間となっております。１年間という期間については、４月２９日から開設をしておりまして、それから１年間ということで考えております。","voiceIndex":220,"id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"済みません、先ほど質疑の中で陳情の要旨の２番目に関連して、「歩道上以外への適切な場所への次期増設計画」というところで、民地を含め云々という話があったのですが、そこら辺がよく聞き取れなかったというのもあるのですが、もう少し教えていただければと思います。","respondent":"古郡交通安全担当課長","answer":"大森駅周辺については、用地がないということで、民地も含めて今後探していって検討していきたいです。","voiceIndex":223,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"やはりこれは「歩道上以外への適切な場所へ」と書いているのです。ですから、少なくともこの４月で今年度の初めに完成したところからやはり期限を区切って検討して、それをこの心配されている陳情者の方々にはやはり区がどういう検討をしてどういう結果になったのかというのを、数値なども示して近隣の状況などもきちんとしたデータもそろえて少なくとも説明する必要があるのではないかと。","respondent":"古郡交通安全担当課長","answer":"直近では公園で最大の利用があった際、公園内の平置きは１２５.１％のときは住宅前が７４％になっているという状況で、その後も日立大森ビル前も１３５％という収容し切れないような状況もありますので、やはりそういったものを判断しながら。","voiceIndex":225,"id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど紹介しましたように、設置の段階からいろいろやはり非常に区としても私はまずい点があったと思いますし、そういった経緯があるところなので、やはり検討するということですけれども、どのような検討をして、その検討結果をきちんと一定の期間を区切って住民の方に示すというのは、先ほどありました委員会資料のように、数値も出して、なおかつ私も伺いましたけれども。","respondent":"古郡交通安全担当課長","answer":"１年後ということで検討はしていきたいということで考えておりますので、その状況によってその場その場で判断をしていきたいとは考えております。","voiceIndex":227,"id":"exchange-083"},{"speaker":"松永副委員長","kind":"質問","question":"説明、ありがとうあります。私から１点だけなのですけれども、先ほどのご説明の中で利用状況、放置状況、安全面、今後についてそれぞれ先ほどの議論の中で理解いたしました。そこで、先ほども安藤委員からありましたけれども、近隣住民の方々に対しての周知、説明等というのは今まで行われてきたのかどうかというのをお聞きしたいと思います。","respondent":"古郡交通安全担当課長","answer":"付近の住民の方に関しては、設置の段階ではある程度説明をしている、水神口に駐輪場を設置する段階では丁寧な説明を行っている状況です。整備をやりますよと住民の方々には説明をしているという状況があります。","voiceIndex":229,"id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"理由はいいですかちょっと。全ての状況においてまだ道半ばであるということから、この陳情の要旨については「部分的、段階的にでも開始をすること」、これも今精査中ですから、まだ時期尚早であるということです。それによって「策定、予算化」というのは物が決まってからの結論の話ですので、１の部分を受けて２についても理解するのは困難であると。以上の理由から不採択でお願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-085"},{"speaker":"あくつ委員","kind":"質問・要望","question":"結論から言えば、不採択とさせていただきたいと思います。先ほど答弁をお伺いしますと、１年間ぐらい状況を見てこれから分析をされるということで、これは一定の期間は必要だと思います。私どももご本人の皆様からもしっかりお話を伺いましてその思いは受けとめたつもりでありますけれども、状況がこういう状況であるということも今説明を受けましたので、なるべく早く結論を出していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":234,"id":"exchange-086"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張します。利用状況について分析を早急にということは当然のことですし、これまでの設置からの経過、住民との合意のあり方の問題もあります。それと実際にこういった駐輪場施設が住宅前にあるということでやはり陳情者の方々も生活への支障を感じているということもありますので、これは採択をすべきものだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":235,"id":"exchange-087"},{"speaker":"松永副委員長","kind":"質問・要望","question":"私たちの会派では、本日結論を出す。理由といたしましては、放置状況では平成２７年度より若干ではありますが増加傾向にあるという分析が出ております。こうした分析は現在も行われている中で、結果を出すというのはなかなか難しいものであると思いまして、不採択としますが、その中で、要望になるのですけれども、今後も近隣住民と情報共有をしっかりとしていただくようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"本日を結論を出していただきたいということで、不採択です。理由とそれから意見ですけれども、先ほどの質問の中でも今後の動向をしっかり見ていただきたいということです。ですので、やはり陳情者の方々も含めご理解をいただくような努力をこれからもしていただきたいということと、動向に合わせて、状況に合わせた形での対処を全体的にもう少し見ていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-089"},{"speaker":"筒井委員","kind":"質問・要望","question":"理由は、先ほど述べましたとおり、交通の安全性の問題、美観の問題、そして利用状況が今後どうなるのかということ、そういったことの分析がまだありますし、１年ないし１年以上かかってしまうおそれがあると、そういう可能性が強いということでして、また陳情内容にある、計画策定、予算化というのは、その分析が済んでからでないとできないということなので、今回は不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-090"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"６月２９日の自民党の石田秀男議員の一般質問で、北品川の駅前交通広場のまちづくりの質問がありましたけれども、計画案の一部変更をということで質問がありました。区のご答弁が、景観と歩行者の安全に配慮して引き続き検討していくということでしたけれども、具体的にどのような配慮というのがなされるのか、どういうお考えなのかをぜひ聞かせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":243,"id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":62537,"voices":245}},{"id":"h30-20180702-9","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"文教委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第４８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいのですが、いわゆる免許状を有する者というふうに規定を改めるということですが、以前免許の更新をされていない方とかのことがいろいろ問題になっての改正なのかなというふうに思うのですが、これは免許状を有する者ということで、例えば年に１回なのか、数年に１回なのかはわからないのですが、提示というのはされるのですかね。","respondent":"高山子ども育成課長","answer":"今般は、放課後児童健全育成事業に関する放課後児童支援員の資格を取得する、足り得る前提資格として教員免許状ということを書かせていただいております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"ここに例えば民間の方々も入って仕事をしていただいている、そういう状況なので、民間のところではこの資格がどういうふうに位置づけられていくのか、きちんと免許を持っている、免許状を有する者であってほしいと、当然条例がそうですから、そうなるのだろうと思うのですけれども、改めてちょっとその辺の確認をしておきたいと思います。","respondent":"高山子ども育成課長","answer":"具体的に教育職員免許状の第４条に定める資格の範囲という点で申しますと、これにつきましては、幼稚園、小学校、中学校、義務教育学校、高等学校、中等教育学校などに加えまして、解釈の話になってくるのですが、特別支援学校でありますとか、あるいは養護教諭。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうものが民間の方々については自己負担なのか、会社負担なのか、その分を委託費ということで区がこれからの委託契約の中で上乗せになっていくのか、ちょっとそのあたりはどういうふうになるのか教えていただきたいと思います。","respondent":"高山子ども育成課長","answer":"放課後児童支援員の講習料につきましては、基本的には無料で受講していただいておりますので、特に事業者の側においてそれを負担されるというような状況はございません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけです。３月３０日の通知の中身、改正の趣旨及び内容というところに、一つ、第１０条第３項第１０号として、「５年以上放課後児童健全育成事業に従事した者であって、市町村長が適当と認めたもの」を新設すると書いてあるので、これはどういうことなのか、品川区に関しては、これが影響するのかどうか教えてください。","respondent":"高山子ども育成課長","answer":"したがいまして、今回の条例改正の範囲外ではありますが、あわせて規則においても改正を予定しています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"規則はどこを見たらわかるのでしょうか。規則も変わっていくということなのですね。","respondent":"高山子ども育成課長","answer":"今回の条例改正に合わせまして、規則においても改正いたしますので、現状においての表現とは今後変わっていくということで、条例と合わせたタイミングで施行していくというふうに考えてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"提案","question":"ということで、規則も変わっていくけれども、今回提案があるのはここの条例の部分であるという説明でよろしいのですかね。はい、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"}]},{"id":"topic-02","title":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"病児保育のところです。病児保育にかかわる基準がちょっとわからないので教えていただきたいと思うのですが、定員８名と書かれておりますけれども、実際の８名に対しての人員はどの程度、どういう職種の方がかかわるとかという基準があるのかどうかと、部屋の２階の一部で約９０m2とありますが、これはこの病児保育専用室なのか、この辺の基準も大もとがあるのかどうか教えてください。","respondent":"佐藤保育課長","answer":"児童に関しましては、３人に１人以上の保育士を配置する予定です。定員は８人予定ですので、看護師１人と保育士３人が必要になるです。実施スペースの関係ですが、保育室は児童１人当たり１.９８m2以上、観察室は３.３m2以上の基準があります。","voiceIndex":29,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"病児保育は子ども・子育て計画で増やしていくという希望が、本来、病気だったら本当に保護者の皆さんがお休みできるような職場の環境をつくっていかなければいけないなと思っていますが、なかなか今の厳しい状況の中で求められているというところで、またクリニック、病院自体もすごくご苦労が多いと思うので、２カ所目ということで、ありがたいな、ぜひ成功していただきたいなと思うのですが。","respondent":"佐藤保育課長","answer":"お子さんは熱があるという状況で、比較的静かにしていますので、保育士の方も見守っている運営をしていると聞いております。","voiceIndex":31,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"最後です。病児保育にかかる費用というか、保護者の負担と、あと補助のところを教えてください。","respondent":"佐藤保育課長","answer":"区からの運営事業者に対する運営支援といたしましては、大体８人定員ですと年間１,０００万円ぐらい、保育士と看護師の人件費相当から算出してお支払いをしているところです。","voiceIndex":33,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"研修のところなのですけれども、ちょっと現状がどういうふうになっていて、どう変化をするのかというのを具体的に教えていただきたいのと、「のびしなプロフェッショナルスクール」のところの一番下の図のところに、「内容」と「対象」と「体制」とあるのですが、この「体制」のところに三つの丸が書いてあって、これの意味がわからないので、ちょっとここを教えてください。","respondent":"佐藤保育課長","answer":"こちらに関しましては、先ほどご説明いたしました国が示す８分野の研修のほうに再編して、どこの分野が一番弱いのかとか、過不足のほうを今回検討して、より分かりやすい形で私立も含めて、公立も当然ですけれども、保育士の研修の参加と質の向上を図っていくです。","voiceIndex":35,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなのですが、右肩に大きな丸で「全保育園保育士」と書いてある、これの意味に対して行っていくという理解でいいのですか。すみません。","respondent":"佐藤保育課長","answer":"答弁がわかりにくくて申しわけありません。体制といたしましては、今ご説明した内容で、この体制をもって右に矢印がありまして、区内全部の保育園の保育士に働きかけるです。","voiceIndex":37,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全区内の保育園保育士に対しての質の向上という取り組みなので、ぜひよい成果を上げていただきたいなと思いますが、左の８項目の内容というのは、これから国から示される中身で行われていくのか、それを具体的に横引きにしながら研修の項目を決めていくことなのか、ちょっとそこを教えていただきたいのと。","respondent":"佐藤保育課長","answer":"そしてまたその後、標準的な事務のマニュアルを作成して、それを全保育園長に対して研修をして、周知の徹底を図るというところを今のところ予定しております。","voiceIndex":39,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"その事務内容の標準化委託の内容に当たって、現状いっぱい問題があると思うので、現場の声の反映というのを、どう集約してここに持っていっているのかというのと、標準化のマニュアルをつくっていくということですけれども、以前保育園でかなりお金をかけて標準化、ファイリングシステムというのをつくって、あのときは品質を一律にしていくということでファイリングシステムがあったのですが。","respondent":"佐藤保育課長","answer":"この間、事務の標準化ＰＴというのを立ち上げまして、各園長から細かく私も話を聞きましたけれども、やはり基本的にワードとかエクセルとか、そういった作業が苦手な保育士が一定いるというところと、給食の賄いであったり。","voiceIndex":41,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ＩＳＯは、私が本当に議員になる前から、かなり昔で、これというのは、すごく大変な思いをしてファイリングシステムをつくったにもかかわらず、今伺ったら引き継がれていないというか、年間何百万円も使って、ＩＳＯの規格を守っていくためのいろいろな作業もされていたと思うのですが、その辺がうまくつながっていないという意味では、今度のマニュアル化のところもぜひ現場の声を十分入れて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ということは、何か品川区独自の特色があるのかなと思うのですが、もしそういうのがあるのであれば教えていただきたいのと、事務内容標準化の部分ですが、もちろん事務内容を精査して標準化をするというのはいいのですけれども、ただ事務内容を標準化してもなかなか事務作業にかかる時間とか労力というのは、そんなに変わらなくなってしまうので。","respondent":"佐藤保育課長","answer":"１点目は、研修の関係ですが、「のびしなプロフェッショナルスクール」というところで銘打っているですが、区といたしましては、就学前乳幼児教育ということで、小学校への連携というところに力を入れてきているのと、特別支援の関係と保護者支援。","voiceIndex":44,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"この間の質疑の中であったかもしれないのですが、まず事業予算の(2)の研修追加分で、今渡部委員のほうからあった８分野、私も今資料を見ながらですけれども、追加をしたものというのが具体的に何かというのと、あと８分野はいろいろあって、１分野当たり１５時間、先ほどの質疑で研修時間にあてられるということなのですけれども、この間、今いろいろ課題になっている保護者支援というところについては。","respondent":"佐藤保育課長","answer":"保護者支援に関しましては、現状かなり研修をしているところで、１日の保護者とのかかわりであったり、さまざま課題を抱えている方に関する対応に関しても研修は行っているところです。","voiceIndex":48,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"とりわけ、この間の一般質問でも取り上げた年休の取得が事務職の方々に比べて半分しかとれていないという現状のときに、やはりこういう病児保育というのがそういう点でも必要なのかなというふうに見てはいるのですけれども、さっきも言ったように、やはり休める環境をつくるということが望ましいわけでありまして、そういう点について保育士の方々をいろいろ見ておられる保育課として。","respondent":"佐藤保育課長","answer":"ただ、例えばリフレッシュとか長期間の休暇をとるのはなかなか難しいと、その辺は担任をほとんどの職員が持っていたり、行事もたくさんある関係で厳しいという話は聞いておりますので、今回お願いしている事務内容の標準化の委託とか、電算の効率化とか、さまざまな手法を使って。","voiceIndex":50,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、やはりこういう区民の皆さんに安心して働き続けていただくために、開設する事業で、その事業を担っている保育士の方々がとれないなどというのは、あまりにも不合理だというふうに思いますので、そこの改善を強く求めたいと考えていますし、そういうことについて区はどういうふうに考えているのかを伺って、終わりにしたいと思います。","respondent":"佐藤保育課長","answer":"年休の関係ですが、休みの関係はさまざま制度もできておりますので、例えば子の看護のための休暇とか、部分休業をとっている職員もおりますので、その辺の休暇もあわせてどういう状況かというのを把握していきたいというふうに考えております。","voiceIndex":52,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"終わりにしたかったのですけれども、最後に一言話したいと思います。したがって、改善しなければいけないというふうに思いますので、ぜひいろいろな工夫をされて改善し、安心して働き続けられるだけではなくて、自分の子どもも含めて、子どもが豊かに育つ、豊かに育てられる、そういう状況を一日も早くつくっていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-03","title":"平成３０年請願第１２号、大崎図書館の解体は止め、新たな図書館として再生させることを求める請願","agenda":"平成３０年請願第１２号、大崎図書館の解体は止め、新たな図書館として再生させることを求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"改めて大崎二丁目にある大崎図書館を解体する理由、先ほど補修とか改修が追いつかないという話でしたけれども、解体する理由、そして築何年か、そのあたりを教えてください。","respondent":"横山品川図書館長","answer":"解体の理由と申しますか、移転の理由と申しましては、改修について補修が追いつかないということと、またＳＨＩＰへの連携です。築年数につきましては、３４年になるところです。","voiceIndex":68,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"築３４年ということですから、一般的には改修というよりは補修をしながら公共施設を維持、存続させていく、こういう方針に品川区はあるというふうに思っているのですけれども、その点と、この解体する理由として、今までは老朽化というふうに言っていた時期もあったと思うのですけれども、そことの関係の整理をどういうふうにされたのかを知りたいし。","respondent":"横山品川図書館長","answer":"老朽化という意味では、３０年以上たっておりますので、老朽化はしております。委員がおっしゃるように老朽化しても補修をしながら最大年数までもたせるという区の方針の原則があります。","voiceIndex":70,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"文章は正確ではないけれども、趣旨をということで聞いていただきたいのですが、２９号線で移転することになり、どうしたものかと、あちらの旧大崎図書館のことですね。思っていたが、こうした場所、御殿山のほうですね。ですから、老朽化というふうにずっと今まで説明されてきましたけれども、もう一つの理由として、２９号線、移転、これがあるのではないか。その点についてはどうなのですか。","respondent":"横山品川図書館長","answer":"移転の理由につきましては、先ほどからご説明しました老朽化による改修が追いつかないという部分とともに、先ほどＳＨＩＰとの連携という部分を大崎図書館が担っていたということもありまして、そういう意味では、移転のチャンスだったというのも一方です。","voiceIndex":72,"id":"exchange-022"},{"speaker":"南委員","kind":"確認","question":"私が聞いたのは、２９号線の問題、大崎図書館移転を区が判断した材料の一つに、この２９号線があったのではないかと思っていて、ずっとこの間もそういう立場で質問もしてまいりまして、図書館の移転はだめだというふうに言っていたのですけれども、いみじくも区長がその開所式のときにそういう発言をされたので。","respondent":"横山品川図書館長","answer":"近くにあったほうがいいというのはすごくわかるのですが、そういう意味ではほかの地区でこのように３箇所に設けられて、それこそ歩けば１０分かからないでどこかの図書施設に行けるという環境を整えられたというのは、結果的には恵まれた状況を確保できたものだと認識しています。","voiceIndex":74,"id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"やはり、でも、区長の発言というのは重たいですよ。そこをいろいろ担当のところで北品川に用地ができて、ＳＨＩＰとの連携ができるとか、そういうことを繰り返しておっしゃるけれども、やはり基本的な移転の理由というのは、２９号線、これがあるのではないかなというふうに思うのですけれども、違うのですか。それともう一つ、そういう決定をやはりしているはずですよね。その点についてはどうなのですか。","respondent":"本城教育次長","answer":"２９号線の関係につきましては、私どもがわかる範囲で、認識のところも含めてですが、現在もまだ企画や総務部のほうから聞いているところでは、東京都の間で具体的な協議をしているけれども、どういう形になるか今も協議中だということです。","voiceIndex":76,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"やはり、２９号線が通ることを想定してこういう対応をとっているのではないのですか。そして、これは間違っていましたというふうな、私の希望ですけれども、そういう考え方は間違っていたと、あそこの施設はまだ残っているから、ここで地域の皆さんに大切にしていただいた図書館をもう一回再開しますよと、そういう判断にするべきだというふうに思うのですけれども、それはどうですか。","respondent":"本城教育次長","answer":"それと、２９号線の関係については、私ども聞いているところですが、現時点においても東京都と協議をしているですので、そういう意味からしても、移転につきまして、それ自体については先ほど来ご説明した三つの要因によって総合的に判断して決めた、そのような経緯です。","voiceIndex":78,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"だから、ここで１年近く取次施設があるからいいのだというふうにはならないというのが地域の方の声ですよね。しかも、芳水小学校のところは、上が体育館ですか。そういう点についてどうなのかということ。それと、芳水小学校と取次施設があるからいいのだと、こういう考え方にはならないというふうに思うので、そこについてはどういうふうに思うのかを改めて伺いたいと思います。","respondent":"横山品川図書館長","answer":"芳水小学校の体育館の下ですけれども、音がする真下では全然ございませんし、図書館の環境を維持する標準というので、音がしないようにという確認をしながらの設計となっておりますので、そういう意味では全く音がしないということはないと思いますけれども。","voiceIndex":80,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"最後にしたいと思いますが、私、ちょっと誤解されるといけないので、申し上げたいと思いますが、御殿山にできたあの図書館は必要ないとか、そういうつもりは全くありませんし、この間ずっと主張しているように図書館というのはそれこそ本当に５分ぐらいで行けるような、そういう地域に存在していただくことが一番いいわけですから、それはそれとして図書館機能を十分果たしていただいて。","respondent":"横山品川図書館長","answer":"解体の費用を改修のほうにというお話ですが、例えば地下の書庫の改修だけでもそれ以上の金額がかかるような見込みが出てきているような状況が見られた中で、それぞれの改修をするよりは、全部移転してしまったほうが、先ほど申しましたように。","voiceIndex":82,"id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"今説明は、私的にはまだ反論したいと思っていますけれども、次の時期に譲りたいと思いますが、最後にＳＨＩＰとの関連なのですけれども、ＳＨＩＰを前に視察をしたときに、蔵書数なんてとんでもない、これでＳＨＩＰがあるからというふうに言っていたのか、とすごく私は憤りを覚えた経験があるのですけれども、ＳＨＩＰとの関連というのであれば。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「平成２７年４月より大崎図書館ユーザーの会として、大崎二丁目の大崎図書館の存続を求めてお願いをしてまいりました。そういった意味では、まだまだ十分補修可能なのになぜ解体するのか、この疑問に私は十分答えていないと思うのです。区民の理解を得ることが自治体の役割として必要であると思うのですが、この辺、私はここが一番大事だなと思っているのですけれども、いかがでしょうか。","respondent":"横山品川図書館長","answer":"解体については、区民の方へのご説明等はするような運びだというふうに聞いております。","voiceIndex":85,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"理解を得ていませんよね。空き家のままにしておいたら危ないと。この間もずっと努力をされていたけれども、今行政にこの住民の方々、利用者の方々が意見を聞いてほしいというので、この議会にこの請願が出されたのですよ。廃館とおっしゃって。そこの自覚をしっかりしないと、同じご答弁をされていても、何か空中を飛んでいるだけで、説得力が全くないなと思っているのですが、その辺はいかがでしょうか。","respondent":"横山品川図書館長","answer":"私も大崎図書館がすごくすてきな施設だなとは思っておりました。そういう意味では時代の状況で手放すことになってしまいましたけれども、そういうところを一緒に受けとめていただいて、次に進めればいいなと考えています。","voiceIndex":87,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"今、最後、時代の状況とおっしゃいましたでしょうか。図書館はもちろん公の施設、地方自治法第２４４条に書かれている公の施設なのですけれども、ここに「住民の福祉を増進する目的をもってその利用に供するための施設」と書かれているのですが、この中身をどう受けとめていらっしゃるのかなというのを今日伺いたいのです。私たちは施設利用に対しては、住民本意になってほしいな、原則にしてほしいなと。","respondent":"横山品川図書館長","answer":"西口の従来から利用されている方の欲しいという気持ちを区のほうが最大限に取り入れた形で分館というのが、区としては施設を増やさないという方針に、ある程度反した形で分館というのを設けたというところで。","voiceIndex":89,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そろそろまとめますけれども、とにかく今回の新しい北品川に移した時点において現状の大崎二丁目のところは不便になる、これは認めていらっしゃると思いますけれども、そういった立場だったら、本当に最大限地域のために考える、今新しい図書館をつくらないけれども、分館をつくっていく最大限の努力をしたというところですけれども、私はここにとどまらず。","respondent":"横山品川図書館長","answer":"そういう意味では、先ほど申しましたように、大崎地区には３拠点というような形で品川区内の中でも図書環境としてはかなり重点を置かれたような位置づけになってあります。この中で、もう１拠点というのは、今の状況ではあまり現実的ではないと考えております。","voiceIndex":91,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後に言っておしまいにしますけれども、大崎は今すごく変わっていますよね。駅周辺の超高層化がどんどん広がっている。線路で分断をされ、目黒川で分断をされている。自転車に乗っていくのも大変といった状況の中で、私はぜひ地域バランスと言っているのだったら、この地域の活用度合い、今後のまちがどう発展していくかはわかりませんけれども、再考をぜひしていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"施設が老朽化して雨漏りがある、前も書庫の部品が取り寄せられなくて、それを全部入れ替えるとなると大変なことになると伺いました。そのようなことだった。こちらに今回お示しいただいている松原傅吉さんのご親戚の方も、芳水小学校にというところで一生懸命動かれて、これが実現したというふうに伺っているのですが、その辺の認識が間違っているか、間違っていないか、もう４年前の話なので教えてください。","respondent":"横山品川図書館長","answer":"そういう意味では、地域の方のお声を受けた分館です。松原傅吉さんが私財を投げ打って図書館を建てていただいたというのはすごく認識しておりますので、何とかその思いを残せないかということで、今遺構なり何かを残せないかということで工夫を重ねているところです。","voiceIndex":94,"id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"承知いたしました。当然隣にあったものが１０軒先に行ったら不便になるわけですから、ただ、その１０軒先の人はすごく便利になるのだろうな、この３９万区民の要望をどういうふうに捉えていくかというのは行政の仕事、ただ、これは文教委員会でやる話ではないので、先になりますが、ちょっとそれとは違うような話がずっと議論されていたので、それって違うのにと思いながら聞いていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"いいと思うのですけれども、そういう運営で。質疑されていない会派の方々の態度について、どういう態度をとったのかについての理由、それはぜひ述べていただけるようにはからっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-036"},{"speaker":"渡部委員","kind":"意見","question":"先ほど述べさせていただいたようなところもあるのですけれども、大崎図書館の移転の前の話として、ここの図書館を例えばほかの用途に転用する場合とか、擁壁がどうした、何がどうしたというので、かなり傾斜地で難しいところだというような議論を行財政改革特別委員会等でされてはいたのです。この図書館移転の前に。それについて今後どうするかというのは、またじっくり考えていけばいいところだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-037"},{"speaker":"つる委員","kind":"提案","question":"大分前ですけれども、２０１４年だったでしょうか、この大崎図書館にかかわる請願が出たときに私が申し上げたのが、場所が移る、移転ということに際しては、やはり奥の細道ではなくて、図書の細道みたいなものをつくって、今まで近くにあった人たちがそこに行くまでを楽しみながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"意見","question":"結論を出すということで、採択を主張します。ぜひ文化的な交流の拠点として公の施設、ここを再生してほしいという願いは、私は当然であると思っています。特に利用者、住民の方の声を受けとめて、品川区は再検討すべきであると考えています。そして、あわせて２９号線の代替地とされることに対しては、２９号線先にありき、道路ありきといった意味では、とても納得できるものではない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-039"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"結論を出すで、我が会派としては、不採択を主張いたします。理由としては、この間長きにわたってこの大崎図書館については議会でもさまざまな議論があったと思います。これからも地域の皆様にまずご理解をいただいて、そしてさらにご利用していただけるような図書館運営をぜひやっていただきたいなと思います。それは要望でお願いしたいと思います。よって、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今回の請願のみならず、これまで何年か文教委員会に所属させていただいて、こういった地域の方々のご意見を伺って、さらに行政の方の説明も伺ってきました。こちらの請願にあるように、今までの思いは十分に理解させていただいています。ということで、今後の運営をさらに進めていって、より代替のところで進めていってほしいとお願いをしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4944#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":37516,"voices":109}},{"id":"h30-20180702-5","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"総務委員会","time":"午前１０時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５８号議案、戸越台複合施設大規模改修工事請負契約、(6)第５９号議案、戸越台複合施設大規模改修機械設備工事請負契約および(7)第６０号議案","agenda":"第５８号議案、戸越台複合施設大規模改修工事請負契約、(6)第５９号議案、戸越台複合施設大規模改修機械設備工事請負契約および(7)第６０号議案","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"この後の、後地小学校などでも、同じような入札の説明があろうかと思いますが、個別にどうこうという質問ではなく、入札全体に関して質問させていただきたいのですが、まず、近年、入札不調とか工期の遅れとかがあったのかどうなのか。工期に関して、今、既に着工されている施設もあろうかと思いますので、それも含めて、現状を教えていただきたいということで、お願いします。","respondent":"立木経理課長","answer":"入札不調の件ですけれども、平成２９年度ですが、件数は５９件ほどございました。不調率としましては６.６％になりまして、不調になった後、不調随契として２１案件、契約しております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そうなってくると、労働者の職場環境が著しく変わってくるというのかな、突貫という言い方が正しいかどうかわからないですけれども、長時間労働を強いられる可能性も出てきますので、この第２回定例会で議案が上程されて、議決されて、翌日からおそらく着工していくと思うのですが、例えば前年度の第１回定例会ぐらいで翌年度の債務負担行為か何かで、３月中、前年度にはこういった部分を議決なり何なりして。","respondent":"立木経理課長","answer":"完成期日がどの程度になるかという部分に関しましては、それぞれ工事の所管のほうできちんと工期を見ながら設定していると認識しておりますが、余裕を持たせた工期という部分に関しましては、しっかり所管に伝えながら。","voiceIndex":9,"id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それが実際、積み上げの中で十分間に合ってつくったものなのか、それとも、行政より早く、関連するＪＶの方々が、やっぱり職場環境は優先させなければいけないから、多少こっちが持ち出ししてもやろうよという話で、１つの事例として、こういう環境が必要だよということから設置したか、その辺は詳しく聞いていないからわからないけれども、非常にいいスペースがあったと記憶が鮮明に残っているので。","respondent":"立木経理課長","answer":"積算単価につきましては、きちんと市場の動向とかを見極めながら、きちんと私どものほうでしっかり検討させていただきたいと思いますので、よろしくお願いいたします。","voiceIndex":11,"id":"exchange-003"},{"speaker":"いながわ委員","kind":"意見","question":"最後に、市場の動向は重々わかっているのです。だから、要はそれを受注したＪＶの人たちとしっかりコミュニケーションをとっていただいて、やっていただく。そうなってくると、また新しい入職者がもしかしたら増えてくるかもしれないし、今後、そういう人たちを育ててもいかなければいけないと思うので、しっかりお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"もう１点、例えば工期を短くするために、仮設の学校や介護施設をつくって、短い期間で工事を進めていくという手法は、今回の工事を進めるに当たり検討されて結果的に、今回の手法が一番合理的だということなのかどうか、その検討経過についても伺いたいと思います。","respondent":"小林施設整備課長","answer":"今、委員の質問のとおり、居ながら工事ということで、各部署と数年にわたって打ち合わせはしてきました。それぞれが居ながら、引っ越しも含めて、いろいろな方面から、いろいろな方策、いろいろなところを検討しました。","voiceIndex":15,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望ですけれども、介護施設を利用されている方、また、学校等を利用されている方、保護者の方に十分理解を求めて、できるだけ影響が伴わないように進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"この工事によって、減価償却というよりは、どれだけ建物自体の耐用年数が延びるのか、使えるような状況になるのか、教えてください。この建物がいつごろできたのかも、参考にお聞かせください。","respondent":"小林施設整備課長","answer":"この建物は、平成８年にできて、２２年経過しております。逆に言うと、大規模改修というのは２０年ぐらいを目安にやっていく。そして長寿命化、建物を長く使っていくということがあります。先ほどの、２点の質問については、約２０年おきに大規模改修が望ましいです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"もう１点。本体の基礎は変わらないわけですよね。そうすると、これをやることによって、これだけの金額をかけて、どれだけこの建物が使える状況になるのか。その辺について、今回、全面改修すれば、あと３０年、いや、４０年もちますよというような計画を立てた上で工事を行うと思うのですが、その辺について教えてください。","respondent":"小林施設整備課長","answer":"先ほどもちょっとお話ししましたけれども、まずはいろいろな工事手法を検討したときに、まず一番に考えたのは、居ながら工事で、全面的な建て替えとなれば工期はもっとかかる。それと同時に、特養と学校の引っ越し先を考える。","voiceIndex":21,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"改修工事を今後進めていけば、３０年、４０年、５０年もちますよというような根拠を教えてください。できるだけ高層階にはしないほうがいいというお話も聞いているのですが、ここに関しては、何かあったときの避難経路、また、避難に対するさまざまな方策等は、完璧にできているのでしょうか。その２点だけお聞かせください。","respondent":"小林施設整備課長","answer":"そこまでは当然使っていくです。それから、避難経路、これも工事をするわけですので、それが第一の優先。避難経路ができなくて工事が着工できるかといったら、それはできませんので、避難経路を確保しながら工事をしていくです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"複合施設ということで、これからこういう複合型の施設が増えていくと思うのですけれども、基本的なことなのですが、予算の見方とか考え方、これは複合施設なので予算もそれぞれ民生費、教育費になっているのですけれども、これから複合施設が増える中で、予算の点検、決算の妥当性の点検というときに、それぞれどういうふうに支出されるのか、その基本的な考え方と、それから、それぞれの款と項のところで。","respondent":"小林施設整備課長","answer":"完璧に特養だけにしか使わない施設だとか、学校しかないものとか、そういう分けられるものについては、基本的にはそれぞれのところに振り分けております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"概ね予算を立てる段階で、案分ができる程度のところまでは詰められてから予算が立ってというふうに、いつもそういうふうに流れていくと考えてよろしいのでしょうか。","respondent":"小林施設整備課長","answer":"基本的にそうです。面積は見積もりの段階で床面積が出ますので、共用で使っているものについては、案分で見積もり金額を出しております。先ほど言いましたが、分けられるものについては分けて、それぞれのところの科目で見積もるというところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、予算の段階でそこまで詰めているのであれば、決算でずれることはあり得るというのは、承知しているのですけれども、この段階で大体それぞれの所管でこれぐらいというざっくりした金額とか、そういうものも出せないのでしょうか。予算の点検などを考えると、そのほうが私たちの役割を果たす上でもありがたいのですけれども、いかがでしょうか。","respondent":"小林施設整備課長","answer":"ただ、今言ったように、面積案分で原則やりますので、そちらで見積もり金額を施設整備課から各所管にお知らせするというところです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"大規模な改修工事ということで、平成３４年まで工事が続きますが、工事のことで１点だけお聞きいたします。電気設備工事、屋上の緑化など、本当に大規模な工事を長期間行うと思うのですけれども、運搬や搬入などについてお聞きいたしますが、外壁に足場を３方向、４方向、全面なのか、足場をどういうふうにやっていくのか、工事の搬入や運搬も含めてお知らせいただきたいと思います。","respondent":"小林施設整備課長","answer":"いつやっていくかとか、そういうことも打ち合わせをして、今後、工事を進めていくというところです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、平成３４年まで工事が続くわけですから、足場もずっとかけっぱなしと理解してよろしいですか。","respondent":"小林施設整備課長","answer":"外壁につきましては、４４カ月の間、足場をずっとつけるというわけではなくて、終われば当然そのときから撤去していくです。","voiceIndex":37,"id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"賛成です。ぜひ私が質問した内容を、経理課長のみならず、施設整備課長も共有の問題意識を持っていただいて、取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"}]},{"id":"topic-02","title":"第５６号議案、中小企業センター空調設備改修第二期その他機械設備工事請負契約","agenda":"第５６号議案、中小企業センター空調設備改修第二期その他機械設備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいのですけれども、契約を結ぶときに、第一期と第二期に分けるときと分けないときというのは、どういう根拠に基づいているのか。先ほどの戸越台複合施設の工事は分けずに、この後の芳水小の工事は第一期、第二期と分けるのですけれども、その考え方を教えていただけますか。","respondent":"小林施設整備課長","answer":"先ほどの戸越台複合施設につきましては、関連するところがあり過ぎて、工事を分けることができませんでした。４４カ月を一連でやらないと、居ながら工事ができないという判断をしました。","voiceIndex":70,"id":"exchange-016"}]},{"id":"topic-03","title":"ピック・パラリンピック施設周辺道路整備工事（その１）請負契約、第６６号議案、オリンピック・パラリンピック施設周辺道路整備工事（その２）請負契約、第６７号議案","agenda":"ピック・パラリンピック施設周辺道路整備工事（その１）請負契約、第６６号議案、オリンピック・パラリンピック施設周辺道路整備工事（その２）請負契約、第６７号議案","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"確認なのですけれども、オリンピック・パラリンピック施設周辺工事というのは、東京都からの受託事業になるのでしょうか。","respondent":"多並道路課長","answer":"ただ、都と国の考え方で、今回のオリンピックを契機に、オリンピック会場周辺の無電柱化を進めることについては、国費が半分で、残り半分も都費として、重点的に財源として区へ補助できるということで、このような連携をしながら進める事業の位置づけです。","voiceIndex":85,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"であれば、道路課長がいらっしゃるので、これをやったことによって、今後の品川区内における電線類地中化に対するビジョンがあれば、簡単で構わないので、多少契約案件から外れてしまう部分があるのですけれども、もしお答えができるのであれば、あくまでも４年に１回のオリンピックで、５０年ぶりにオリンピックが東京に来て、それを機にやろうよというのは重々わかるのですが。","respondent":"多並道路課長","answer":"区としましても、今取り組んでいる会場周辺の無電柱化はこの計画に沿っているところですけれども、それ以外に、安全・円滑な交通獲保であったり防災だったり、いろいろな観点から計画されていますので、そういうものを研究しながら、今年度。","voiceIndex":87,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"第６５号議案の説明でありましたが、３７ページの下にある公告文に記載のとおり入札を無効としたということが、どういうことを担保するための仕組みなのか、よくわからないので、ご説明をいただきたいと思います。あわせて、第６７号議案のエレベーター設置ですけれども、随意契約となっておりますが、その理由を伺いたいと思います。","respondent":"立木経理課長","answer":"最初に、第６５号議案の公告により無効という部分ですが、工事のほう、いろいろな事業者に受注していただくということで、公告の中で事前にお知らせをさせていただきまして、当日開札する入札案件のもので、先に入札案件で落札した事業者は。","voiceIndex":91,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"第６７号議案のエレベーターのほうですけれども、工事そのものは必要だと考えています。ただ、疑問として残るのは、東京モノレールを利用する方のための工事であるならば、東京モノレールが自分でやるという考え方もあるのかなと。それを区の工事としてやる理由について、ご説明いただきたいと思います。","respondent":"多並道路課長","answer":"そういう関係で、いろいろなことを考えた結果、東京モノレールと協定を結んで実施することが一番妥当だろうということで、今回は随意契約とさせていただいているところです。","voiceIndex":93,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"その関係性はわからなくもないのですけれども、東京モノレール自身のお金で駅を改修するのではなくて、区の工事としてやる理由が何かなと思いまして、そこを伺いたいです。","respondent":"多並道路課長","answer":"今回、我々が行いたいのは勝島歩道橋、いわゆる競馬場前駅の目の前にある歩道橋のバリアフリー工事です。","voiceIndex":95,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"３７ページの下の部分に、その１については、鈴中工業株式会社東京支店は入札無効という話が出ていますが、先に落札が決まれば次は落札ができないというお話だったと思うのですが、順番からすれば、その１を先にやって、次にその２ではないかと。というのは、何で鈴中工業はその１を受けなかったのか。ここで外される必要があったのか疑問に思うのですが、教えてください。","respondent":"立木経理課長","answer":"説明が足らず、申しわけございません。開札の順番をあらかじめ公告の中でもうたってございまして、今回は、同日開札で金額の大きいその２のほうが先になってあります。","voiceIndex":98,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"もう１点、企画調整課に聞いたほうがいいのかなと思ったのですが、オリンピック・パラリンピック施設周辺道路整備工事ですが、先ほど区が積極的にみずから申し出て道路整備工事を行うということで、その根本には、オリンピック・パラリンピックもありますが、区内道路の防災上の安心・安全も兼ねてということで、もし積極的に行うならば、区としてより電線地中化をしなければいけない道路があるはずですから。","respondent":"多並道路課長","answer":"今回の工事につきましては、もちろん先ほどご説明させていただいたオリンピック会場周辺の無電柱化が大きな目的ですけれども、あわせて競馬場通りにつきましては、緊急輸送道路ともなっていまして、防災上も非常に重要な道路となっています。","voiceIndex":100,"id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認をさせていただきたいと思います。競馬場駅前の通りと大井ふ頭中央海浜公園のところの道路と、それぞれ別々に入札を出しているのですけれども、ここは一括して同じ業者に対しての工事ということではなくて、別々に入札を出しているのはどうしてなのか教えていただけますか。","respondent":"多並道路課長","answer":"その際、一番の命題となりますのが、オリンピックまでに間に合わせること、それから現場条件を考えまして、どうしても２分割にしないと工事が終わらないと考えまして、それで現場を２つにして、同時施工しながら進めていくという計画とさせていただきました。","voiceIndex":103,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"賛成なのですけれども、１つだけ要望です。先ほどの質疑で、この契約内容については、とてもよくわかったのですけれども、これは要するに半額分の契約だと思うのですが、それは判断する上で重要な情報であると思います。できるだけその辺の情報を資料として出していただけると、ありがたいなと思います。結論としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"こちらの工事ですけれども、戸越台中のときは１カ所あけて特養ホームを持ってきて、また直して戻るという話がありましたけれども、こちらの荏原複合施設の場合は、こちらも居ながら工事になるのかなと思うのですが、利用者への影響に対する対応はどのように行っているのか、伺いたいと思います。","respondent":"小林施設整備課長","answer":"こちらも、居ながら工事でありますので各所管と打ち合わせをしながら、なるべく支障のないように工事を進めていくスケジュールを立てていきます。","voiceIndex":138,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"議案の内容とちょっと違うのですが、せっかく建物の配置図を出していただいたのですけれども、古い地図なので、平塚小学校とか平塚中学校が載っていて、せっかくいろいろ努力されているので、新しいものにかえていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-027"}]},{"id":"topic-04","title":"第４５号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第４５号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今回の変更で、災害派遣手当自体に何か変更があるのかどうか、その点だけ確認したいと思います。","respondent":"黒田人事課長","answer":"今回、旅館業法の改正に伴う文言修正だけですので、そのほかにつきまして改正等があるものではございません。","voiceIndex":155,"id":"exchange-028"}]},{"id":"topic-05","title":"第４６号議案、品川区特別区税条例の一部を改正する条例","agenda":"第４６号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"（３）給与所得控除・公的年金等控除から基礎控除への振替に伴う調整というところについて伺いたいと思うのですけれども、まず、給与所得控除と公的年金等控除と、それぞれ意味合いが異なるものを基礎控除として振りかえるというのは、問題があるのではないかと思うのですけれども、その点について、理由と見解を伺いたいと思います。","respondent":"伊東税務課長","answer":"それからフリーランスの方々への影響というか、どのぐらいかということは、なかなかいろいろな指針があって難しいところではありますけれども、営業所得というところを見て拾ってみますと、大体１万人弱、９,８００人ぐらいいるのではないかと考えるところです。","voiceIndex":170,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"給与所得控除と公的年金等控除のそれぞれの給与と年金という意味合いの異なるものを振りかえてしまうのは、もともとの考え方に照らして、おかしいなと思います。今回、直接条例の変更には盛り込まれていないものの、給与所得控除の上限の引き上げは、勤労世帯や中間所得層への増税となるため、この点は進めるべきではないと、意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-030"},{"speaker":"中塚委員","kind":"意見","question":"今回、５つの変更ということですので、それぞれコメントしたいと思いますけれども、まず、１つ目と２つ目のたばこについてですが、たばこの害に対して、課税し、規制をするという方向は、賛成です。３つ目のフリーランス、請負、起業等の方々の税金が安くなるという点は評価できますけれども、法律の背景にある給与所得控除の上限引き下げについては問題があると思います。以上の点から総じて賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":176,"id":"exchange-031"}]},{"id":"topic-06","title":"議案質疑を行います。 次に、(15)の第６８号議案 防災行政無線設備更新工事請負契約","agenda":"議案質疑を行います。 次に、(15)の第６８号議案 防災行政無線設備更新工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"確認なのですけれども、平成３３年度で屋外全ての防災無線の更新、要は新しくかえていくということだと思うのですけれども、今年３４カ所ですが、全体では何カ所あるのか。","respondent":"古巻防災課長","answer":"ただ、今、委員からもお話がありました聞こえづらいものの解消ですとか、そういったことも含めて、今のところ２３局増設する方向で検討しておりますので、最終的には１５６局で運用するという予定で、平成３３年度末までに工事を終わらせるような計画で進めております。","voiceIndex":187,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、お考えがあるかどうか。なければないでいいです。","respondent":"古巻防災課長","answer":"スピーカー自体の直接的な更新ではないですけれども、そういった周辺の技術も含めて更新をしていきたいと考えております。","voiceIndex":189,"id":"exchange-033"},{"speaker":"新妻副委員長","kind":"質問","question":"資料に設備数は３４カ所と書かれておりますが、前にも会派から申し上げさせていただいたことがあったと思うのですけれども、大井町の駅周辺は、人が多く集まる割には聞こえにくいという課題があるのかなと思っておりまして、この大井町駅周辺の聞こえにくさの改善は、いつの段階でされるのでしょうか。","respondent":"古巻防災課長","answer":"今年度新設をする場所につきましては、主に港湾部を予定しておりまして、大井町駅の入り口になるかと思いますけれども、そちらの更新については、平成３１年度の予定で、今計画を立てているところです。","voiceIndex":191,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年防災無線、行政無線に対しては、いろいろ区民の方から様々な要望が来ています。その時に情報をどうやって得るのだと、電源が切れてテレビも何もだめになる、まだ若い人はスマホとかを持っていれば対応できるかと思うのですが、やはりそういうときに情報を得られない弱者が大勢いるということを考えて、私は早急に抜本的な対応をしていただきたいと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-035"}]},{"id":"topic-07","title":"第６９号議案 しながわ区民公園南側ゾーン改修工事請負契約および第７０号議案 しながわ区民公園水処理施設改修工事請負契約","agenda":"第６９号議案 しながわ区民公園南側ゾーン改修工事請負契約および第７０号議案 しながわ区民公園水処理施設改修工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"それと、必ず夏を２回越えなければならないと思うので、夏の時というのは、これはもうオープンスペースなので、工事をすればすごくほこりが舞うと思うのです。それは去年もそうでしたので、だからそういうところの対策とかをしっかりやっていただいて、あとは水族館に訪れるお客様に対しても不便がないようにやっていただきたいと、これは要望です。","respondent":"溝口公園課長","answer":"工事現場の環境ですけれども、公園の場合、仮設事務所を設けてやりますので、現場で働く作業員の方々がしっかり休憩がとれる場所とか、そういったものにも配慮しながら。","voiceIndex":207,"id":"exchange-036"},{"speaker":"いながわ委員","kind":"質問","question":"ＪＶでやられると思うので、これも同じことを何回も言ってもあれなのですけれども、しっかり働いている方々のいろいろな意見とかヒアリングをぜひしていただいて、こういうのがあったほうがいいのではないですかというのは、予算がどうこうとかではなく、品川区も多少なりとも負担が増えるかもしれないですけれども、しっかり意見を聞いて、よりよい職場環境をぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"基本的なことを教えてください。それから、さらに基本的な質問で申し訳ないです。同じく工事内容の便益設備工３基というのは、言葉の意味がわからないので、教えてください。","respondent":"溝口公園課長","answer":"ちょっと専門用語になって申し訳ありませんが、主に今回提案しているのが、子どもたちが水を飲める施設、または今回勝島の海に多少人が入れるような想定をしておりますので、そういった中で手を洗ったり足を洗ったりすることができる施設を今回３基新たにつくりますので。","voiceIndex":210,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"便益設備についてですので大丈夫です。質問した内容についてはわかりました。それで、だれでもトイレの整備なのですけれども、前にあったことなのでもう二度とないと思いますけれども、だれでもトイレと言っておきながら、肝心の車椅子を利用する障害者の方が使えなかったという事例があったので、その辺についてはぜひ当事者の方たちが使えるということを確認して、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"水処理施設改修工事ですが、これはたびたびやらなければいけないのかなとは思うのですが、大体何年ごとに改修工事をするようになるのですか。浄化したりするのでしょうから、そのメンテナンスも毎年相当かかるのかなと思うのですが、大体毎年幾らぐらいかかって、さらに何年ごとにこういう大きな改修工事をするようになっているのでしょうか、教えてください。","respondent":"溝口公園課長","answer":"水処理施設です。今回、しながわ区民公園の開園以来３０年以上そのままずっと使ってきたものを、今回初めて改修するものです。","voiceIndex":216,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"特に海から水を引いて云々するのか、あと、しながわ区民公園に入ってきたものをまたきれいに浄化して流すのか、いろいろあると思うのですが、結構こういう水処理施設というのは、今、先ほどポンプとかというお話もありましたけれども、やはりメンテナンスは相当大変なのでしょうね。その辺をどれだけ費用がかかるかというのを大まかでお聞きしたのですが、わかる範囲で教えてください。","respondent":"溝口公園課長","answer":"そういったものを適正にやることによって、今回新たに水施設を少しでも長期に使えるようにしていきたいと考えているものです。","voiceIndex":218,"id":"exchange-041"},{"speaker":"吉田委員","kind":"確認","question":"先ほどトイレの話をしながら１点聞き忘れました。だれでもトイレの中に、多分ベビー用のおむつ交換ベッドはつくと思うのですけれども、それをユニバーサルベッドにしていく方向だと伺っていたので、今回の場合はどうなのでしょうか、確認させてください。","respondent":"溝口公園課長","answer":"例えばそこのベッドを使って寝られる方とかもいますので、様子を見ながら、また何かありましたらしながわ区民公園の管理事務所に行っていただければ対応できるようになっておりますので、そちらのほうをご利用いただければと考えているものです。","voiceIndex":220,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことがあれば、それほど長くそこで寝てしまう人も、本来の目的以外で使う人への対策にもなるかと思いますので、その辺をぜひ検討していただいて、障害者を含めて多くの人がこういうところに遊びに来るわけですから、今後の方向として考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-043"}]},{"id":"topic-08","title":"第７１号議案 浜川公園改修工事請負契約","agenda":"第７１号議案 浜川公園改修工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"例えば遊戯施設、健康器具の周りがみんな低木なのか高木なのかわからないですけれども、緑が植わっているのですけれども、ちょっと死角になるところなのかなと私は思ったので、お伺いします。それから、そういう死角があるということは、やはり公園ですから、防犯カメラ設置の考えはこの公園にあるのかないのか、わかる範囲でお願いします。","respondent":"溝口公園課長","answer":"なるべく死角がないような形での設計を進めているところですし、今後公園内での防犯カメラの設置を進めているところですので、当然改修に合わせて、防犯カメラについても整備していきたいと考えているところです。","voiceIndex":245,"id":"exchange-044"},{"speaker":"いながわ委員","kind":"質問","question":"低木・高木に関しては、死角がないようにしたほうがいいのではないかという思いで質問させていただきました。今回のこの落札した予算の中に、もちろんわからないですけれども、そのキャッチボール場に設置するネットに関しても、防犯カメラも含めて全部入っているという認識でいいのですか。","respondent":"溝口公園課長","answer":"防犯カメラについては、今全体含めて公園の中での整備というのを考えておりますので、そういった中で整備をしていきたいと。もしかすると工事期間中、少し長くなりますので、その中でうまくほかの工事を入れて、防犯カメラの設置は考えていきたいと考えているところです。","voiceIndex":247,"id":"exchange-045"}]},{"id":"topic-09","title":"日程(8)、第６１号議案になります。第６１号議案 芳水小学校第２期校舎改築その他工事請負契約","agenda":"日程(8)、第６１号議案になります。第６１号議案 芳水小学校第２期校舎改築その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"外構工事の中に、校庭の整備で人工芝となっているのですけれども、図面では全然読み取れません。校庭の全体が人工芝となるのでしょうか。それから、人工芝は、質と価格がいろいろあると思うのですけれども、どのような判断で、どのレベルの人工芝を採用するのか教えてください。","respondent":"小林施設整備課長","answer":"人工芝の質は、グレード的には中ぐらい。いわゆる上もあればですけれども、基本的には教育委員会と打ち合わせをして、各学校いろいろありますけれども、各学校と一緒に質を合わせてやっていますので、ここだけ高いものにはなりません。","voiceIndex":263,"id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"ほかと合わせなくてはいけないのはわかるのですけれども、そういうことに対しての何か反省点というか、そういう声が活かされたとかということはないのでしょうか。あくまで同等のものでという判断をされたと理解でよろしいですか。","respondent":"小林施設整備課長","answer":"人工芝につきましては、さきほど言ったように平均な質のものですけれども、当然技術革新ではありませんけれども、人工芝もその都度よくなっております。","voiceIndex":265,"id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"少し安心をいたしましたが、やはり校庭を使うのは子どもたちなので、その後の使い方、契約ですからお値段のことが考慮されるのは当然なのですけれども、その辺はぜひ今後も配慮を続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"基本的な質問です。３２ページの給排水衛生設備工事で、雨水利用設備と太陽熱利用設備とあるのですけれども、どういう形で雨水、それから、太陽熱が利用されるのか教えてください。それと、３５ページのほうの太陽光発電設備は何Ｋｗぐらいで、どの部分に使われるのかを教えてください。","respondent":"小林施設整備課長","answer":"雨水利用ですが、雨水利用は２５m3をトイレの排水、ならびに屋上関係の緑化の散水に使います。次に、太陽光の熱給湯関係は２４m2設置する予定です。これを何に使うのかというと、利用目的はプールのシャワー、それから給食室関係に給湯として使う予定で考えております。","voiceIndex":281,"id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"トイレの排水にも使うということで、生活者ネットワークとしては大変推進したほうがいいと考えますのでよかったと思うのですけれども、２５m3というとどれぐらいなのですか。参考のために申し訳ないのですけれども、教えてください。","respondent":"小林施設整備課長","answer":"２５m3は、基本的には一般の教室で使えるかなというようなことだと思います。ただ、集中してずっと使っていれば当然なくなりますし、晴天が続いた場には、水道のほうに換えるということになるので、いわゆるどのくらい使えるのかというご質問になると、そのような感じです。","voiceIndex":283,"id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ご説明ありがとうございました。２６ページの本体の新校舎建築工事なのですけれども、今既存の学校の構造は、鉄骨コンクリート造だと思うのですけれども、今度は新しく構造体が鉄骨造になっているというところがあるのですね。それはなぜＲＣ造からＳ造になったのかということをまずお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"ではその方法はどうするといった時に、鉄骨、これも狭隘道路なので長いものは入りませんけれども、それを現場の小学校のほうに入れてそこで組み立てるというのが、台数を減らす唯一の方法であるので採用したものです。","voiceIndex":285,"id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。そうすると、やはり安全面なども考慮していかなければいけないので、これから工事が始まる前に土壌の改良をするのかどうかわからないですけれども、土止めの工事とかいろいろあるのと、あと擁壁の問題とかありますよね。その辺のところもご留意、ご注意していただいてやっていただきたいです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-052"},{"speaker":"いながわ委員","kind":"質問・要望","question":"賛成でありますが、この今の議案で全て改修工事とか設備工事という説明が終わりまして、先ほど前段で午前中に私が申し上げたようなこと、工期の問題や職場環境については全てに該当するということをどうかお酌み取りいただきながら、工事を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-053"}]},{"id":"topic-10","title":"平成３０年陳情第８号 同性パートナーシップの公的承認","agenda":"平成３０年陳情第８号 同性パートナーシップの公的承認","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"確認したいのですけれども、どう質問していいかもなかなか自分の中では困っているところで、例えば大手企業というのはダイバーシティの推進ということで、誰もが参画できるようなフィールドをつくっていく。されているのであればいつからやっているのか。逆に言えば、学校側というか生徒がそれを受けた時に、そういう方々もいるんだろうねという話なのか、その雰囲気がわかれば教えていただきたいと思います。","respondent":"島袋人権啓発課長","answer":"子どもたちへの教育ですが、やはり平成２７年あたりですか、文部科学省のほうからも、ＬＧＢＴとは正式には申し上げておりませんけれども、対応指針のようなものが出ておりますので、品川区におきましては教育総合支援センターのほうで、多分市民科だと思いますけれども。","voiceIndex":320,"id":"exchange-054"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えばもし、この陳情で訴えていることをすべて受けてしまうと、いろいろな部分で、ではトイレの問題はどうするのだとか、逆に言えば同じ性的マイノリティの方々も、この中に含まれていないという方々もいらっしゃると、いろいろ今週刊誌とかニュースとかいろいろな部分でそういう話が氾濫していますから、そういうことも踏まえた上で。","respondent":"島袋人権啓発課長","answer":"私どものほうでも、今年度策定しております男女共同参画のための品川区行動計画第５次等の中で、やはりマイノリティの方たちの人権に対する項目を一つ大きな柱として位置づけておりますので、その中で、策定検討委員会の中でまた進んでまいると思うところですが。","voiceIndex":322,"id":"exchange-055"},{"speaker":"いながわ委員","kind":"質問","question":"まだ全然整地されていないところで行ったとしても、おそらく頭でっかちになって終わってしまうのではないかなと。だから、しっかりＬＧＢＴ、性的マイノリティの方々に対する理解を深めるという言い方なのかわかりませんが、しっかりとしたフィールドをつくることが大切なのかなというふうな思いから質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":324,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひこの品川区議会でも仕組みが始まるように、皆様には賛成をしていただきたいと初めに述べたいと思います。品川区に１点だけ伺いたいのですけれども、冒頭に概要の説明はありましたけれども、つまりはこの陳情に書かれているように、この制度の導入に向けた協議を開始してくださいとありますけれども、区には導入に向けた協議を検討していただきたいと思うのですけれども、その点はいかがなのでしょうか。","respondent":"島袋人権啓発課長","answer":"そちらの中で、やはりどのような困り事があるのかとか、どうしていってほしいのかというようなのも、やはり策定委員会の中でも議論がいろいろと出てくると考えています。その中で、しっかりと課題を見つけて考えてまいりたいと思っているところです。","voiceIndex":325,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご説明はしっかりと課題を見つけて考えていきたいということですけれども、それはこの導入に向けた協議を開始していくことに前向きに考えているという意味なのか、それとも現状においてはいわゆる課題の整理という意味なのか、もう少しご説明いただきたいと思います。","respondent":"島袋人権啓発課長","answer":"昨年１１月に実施しました調査においてもそうですけれども、まずは区民の皆様の理解が進んでいない、偏見差別があるという考え方も、そちらをきちんと人権啓発課のほうで区民の皆様に知っていただくように行動することが一番かと考えております。","voiceIndex":327,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"差別をなくしていく品川区に私もぜひ進めたいと思うのですけれども、今日の審査は同性パートナーシップ制度についてのことなので、今のご説明というのは、導入に向けた協議を開始していきたいという趣旨でのご説明なのか、それともそこにはまだたどり着いていないという意味なのか、そこを伺いたいと思います。","respondent":"榎本総務部長","answer":"最終的にこの公的承認というのが一番いいのだというふうになれば、それはその導入に向けた手順をまた踏んでいくという形になるかと考えています。","voiceIndex":329,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味からも、この同性パートナーシップの仕組み、仕組み自体は各自治体にいろいろ違いがあったり、いいところとより踏み込んだところとあるので、そこはよく精査が必要かとは思いますけれども、品川区にもこの導入に向けた協議を開始していただきたいと思いますけれども、改めていかがでしょうか。","respondent":"榎本総務部長","answer":"先ほどの繰り返しになりますけれども、これだけを進めるというわけにはちょっといかないと考えておりまして、まずは、先ほど課長が申しましたけれども、多様性尊重啓発講座という形でやりまして、どういう方々に聞いていただいて。","voiceIndex":331,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"これだけを進めるわけにはいかないという意味がわからないのです。その中で、これだけを進めるわけにはいかないというのがどういう趣旨なのか、改めて伺いたいと思います。そうした中でこの制度が求められているということはぜひ受けとめていただきたいと思うのですけれども、改めて、これだけを進めるわけにはいかないとはどういう意味なのか、伺いたいと思います。","respondent":"榎本総務部長","answer":"この陳情の中身が全部わからないのですけれども、基本的にはこの性的マイノリティの方々への差別をなくした上で、そういう承認制度を創設してという形なのかなと受け取っているところなのですけれども、まずはこの協議というのがどういう意味なのか。","voiceIndex":333,"id":"exchange-061"},{"speaker":"中塚委員","kind":"意見","question":"協議というのはそれぞれ捉え方があっていいと思うのですけれども、品川区の中で検討委員会を設置して当事者の方の参加や、参加はちょっとというのであればアンケート調査だったり、様々な形で導入に向けた協議を開始してほしいというふうに私は受け取っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":335,"id":"exchange-062"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、渋谷区のパートナーシップ証明書発行が２年前だったと思うのですけれども、今もって２０件程度の証明書しか発行していないというところで、渋谷区がそこまで斬新なことをやったのにもかかわらず、性的マイノリティと思われる方もそれぞれ悩みがある中で、証明書がいまだ２０件程度しかないということは、改めてこれは議論の場を持って調査研究をしていくべきではないかと考えていますけれども。","respondent":"島袋人権啓発課長","answer":"初めに、本当に実態把握が難しいということと、とても私ども行政のほうにお声が届いていない部分があると。","voiceIndex":336,"id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"私は今回一般質問に入れさせていただいたので、実はあちこちに問い合わせをしましたので、何か私個人としては伺うまでもなく、結構品川区の中でいろいろな取組みも進んでいて、一方でまだまだだなというところも理解しているのですけれども、今、あまり事例はおっしゃらなかったのですけれども、人権啓発課として他の所管とも連携しながら進めていることの内容などを少し紹介していただけると。","respondent":"島袋人権啓発課長","answer":"子どもたちに関することであれば、「よりそいホットライン」等の電話等で対応させていただいている部分があります。そちらのほうに関しましては、教育委員会の教育総合支援センターですが、連携をとり行っているところです。","voiceIndex":338,"id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"普通、施策を考える時に、調査研究が大もとになるというのはそのとおりだと思います。そのことも含んで、私としてはこの陳情は大変表現を工夫して、導入に向けた協議というあたりで、まずは機運醸成を図ってほしいという趣旨かなと受け取りました。ですから、生活者ネットワークとしては、やはり区議会の中でもその機運醸成をまず取り組もうということで、これはぜひ皆様に賛成を呼びかけたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-065"},{"speaker":"須貝委員","kind":"意見","question":"ですけれども、やはりそっとしてほしいとか、そういう方も多数いらっしゃる。なかなかこのことに関しては、区としてもではどこまで出ていっていいのか、今後どのような行政サービスに結びつくのかとか、その方たちをどうやって守れるのかということが、やはり非常にまだ様々な問題を今後議論しながら進めていって、そして今回のこの方の陳情にあるようなことを一歩一歩慎重に進めていくべきだと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":341,"id":"exchange-066"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"きっとこの方も勇気を持って、この陳情の名前に連ねられたのかなと思いますけれども、なかなかやはり制度をつくっていくのにはハードルが高いということも実感をいたしますので、今回初めて品川区でこの陳情が出されたということで、少数かもしれませんし、また一方では触れないでほしいという方も事実いらっしゃいますが、この陳情が出されたこのことの意義を心にとどめていただいて、機運醸成を図っていく。","respondent":"島袋人権啓発課長","answer":"は区としてできることは、そのような啓発活動をしていくことが一番かと思いますので、準備は少しずつではありますが、同性パートナーシップ制度とはまた別に、区民の方たちにもしっかりと理解促進を進めてまいりたいと考えているところです。","voiceIndex":342,"id":"exchange-067"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すでお願いします。趣旨採択でお願いします。理由としては、本来なら継続を求めたかったのですけれども、品川区の現状についての調査と研究も必要と考えております。憲法上、法律上も同性婚はまだ認められていないという状況もあります。これはまず現状をあくまで調査をしていただきたいということで、趣旨採択とすることにいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":345,"id":"exchange-068"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いをしたいと思います。継続でと言いたいところですが、なかなかパートナーシップ制度の導入に向けてはハードルが高いと思いますので、議論を大きく進めていくためにも趣旨採択でということで、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":346,"id":"exchange-069"},{"speaker":"中塚委員","kind":"意見","question":"先ほどそっとしてほしいとか、構ってほしくないというお話がありましたけれども、私自身も、年齢は定かではありませんけれども、割とご高齢のゲイのカップルの方と、今までどのような人生を歩んできたのかという話を聞いた時に、最近よくテレビでＬＧＢＴが取り上げられるよねという話になった時に、確かにその方もそっとしてほしいんだとおっしゃっていました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":347,"id":"exchange-070"},{"speaker":"いながわ委員","kind":"意見","question":"結論を出すで、趣旨採択です。そういうことを踏まえた上で、こうした陳情を出されてきた方の思いとか、この文書になって出てきたというのは、我々もそれを考える一つの出発点になるのか、そういう部分にもなろうかと思いますので、趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":348,"id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"私も結論を出すということでお願いしたいと思います。先ほど見解を述べさせていただいたとおり、現時点では趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":349,"id":"exchange-072"},{"speaker":"吉田委員","kind":"意見","question":"生活者ネットワークとしては、ぜひ採択をしたいと思います。そっとしておいてほしいという方がいらっしゃるのも、そのとおりだと思います。このことに限らずいわゆるマイノリティの方たちは、ぜひ声を上げてくださいと言っても、もうそっとしておいてほしいという方がいらっしゃるのです。やはり偏見の目が怖いからということがあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":350,"id":"exchange-073"},{"speaker":"松澤委員","kind":"質問","question":"本日結論を出すということで、皆様方のご意見をお聞きし、また品川区の現状についての調査研究はやはり人権啓発において必要かなということで、趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":351,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"採択を主張させていただきましたが、皆さんのご意見を伺う中でこれが全会一致で決まるのであれば、趣旨採択に変更しても結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":354,"id":"exchange-075"}]},{"id":"topic-11","title":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すみません。自分の質問のところでもいいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":359,"id":"exchange-076"},{"speaker":"吉田委員","kind":"質問","question":"いやいや、そうなのです。まさにこの性の多様性のところだったのですけれども、ご答弁がよく理解できなくて、公営住宅の入居に関しては、国の解釈がというようなご答弁があって、国の法的な解釈で言うと、公営住宅法ではもう親族要件が外れているのですが、そのほかにも法的解釈で見解が分かれることがあるということなのでしょうか。その辺が理解できなかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":360,"id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"例という意味では、総務委員会ではなかったですけれども、ほかの常任委員会で、自分の質問に対してフォロー質問をすることにして、次の日に質疑を行うということは正直言うと何回もあったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":366,"id":"exchange-078"},{"speaker":"吉田委員","kind":"質問","question":"公営住宅の入居に関しての同性カップルの入居に関して、国と都の解釈がというようなことだったので、国の解釈はもう済んでいるはずだという再質問をいたしましたが、それに対して、改めて同じようなご答弁だったように理解しております。それが公営住宅法の親族要件以外に法の解釈が分かれるものがあるのかどうか、もしあるのでしたら教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2110#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":61620,"voices":374}},{"id":"h30-20180703-6","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"区民委員会","time":"午前１０時００分～午前１１時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７回 品川区・ポートランド市 青少年スポーツ交流事業","agenda":"第７回 品川区・ポートランド市 青少年スポーツ交流事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"種目が女子バスケットボールということで、最初は野球だったということなのですけれども、女子バスケットボールになった経緯などあれば伺えればと思います。","respondent":"遠藤協働・国際担当課長","answer":"今回、バスケットボールだけになってしまった理由なのですが、野球は今まで６回全て続けてきたところなので、野球もということではあったのですが、どうしても先方で野球の人数を出すことが難しいような話がありまして、バスケにつきましても。","voiceIndex":5,"id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですけれども、ポートランド市からの派遣で来る方たちに、日本から行くほうも事前にいろいろ学んで文化などを知って行くのだと思うのですけれども、ポートランド市のほうからも日本の文化なども勉強したり学んでから来てという中で、うまく交流をしていきましょうねという話があるのですか。","respondent":"遠藤協働・国際担当課長","answer":"先方とのやりとり、事前に協議というのは特に行ってはいないのですが、ポートランド市のお子様方がこちらにお見えになったときに、品川区とポートランド市が結びついた経緯だとかというところで、品川歴史館や大森貝塚などを回って、あとは歴史館には茶室がありますので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"大倉委員","kind":"質問","question":"そういうのがあったら、５年に一度ということでいろいろな意見が出てくる中で、直接、例えばポートランド市の方たちの日本のイメージとか、こういうのに興味があるという何か、文化でもいいですし、例えば、秋葉原がすごい、行ってみたいといったような情報をとってくるようなことを行っているのかどうかを教えてください。","respondent":"遠藤協働・国際担当課長","answer":"ポートランド市の方の意見を聞くというのは、直接お子さんから聞く場面ですと、さよならパーティーという一同に会する機会がありまして、そこで直接話を聞くぐらいしかないのと、あとは間に入ってくれたポートランド市の引率の方などを経由して。","voiceIndex":9,"id":"exchange-003"},{"speaker":"大倉委員","kind":"提案","question":"まさに直接、日本のイメージというところで聞ける機会でもあるのかなと思います。これからどんどん交流が進んでいって、国際都市品川を目指す中で、１つこういったこともいいのかと思いましたので提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"制度が開始されたのは昭和ですよね。人数。人数もこれは１２名、１１名ではたしていいのかどうか。それがまず１つ。もう１つは、国の対象国、提携国と言ったらいいか、これもさまざまな場所で見直し論もあるだろうし、拡充論もあるだろうし、議会からも要望させてもらっていて、結局、対象国は昭和のままのような気がするのですね。なぜここまでそのままなのか、逆に言うと不自然ではないでしょうかと。","respondent":"遠藤協働・国際担当課長","answer":"人数も減ってしまっているというお話ですが、スポーツ交流という面では少なくなっておりますが、国際交流というところになりますと、ニュージーランドのオークランドには毎年３０人のお子さんを派遣しているというところがありますので、全体としてはそう減ってはいない。","voiceIndex":13,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"それは何かと言うと、やはりこれがベストなのですかと。方法論で。例えば対象で中学生だと課題があるのであれば、ほかの検討がなされたり、あとは１回実施するとか、ずっと同じまま踏襲しているだけに見えてしまうのですね。これはどこかで言わないとだめな気がするのですよ。この機に。時代に即していなかったりするような気がするので、包括的になりますが、その辺のお考えを教えてください。","respondent":"遠藤協働・国際担当課長","answer":"この部分の見直しと言いますか、今までのものをずっと引き続きやっているだけではないかというご指摘かと思いますが、先ほどお話ししたとおり、１回中止になりかけたこともあり、事務レベルではあるのですけれども。","voiceIndex":15,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"要望で最後。おそらく、多くの方は。ポートランド市はポートランド市でもちろん歴史もあるからとなるけれども、そこで閉塞感があるのだったら、やはり対象国の見直しとか、あるいはもっと、今は３つなり４つなりにとどめている場合ではないような気がするのですね。やはりアジア圏を中心とした新規というものは検討すべきと思いますが、それを要望と兼ねてご答弁をお願いします。","respondent":"遠藤協働・国際担当課長","answer":"対象国の見直しも含めてと言うか、もっと広い見方というところでご指摘をいただきましたので、いろいろな観点でこれから考えていければと考えています。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"しながわ文化プログラム推進事業助成金","agenda":"しながわ文化プログラム推進事業助成金","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"なかなかイメージができないところもあるのでお伺いしたいのですけれども、対象イベントの3)のところで、「オリンピック・パラリンピックの開催に向けた機運醸成またはレガシーの活用に資すること」とありますけれども、このレガシーの活用に資するということがどういうことなのか、イメージできる形でご説明いただければと思います。","respondent":"立川文化観光課長","answer":"そういった意味で、いわゆる小ホールぐらいのイベントですと大体２００人以上です。こういったイベントがどれくらいあるのかというのは数字を持ち合わせておりませんので回答を控えします。","voiceIndex":23,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"もしほかに何か例があれば伺いたいと思います。はイベントの２００人の規模のところで、結構この規模が小ホールレベルだということでしたけれども、大きな規模というイメージをしているのですけれども、結構多くの数がこういった規模であって、多くの文化振興を行っている団体がこの助成を受けられるのかどうかというところを伺いたいと思います。","respondent":"立川文化観光課長","answer":"１,０００人以上のホールになりますと、やはり集客がかなり難しいというところですので、ですから、この２００人という目安というのは妥当な数字ではないかというところです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"小ホール、２００人から３００人の規模が妥当ということでしたけれども、それはこの助成の額なども見て妥当ということなのですかね。わかりました。その中で、予算額の中で今５件から５０件ということでしたけれども、この規模のイベントをやっている、できる団体がどれだけあるのかと思うのですけれども、あまり限定されたところではなくて、広くこれが利用できるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"事項別を見ても内訳がわからないというのと、今まで行われてきた事業ではないのですよね、ということと、あとは予算書にこうやって書いてありますというのが、この資料の中にも書いてあったらよかったなというのと、あとは予算の内訳を聞きたいのと、対象団体に対する審査の方法について伺いたいのですけれども、お願いします。","respondent":"立川文化観光課長","answer":"予算書は１８７ページ、２,１００万円ということで計上しております。内訳につきましては、予算案を調製する段階での内訳というのは、ざっくり申しますと、金額の規模によって大体７件ぐらいの事業は予定していたところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"２０１８年、今年６月に立ち上げた文化何とかというところをもう１回教えてほしいのと。ごめんなさい。聞き取れなくて。立ち上がったものの報告、そういった書面は配られましたか。〔「はい」と呼ぶ者あり〕配られていたらすみません。私が見ていませんでした。そして、審査方法はわかりました。審査員はどのような方がそろっているのかというのを教えてください。","respondent":"立川文化観光課長","answer":"振興協議会につきましては、昨年度、今年２月の区民委員会で前課長が説明したところです。","voiceIndex":30,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"なぜ今このような質問をしたかと言うと、去年９月の補正に出ていた品川区地域資源活性化事業補助制度のときに、補助金のつけ方が、事項別を見ても内訳がわからなかったり、当初予算以上のものが補正でついてしまったりということがあったので、その辺が不安で聞いてみました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問","question":"１点。助成金の２分の１の助成の意味合いを教えていただければと思います。２分の１と言うと、やはり事業者が絡んで、採算性があえば２分の１はオーケーだよという見方が１つ有力にあると思うのですね。議論はあったかと思うのですが、スタートはとりあえずこうだろうというところかなと推測はするのですが、その辺のお考え、結論に至った考えとか、望ましい形と言うのですか、想定も含めて教えてください。","respondent":"立川文化観光課長","answer":"もう１点の、地域団体が実施する場合に２分の１というのはかなりハードルが高いというところですが、確かに半分を例えば町会・自治会が負担するということになりますと、最低の補助金額が２０万円ですので。","voiceIndex":34,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"意見","question":"本当に企画自体はものすごくすばらしい、タイミングと言い、地域ニーズに合っていると思います。手探りだったり、第一歩目が大事なので、しっかり支えるべき事業だと思いますので、今後の推移を見ながら弾力的に検証していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"は効果測定、これは、では１回、継続的実施が可能だというところで言うと、ああ、これは大丈夫だなとか、これは本当に大丈夫なのかとか、本当に継続できますかというところの効果をどのように測定していくのかというところを教えていただきたいと思います。","respondent":"立川文化観光課長","answer":"そうしますと、既存の事業をオリンピック・パラリンピックに向けて、どうアレンジしていくか、どう充実させていくか、そういったことをこの助成金が出るということでプラスアルファの部分を、今までやってきたイベント等に加えていただければ。","voiceIndex":37,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"わかりました。同じ事業者が、予算額が１,０００万円しかないですよね。同じところがずっと使っているとほかのところが使えなくなるということもあるのかというところで、縛りがあったりするのか、その辺を教えていただきたいのと、今後、この助成金のあり方は考えていくということだったので、そこだけお願いします。","respondent":"立川文化観光課長","answer":"ですから、今後につきましては、実際に申し込まれる団体と予算額の関係については、検討していく必要があるかと考えています。","voiceIndex":39,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に。しっかりとした効果測定をしていただきたいというところがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"今までイベント系と言うか文化系と言うか、そういうのに助成を出していたことがあるではないですか。この対象とならない主な事業のところに、「宗教的または政治的な宣伝」というような文章があえて出ているのですけれども、私はあまり、こういう文章として出てきたのは記憶にないのですね。","respondent":"立川文化観光課長","answer":"これは文化芸術の国や都の助成制度がありまして、文言としましてはその辺から引っ張ってきたですので、区が独自にあえて載せたというよりは、文化芸術の分野ではイベントなどについて、イベントホールであるとか、集会所で人を集めて何かを実施するですので。","voiceIndex":42,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"ということは、今度からここだけではなくても、こういったイベント系の助成金というのはどこでも出てくると思いますが、今まで私はある意味常識、当たり前だと思っていたのですね。区としては。毎回こういうイベント系などそういうものに助成する場合に、「ただし宗教とか政治的な」というのを、文章でこれから出していくような方針にしていくのでしょうか。","respondent":"立川文化観光課長","answer":"区全体としての答弁は私はできませんけれども、文化観光課所管の事業につきましては、こういった文言は助成金を交付する際には出していくということです。","voiceIndex":44,"id":"exchange-020"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"大体、イベントは中心者という方がおられて、その方が引っ張っていくような形にはなると思うのですけれども、うまくここのとこころを育てていくと言うのでしょうか、そういうような事業も、これから品川区がこういうイベント等を行う上においては重要だと感じておりますので、この点についても教えていただければと思います。","respondent":"立川文化観光課長","answer":"その後の部分ですけれども、今回の文化プログラムの成果というものが、その後継続して残していく必要性というのがあると考えておりますので、今後についても区が助成して文化芸術に親しめる人を増やすであるとか。","voiceIndex":46,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"すみません。先ほどご答弁の中にあったかもしれないのですけれども、助成金は同じ団体が次の年も助成金を受けられるとなったときには、２分の１ではなくて何分の何になるということはあるのですか。ないのですか。","respondent":"立川文化観光課長","answer":"これは２分の１という固定で実施するものです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"失礼しました。要綱などはこれからということなのでしょうか。","respondent":"立川文化観光課長","answer":"実際の助成金の交付要綱というのを制定いたしまして進めてまいります。","voiceIndex":51,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"対象にならない主な事業というところで、「同好会等」というのがあるのですけれども、なぜこの同好会が対象にならないのかというところを伺いたいのですが、この前に書いてあるカルチャースクールというのは営利のところでそうなのかなとは思うのですけれども、この同好会について伺いたいと思います。","respondent":"立川文化観光課長","answer":"それはカルチャースクールでの教室であったり、同好会という名称の教室であったり、そういった団体が行う発表会等については助成はしませんよというふうに言いたいということです。","voiceIndex":54,"id":"exchange-024"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡辺委員","kind":"意見","question":"日程はこの範囲で絞られていたら、あとは相手のあることなので、交渉はお任せして、全く問題ないと思います。は内容もそれぞれこれだけ具体的なものがあるし、移動手段もおそらくスムーズなような気がするし、いろいろな配慮がされているので問題ないと思います。このとおり進めていただければ幸いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-025"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"屋外プール開放についてですけれども、この間も言ってきておりますけれども、伊藤学園のプール開放を求めていました。今回、この学校プールの開放に伊藤学園が入っていないということなのですが、ぜひ、開放してほしいという声もありますので、加えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"伊藤学園のプールは温水プールということで、以前に開放していたこともありますけれども、こちらとは性質が違うところでして、現在のところは学校の夏休みの開放というところでは考えておりません。","voiceIndex":69,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"伊藤学園は性質が違うというお話なのですけれども、区民の方はやはりプールに入りたいと、ここにもありますとおり、遊泳を気軽に楽しめるというところで、近くにあったものがなくなってしまったというところで、やはりそのためにプールに行かなくなってしまったという方もいらっしゃいますので、このプール開放についても、ぜひ伊藤学園も検討していただきたいのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"特に、こちらのほうは親子で楽しんでもらうことを主としてやっていることでございまして、基本的には小学校の浅いプールを楽しんでいただくというところですので、実際に。","voiceIndex":71,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"合わせて、しながわ区民公園のところですけれども、使用料が大人４００円、中学生２００円、小学生１００円ということになっておりますけれども、やはり中学生以下、この目的にもあるとおり、夏季の余暇の充実ですとか、スポーツのより一層の振興を図るという意味では、中学生等は収入がないわけで、お小遣いをどのぐらいもらっているかわかりませんけれども。","respondent":"池田スポーツ推進課長","answer":"伊藤学園の夏季のプールですけれども、確か伊藤学園が中止になったときには、夏はとにかく暑くて利用ができないというような話があったかと思います。そうしたことがありましたので、今回新たに夏の期間だけ一般の方に開放するということは厳しいかと思います。","voiceIndex":73,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"プール開放のほうは夏が厳しいという話でしたけれども、そのときは温水プールで夏が暑いということで多分厳しいということだと思うのですが、今度は普通に水のプールでやるということを求めているわけですけれども、それでも厳しいという理由はどういったことなのか、もう少し詳しく教えていただきたいと思います。いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"ロッカー代につきましても、こちらのロッカーもずっと長くもっているものでもございません。実際に買いかえ等が必要ですので、こういったことで実際に歳入とさせていただいているですので、こちらもご理解いただければと思います。","voiceIndex":75,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"しながわ区民公園水泳場についてなのですけれども、利用制限の中に、おむつのとれていない幼児はプールには入れないということがあるのですけれども、今、ここにも書かれているように、水着がわりに着用できる紙おむつというのが出ているではないですか。その辺が、確か以前どこかで質問したと思うので、検討されているのかどうか、その辺を伺いたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"こちらも、区のホームページの児童センターの部分にプール開放についてのご案内がそろそろ出ると思いますので、皆様にご周知いただければと思います。","voiceIndex":77,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"でも、今聞いているのは、児童センターのことではなくて、しながわ区民公園の水泳場のことを伺っていて、今お話しされていた児童センターのこともわかるのですが、そうすると今度は小学生以上の子が入れなかったりするのですよね。ちょっとでもプールのほうに近づくと、だめですとなってしまうという声を聞いているので、その部分なのですけれども。","respondent":"池田スポーツ推進課長","answer":"しながわ区民公園のプールは、おむつのとれていないお子様はご遠慮いただいている、これはそのルールでやっておりますので、おむつをつけている方はプールに入れないと、中にも入れないと、そういうふうにご理解いただければと思います。","voiceIndex":79,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"中に入れないことはないですよね。プールサイドでの見学は可能ということが利用制限に書いてあるので、そこは大丈夫だと思うのです。子どもたちも立派な区民の１人なので、ぜひ、そういう、だめだよと締め出すのではなくて、一緒に遊べるような条件にしてほしいと思うのですけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"プールにつきましては、おむつのとれていないお子様ではなく、水泳のパンツをはいていただいて、遊んでいただくということでお願いいたします。","voiceIndex":81,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"プール用の紙おむつのパンツをはいていても、このプールサイドでの見学もだめということなのですか。どうなのでしょうか。","respondent":"池田スポーツ推進課長","answer":"ルールとして、おむつのとれていないお子様はだめというふうなご理解をいただきたいと思います。","voiceIndex":83,"id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい。何度も。「水着がわりに着用できる紙おむつ、トレーニングパンツ、裸でも、プールに入れません」はあるのですけれども、プールサイドには一緒に連れて行くことはできますか。どうでしょうか。","respondent":"池田スポーツ推進課長","answer":"先ほど委員がおっしゃったように、プールサイドに控えるとか、そういうところでは構わないと思いますが、水に入るということ、これはおむつのとれていないお子様はだめということでお願いしています。","voiceIndex":85,"id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"確認です。プールサイドには紙おむつをはいている子も入れます。ただ、水を浴びるような、キノコの形でしたか、水を浴びるところ、あそこでも子どもは浴びられないということですか。","respondent":"池田スポーツ推進課長","answer":"あくまでも、水がかかるところは遊ぶところですから、そこは当然おむつのとれていないお子さんはご遠慮いただくということです。","voiceIndex":87,"id":"exchange-035"},{"speaker":"田中委員","kind":"意見","question":"その部分などはどのように考えておられますか。","respondent":"池田スポーツ推進課長","answer":"あくまでも、おむつがとれていない子は、水遊びは中ではできませんというふうにお願いしているところです。","voiceIndex":89,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"おむつのとれていない子と、とれている年の離れた兄弟というのもいますし、あとは小さい子たち、おむつがとれていない子たちも立派な区民の１人なので、どうかその子たちも遊べるような、ここで一緒に遊べるような何かしらを検討していただきたいと思うのですが、いかがでしょうか。これから。","respondent":"池田スポーツ推進課長","answer":"現在のところ、紙おむつではプールのほうに入れないということでご理解いただければと考えています。","voiceIndex":91,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"確かに、保健所からそういうルールがあるというのは聞いています。ですので、それでもやはり一緒に遊べるようにぜひ検討を、保健所の管轄であったり、いろいろな横のつながり、関係部署との検討を、ぜひおむつがとれていない子どもがどうしたら一緒に遊べるかということも検討していただきたいと要望します。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですが、区民公園の水泳場のほうなのですけれども、この夏季以外の使用について、何か使うという可能性、ほかでは今いろいろな使い方がされているところもありますけれども、現在どうなっているのかというのを教えてもらいたいのと、何かプール条例のようなかかわりで、使い方についても制限されているのかどうか教えていただきたいのと、例えば夏季の夜８時までというところで言うと。","respondent":"池田スポーツ推進課長","answer":"今後、これを継続するかどうかについては、あくまでも試験的に、確か昨年かその前ですか、川魚を入れて釣堀をやっていたことがありましたけれども、これ以降、継続するかどうかについては、公園課のほうで所管しておりますので、私どものほうではわかりません。","voiceIndex":97,"id":"exchange-039"},{"speaker":"大倉委員","kind":"質問・要望","question":"地域のスポーツでより一層の振興という部分で言うと、夜間の使い方についてもいろいろとご検討いただければいいかなと。土曜、水曜、日曜日以外というところも含めて、意見として。夏季以外の使用についても、できれば釣堀などもいいのかなと思いますけれども、さまざまなスポーツの振興というところの観点も入れて、夏季以外の活用についても考えていっていただきたいと思いますけれども、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"貸切時間につきましては、これから検討するような形になります。ただ、実際にプールの一般開放については７月１０日から９月９日というふうになっておりますけれども、その前の実は７月５日から９日までの間、団体への貸切を行います。","voiceIndex":99,"id":"exchange-040"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、夏季以外の使用は公園課ということですが、うまく、目的のところでプールなのでスポーツというところで体を動かす、運動するというところで、何かそういったところの連携も踏まえて、これだけということではなく、いろいろな視点をもって連携をしていっていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"確かに承りました。","voiceIndex":101,"id":"exchange-041"},{"speaker":"渡辺委員","kind":"質問","question":"その中で料金も、先ほどどなたか料金の話が出ていましたが、行政がやるゆえに、とても安価、あれだけの施設で大変安価に低料金で運営されていて、ここも満足度の１つだと思います。伺いたいのは、ありがちなのですが、区民料金という区分があってもいいような気がするし、今現状、統一料金である理由がそれなりにあるのかなと、その辺を教えてもらえればと思います。","respondent":"池田スポーツ推進課長","answer":"利用料金については、区民料金と区外料金のことですけれども、外に券売機が置いてあるのですけれども、夏ということで軽装の方が多くございまして、なおかつロッカーということで肌を露出する状態になりますので、貴重品などをお持ちでない方もいらっしゃるかと思いますので。","voiceIndex":103,"id":"exchange-042"},{"speaker":"浅野副委員長","kind":"質問","question":"プールの開放ということでお伺いしたのですけれども、私はしながわ区民公園水泳場は行ったことがないのでどういう雰囲気かというのがよくわからないのですが、開放している期間というのは、例えば監視員の方とか、そういう方は配置をされているのか。学校プールだとされているとは思うのですけれども、そういう事故防止の観点からどのような体制をとられているのか教えてください。","respondent":"池田スポーツ推進課長","answer":"しながわ区民公園のプールですけれども、子ども用のプールが１つ、それから変形プールということで大人も使えるプールということで２カ所ございまして、監視員につきましては１日平均６人ずつ配置していますので、午前６人、午後６人という形で配置しております。","voiceIndex":106,"id":"exchange-043"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"配置はされているということで、どこにも書いていなかったので、どうされているのかなと思ったので、質問させていただきました。学校のプールについては、それは大人の人も監視をしているのかなと思うのですけれども、こちらもどのような体制で安全対策に臨まれているのか教えていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"学校プールにつきましても、地域の方が受付等をやっておりますけれども、実際のプールの中には監視員が２人ほどつくような形で配置しております。","voiceIndex":108,"id":"exchange-044"},{"speaker":"大倉委員","kind":"意見","question":"すみません。最後に。先ほどの区民割引というところと定期券の利用というところで思ったのが、定期券にしたほうが区民かどうか、事前に登録してもらえば判断しやすいのかなと、そういったことも考えていいのかなと思ったので、意見だけ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2814#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":26643,"voices":114}},{"id":"h30-20180703-7","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年度品川区介護保険制度の運営状況","agenda":"平成２９年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"１１ページの特別会計事業費の右の円グラフの地域支援事業について伺いたいのですが、ここに１４億９,８００万円、約１５億円が地域支援事業。その内訳を知りたいと思うのですけれども、１２ページ、１３ページにある総合事業の実施状況と言われる全部は、地域支援事業から出ていると考えていいのでしょうか。内訳を教えて下さい。","respondent":"寺嶋高齢者福祉課長","answer":"金額は記載の１４億９,８００万円ですが、割合としましては、このうちの７２％が総合事業になります。それから、２５％が包括的事業になります。それから、３％が任意事業となります。地域包括支援センターに係る委託料等は、その２５％の包括に含まれております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。１２ページ、１３ページの四角で囲ってある、いろいろな数を示していただいたのですけれども、上にある訪問型サービスとか通所型サービス、介護予防ケアマネジメントは、予算が３ページにあるのです。予算額が出ている、出ていないというのは、何か区別があるのかどうなのか伺いたいです。","respondent":"寺嶋高齢者福祉課長","answer":"今回の資料には金額が載っていないですけれども、先ほどのご質問は品川区の福祉ですが、資料の作成のコンセプト的に、おそらく主だったものということで記載させていただいているということで、実績調書等には全て記載されているのですけれども。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"それとあと、地域包括支援センターのブランチ、在宅介護支援センターの委託費は２５％、地域支援事業の７５％になっているのですけれども、委託費がどのように使われているのか、普通、委託費を出していれば、事業計画があって報告があるという形になるのですが、在宅介護支援センターからそういうものは上がってきていないのでしょうか。伺いたいと思います。","respondent":"寺嶋高齢者福祉課長、宮尾高齢者地域支援課長","answer":"地域包括支援センターに委託しているものの中で、基本的な部分につきましては、機能の分散ということでやっているので、件数であらわすものではないのですけれども、実績ベースでお支払いしているものにつきましては。先ほどの委員、ご質問の品川区の福祉に予算額の計上の件ですが、今日ご提示している運営状況の項目と品川区の福祉の項目との予算額の計上の仕方が必ずしも完全に一致していないところがあるのですが、一部。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に大事なことだと思うのです。２年で時効になるともおっしゃっていたと思うのですけれども、２年で時効になるというのは全体で決まっていることなのか、区として設定できる年数なのか教えていただきたい。それと、ペナルティもつけず、差し押さえもしないという姿勢はどういう考え、スタンスでおられるのか伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"どういう形をとっているかといいますと、実際にはサービスを利用する段階になったときに、こちらとしては、そのときが一番、お話がしやすいときなので、その段階で制度の説明をきちんとして、皆様、本来は使わないずっと前からお支払いいただいていることも改めて申し上げた上で。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"何点かお聞かせいただきたいのですが、２ページの事業所別ケアプラン作成割合ということで、在宅介護支援センターが７３％で民間が２７％なのですけれども、予防プランは基本的に在宅介護支援センターでほとんどやっていると考えていいのか。それを引いた数が介護プランと考えていいのかを１点、お聞かせいただきたい。","respondent":"寺嶋高齢者福祉課長","answer":"予防のプランですけれども、基本的には区内の２０カ所の在宅介護支援センターでつくっておりますが、民間にも委託という形でお願いをしている分があります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"以前は、なかなかケアプランが回ってこないという問題が民間のところにあったと思うのですけれども、そういう問題が今どうなっているのかを教えていただきたいと思います。デイケアが少ない。デイケアでリハビリをやりたいという要望はすごく強いと思うのですけれども、デイケアをもっと増やす、誘致する、そういうところに対しては、区としてはどう考えられているのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"今は、ここまで数が増えてくると、先ほど申し上げたように在宅介護支援センターは２０ですから、キャパ的にも対応できる分が決まっておりますので、まず民間にお願いしていかないと、回らなくなってくることは１つ想定ができております。実際、そういう対応になっています。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"リハビリはすごく要望も高いので、ぜひ、誘致のところでも考えていただきたいと思います。それと、もう一つ、先ほど地域支援事業のところで、包括的事業が２５％で、地域包括支援センターがここに入るということですけれども、地域包括支援センターだけで２５％になるのでしょうか。そこの財源の仕組みがどうなっているのかについても教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"これは２０の在宅介護支援センターに地域包括の機能をお願いしているという考え方は、１つとしては、例えば区役所と地域センターという位置付けと似ている部分があると思っていまして、その機能を受け持ってもらっているという認識なので。","voiceIndex":18,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今、包括的事業のところで、支え愛・ほっとステーションは、途中までは介護保険ではなくて、シルバー交番という形で、東京都のものを使って設置をして運営をしていく、そういうことだったと思うのですけれども、介護保険の包括的事業の地域支援事業の中に入ったのでしょうか。それはいつからなのかも教えていただきたいのが１つです。でも、在宅介護支援センターはわかりにくいと思うのです。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長","answer":"支え愛・ほっとステーション事業自体をやっているのは一般会計の予算になっていますけれども、介護保険法が改正されまして、平成２８年から生活支援体制整備事業ということで。逆に言うと、独立してやりますので、今、品川区は連携がとれているから、品川区の１カ所の地域包括に職種は集中しておりまして、必要に応じて、機能を分散している中で足りないものがあれば。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、ＰＲの問題で申し上げました。それからあとは、地域包括支援センターは３職種がきちんと配置されていないと、地域包括支援センターとは認められないので、ずっと言い続けていることですけれども、保健師をきちんと配置して、地域包括という形にしていただきたい。配置をすることで地域包括支援センターになるのであれば、そうしていただきたいと改めて要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"若林委員","kind":"確認","question":"数字の確認だけです。ここら辺の数字の分析はどうされているか、お聞きしたいと思うのが１つ。１３ページの3)その他の品川区地域貢献ポイント事業ですが、登録者数が１,４１７人で活動者数が１,０８５人で、登録しても３分の１の方は活動していないという数字ですが、ここら辺の分析もお聞きしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"この点は真摯に受けとめて、今後の事業の参考にしてまいりたいと考えています。","voiceIndex":24,"id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"はつらつ健康教室は、いずれにしても、各プラザで数字のばらつきが激しい事業です。その対比も含めた分析が進んでいるのであれば、お聞きしたいと思います。現実を見ると、登録者数に対して３分の２ぐらいだと、逆に登録者数を増やすことが必要になってくるのか。活動者数をもっと増やしたほうがいいという事業の目的とか分析とかをされていれば、参考までにお聞きします。","respondent":"宮尾高齢者地域支援課長","answer":"それと、地域貢献ポイント事業ですが、繰り返しになってしまうのですが、年の経過とともに、当初は積極的に参加していらした方が事業になかなか参加されなくなってくるといったところは課題として認識はさせていただいてあります。","voiceIndex":26,"id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"今の１２回で４クールという表現は、1)から１３ページにかけて、全てにそういう言い方が当てはまるので、数字を見て私たちも判断する部分もあるので、実態に沿った説明が必要なところがあれば、今から直すのはあれですけれども、今、説明していただければ書き加えます。","respondent":"宮尾高齢者地域支援課長","answer":"今すぐ、この事業がどうなっているというところまではわかりかねますので、その辺をしっかりと見据えていきたいと考えています。","voiceIndex":28,"id":"exchange-012"}]},{"id":"topic-02","title":"平成２９年度品川区障害福祉計画実績","agenda":"平成２９年度品川区障害福祉計画実績","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"障害福祉計画の実績ということで、私たちがＰＤＣＡサイクルで、計画の進捗状況を区として報告はあるのかと聞いた際に、実績等は自立支援協議会では報告されているけれども、こういうところには出てきてなかったと思います。今、私たちが資料としていただいている実績、こういう形で自立支援協議会にも、毎年出ていたと考えていいのですか。","respondent":"飛田障害者施策推進担当課長","answer":"昨年度は、平成２８年度版の計画の実績ということで、自立支援協議会では報告させていただきました。","voiceIndex":34,"id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"この実績を見させていただいて、３ページに身体障害者と愛の手帳があるのですけれども、精神障害がないのは何でなのだろうと思って、計画のところにはきちんと精神もパーセンテージの形で出ているのです。人なので、０.５はあるのか。総務省の統計局でも、ゼロから始まっていないグラフは正しくないと言われているのですが、これは今から直すことは可能なのか、そういう考えはあるのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"精神障害者保健福祉手帳は、計画には載せて、こちらには載せていないのは、まだそのとき、平成２９年度の実績が出ていなかったので載せるのに時間がかかってしまったということで、この後のところでは載せる予定でいます。","voiceIndex":36,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"幾つか伺っておきたいのですけれども、まず、５ページの訪問系サービスのところ、同行援護、行動援護、そして重度障害者等包括支援がある。その次のページの障害児相談支援なのですけれども、平成２９年度は１５０、平成３０年が５３２と大きく見込み数が増えているのですが、これはどういったことから上げられたのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今回、また新しく事業者ができましたので、そういうところも案内しながら、また相談の中で紹介していきたいと考えています。１６ページの見込み数が多いのは、今後、児童発達支援とか放課後等デイサービスの数も非常に伸びるであろうと考えております。","voiceIndex":38,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。それで、今、言っていただいた放課後等デイサービスが基本１０日とされているということで、それ以上使いたい方は、日中一時とされているところでは、お母さんたちからも、もっと放課後等デイサービスの日数を増やしてほしいという声が本当に強く寄せられてきたのです。ですので、比べられない。ですので、月間と年間に分けている理由は何なのかを伺いたいのです。","respondent":"飛田障害者施策推進担当課長","answer":"放課後等デイサービスの場合ですと、支給の件数のところで都に報告している数をそちらに出しています。法内事業となります。日中一時は法外事業なので、それで年間の数を出しています。","voiceIndex":40,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でも、月ごとに出せるのではないかと思ったのです。見比べたいと思ったときに、なかなかいかなかったので、何でかと思ったのですけれども、年間でないとこれは出せないものなのか。月間でも直していけるのなら検討をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"委員のおっしゃるとおりです。月であらわせるところはまた整理しまして、わかりやすくしていきたいと考えております。","voiceIndex":42,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、この実績自体がどう使われていくのか。出していただきたい。そして、次の年にどうつなげるかということになってくると思うので、この実績より計画を見たほうがわかりやすいのです。ですので、わかりづらいし、細かくないと感じたので、これを次の年にどうつなげるかというところでは、この実績をつくるに当たっては、どこで議論をされて、どれぐらい期間をかけてつくられてきたのかを伺いたいのです。","respondent":"飛田障害者施策推進担当課長","answer":"ちょうど今、言いました計画とも照らし合わせながら、今後、大きな変更等がありましたら、またそこでも協議して、計画の変更もありうると考えています。いずれにしても、こちらは自立支援協議会で報告をして、また委員のお話をいろいろ聞いていきたいと考えております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"分析と評価まで出している自治体もありまして、簡単にＡ、Ｂ、Ｃ、Ｄ等で評価はされているのですけれども、こういうことでここを頑張ったとか、ここを改善していきたいとか。先ほどの課長の説明の中では、こういったことが課題ですというお話もある中で、この実績が説明されたので、そうした評価、分析はいつごろされて、この委員会には報告していただけるのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"計画を立てて、その目標数値にいっているか、いっていないか。そこがまず重要ではないかと思います。特に今回ですと、大きなところでは品川の空白の荏原地区に施設が足りないとか、グループホーム、就労継続支援Ｂ型、そういうところも、今回、計画に上げさせていただきました。","voiceIndex":46,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それが実際に集計したら３７２人ということになった、計画よりも多くなったということだったと思うのです。そういうことからすると、計画では、平成３０年は増えて３５９人となっているのですけれども、これだと平成２９年からさらに下がってしまうことは計画としてもどうなのかと思っているのですが、その点もお聞かせいただきたいと思います。その２つの項目をお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"そこのところはまだ何とも言えない状況です。現在、品川区内の就労継続支援Ｂ型でなく他区を利用されている方もいらっしゃる状況です。そういう意味では、区内にも就労継続支援Ｂ型が今後必要になるということはここでもわかることです。","voiceIndex":48,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、もう一つ、１７ページなのですけれども、2)に相談支援事業ということが書かれていて、ここは実際にどこで相談支援事業をされているかということだけが出ているのですが、これも地域拠点相談支援センターには委託金を出して、ここに委託をしているということもありますので、ここの実績も、ここの中でぜひ示していただきたいと思うのですけれども、いかがでしょうか。","respondent":"飛田障害者施策推進担当課長","answer":"今、１０日のところを国の基準に合わせる変更は、また検討をさせていただければと思います。そして、１７ページです。相談支援事業の実績の数です。数のところも、今後、どう表していけばいいか検討させていただければと思います。","voiceIndex":50,"id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"一方で、地域での生活基盤となるグループホーム云々、そういう短期入所など社会資源の整備を行うことが課題となっている。続けて、平成２９年度実績で２人ということなのですが、身体の方なのか精神の方なのかも教えていただきたいと思います。平成３０年度から新たな取組みを進められるという予算であったと思うのですけれども、これの取組みの見通しも、この時点で伺っておきたいと思います。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"１１ページの短期入所の平成２９年度は７人、ここは実は悩ましいところなのですが、今回、下にも実績見込み量は各年度の３月の数値と書かせていただいております。たまたま３月分が７人と多くなっている状況です。区といたしましては、いきなり医療ショートではなくて、今年度につきましては、医療的ケアの支援体制、医療的ケアが必要なお子様に対する支援体制の協議会で、まずは情報共有しながら意見交換をしていこうという段階です。","voiceIndex":52,"id":"exchange-022"},{"speaker":"若林委員","kind":"質問・要望","question":"最初の地域生活移行支援です。もう一回、そこは確認します。正確な実態をあらわす表示をするためには、何か記述されることが、先ほど都というお話がありましたけれども、区として実績に反映できる手法があるのかどうかは確認しておきたいと思います。そういうお考えがあればお聞かせいただくのと、もし、そういう方向に行くのであれば、今、何が足りないのかも、もう１点、お聞かせいただきたいと思います。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"大体、半分が都が言っているように、３月の実績を載せており、また、半分は平均で出しています。ただ、平均で出すほうがわかりやすいのではないかということで、これも次回の計画を立てるところでは、また検討できればと考えております。２点目の医療的ケアの先ほどのところなのですけれども、医療的ケアが必要なお子様の支援体制の協議会なのですが、こちらは自立支援協議会の部会とは別に開かせていただきまして、当然ながら、そこでの協議内容につきましては。","voiceIndex":55,"id":"exchange-023"},{"speaker":"若林委員","kind":"意見","question":"最後の相談支援については、おっしゃる意味、昨日も議論させていただいたのはよくわかりました。そういう仕組みを受ける側がしっかり理解するというところ。こういう地域共生、身近なところでという方向であれば、障害者福祉課にも専門家の配置というのは、今後のマンパワー的な部分が実際にどうしても必要になってくるという意見を申し上げて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-024"}]},{"id":"topic-03","title":"高額療養費の制度見直し","agenda":"高額療養費の制度見直し","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"平成３０年８月からの上限額を見ると、赤字で、一番上だったら２５万２,６００円プラス、この括弧にある計算式で、掛ける１％を足したものが最終的な限度額となるのですか。","respondent":"三ッ橋国保医療年金課長","answer":"こちらは上限額がそれぞれ８万１００円や１６万７,４００円、また２５万２,６００円となっておりますが、具体的にもう少し説明いたしますと、例えばですけれども、医療費が１００万円かかったとします。現役並みですと３割負担なので３０万円が窓口の負担になります。","voiceIndex":64,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"わかりました。区民の実態を一番近くで見ておられる自治体として、こういった怒りと悲鳴が上がっている状況を国にぜひ伝えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"こちらにつきましては、社会全体が高齢化しておりまして、今回、制度の持続可能性を高めるためには、高齢者の方々にも制度の支え手として、年齢を問わず、負担能力に応じて負担をいただくことが必要と考えております。","voiceIndex":66,"id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"細分化をされたということで、そうすると、品川区の国民健康保険に加入している７０歳以上の方が、現役並みＩ、II、III、どれぐらいの割合の方が加入されて、おおよその人数が多分あるのだろうと思うのですが、状況はどういう実態なのですか。","respondent":"三ッ橋国保医療年金課長","answer":"７０歳から７４歳までの国保と７５歳以上の後期高齢者とに保険料が分かれておりますので、簡単に申し上げます。国保に関しましては、２００件程度です。しかしながら、後期高齢者医療制度に関しましては、４,６００件程度となっております。","voiceIndex":68,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"今、ざっと全体の数をお聞きしたのですが、区分に分けるとどれぐらいというのもわかるのですか。","respondent":"三ッ橋国保医療年金課長","answer":"なかなか区分が難しいところがございまして、区分までははっきりと申し上げられません。特に後期高齢者医療保険制度は広域連合が区分分けをしておりますので、そのデータまではこちらに来ていません。全体としての状況になります。","voiceIndex":70,"id":"exchange-028"},{"speaker":"こんの委員","kind":"質問","question":"広域だから、区としては把握はなかなかということです。広域も国も、こういう細分化をして、能力に応じて負担をという方針からいくと、それなりの人数がご負担をいただいて、公平性を保ったほうがいいという人がいるということです。ざっくり数字はなくても、品川区としては、そういうある一定の所得のある高齢者が多いと見ているのでしょうか。どんなふうに捉えていらっしゃいますか。","respondent":"三ッ橋国保医療年金課長","answer":"今回、所得区分はなかなか把握できません。実際にこちらの高額療養費の給付の観点から申し上げますと、今回の見直しに当たって、特に後期高齢者の部分ですが、今回の見直しの制度の給付費が４８０億円の減となるので、全国的に見ますと相当な金額と考えられます。","voiceIndex":72,"id":"exchange-029"},{"speaker":"こんの委員","kind":"意見","question":"当然ですが、お年を召して、どんどん医療が必要になってくるとなると、本当に一定の支払い能力はあったとしても、それに応じての医療費がかかるということになっていくのだろうと思うと、今までざっくりその方たちも全部一律だったものが、段階に応じて、所得に応じてという考え方は必要だろうと思うのです。そこら辺は、細かいご説明なのですが、区の健康施策をどんなふうに捉えていますか。","respondent":"三ッ橋国保医療年金課長","answer":"健康、また長寿は考えなければならない、大事な、特にこれからの大切な問題だと考えていますので、引き続き対応をしてまいりたいと思います。","voiceIndex":74,"id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回、８月から変わるということなのですけれども、去年も８月から変わっています。去年のところは、一般が、外来が１万２,０００円だったのが１万４,０００円になり、入院も含めて、限度額が４万４,４００円が５万７,６００円になったということです。どういう形で値上げは決められるのか。それはどこでどういうふうに決められるのかを教えていただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"具体的に申し上げますと、例えば、前回の見直しの部分ですが、委員もご存じだと思いますが、こちらは一般の金額が変わっている。そして、第２段階目というふうに、２段階の施策となっております。","voiceIndex":76,"id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここのところはどれくらいの方が対象になるのか。多分、非課税と一般と現役並みというのはおおよそわかるのではないかと思うのですけれども、そこら辺のところを教えていただきたい。１万８,０００円という外来で、実際にこれ以上に高く外来で使っていて、上限額という状況は、実際問題、どれぐらいあるのかもわかったら教えていただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"今回の１万８,０００円の部分ですが、こちらは具体的な数値は把握しておりませんが、１万８,０００円の水準と申し上げますのは、実際に全てのデータを見直し前に１万２,０００円を設定した水準に１人当たりの医療費の上位２、３％を計算して。","voiceIndex":78,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２、３％の方だけが外来の上限額に適用するという考え方ですか。今、安倍政権、自公政権のもとで、自然増さえも認めない、減らしていくという社会保障削減路線の中で、こういうことも出てきているわけですので、ぜひ、最も区民の身近な実態を把握できる区として、そこのところは国にも意見として上げていっていただきたいと私は改めて要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-033"}]},{"id":"topic-04","title":"住宅宿泊事業法施行後の状況","agenda":"住宅宿泊事業法施行後の状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、届出状況のところで４４件受理済みということで、２枚目の資料だと、１５日時点で受理済みが３３件で、この１０日ぐらいで１０件、とんとんと受理される状況なのだと実感しました。２０件、ごみや騒音を中心に苦情を受けたということですけれども、この２０件というのは、今まで民泊をやられていたところでの苦情なのか。法施行前と施行後、どちらの苦情なのかがわかれば教えていただきたいです。","respondent":"鈴木生活衛生課長","answer":"苦情の件数ですが、これは３月１５日に届出の準備期間が開始されてから、６月２６日現在までのものになりますので、法施行前と後がまざっています。","voiceIndex":87,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。それで、その次の届出の概要のところの建物で共同住宅２９件、一戸建て１５件ということで、品川区の場合は住居専用地域においては土日という制限をしましたけれども、この建物の共同住宅と戸建ての中に、住居専用地域内にあるものはあるのでしょうか。","respondent":"鈴木生活衛生課長","answer":"ただ、前提としまして、住宅宿泊事業ですので、基本的には住宅がある場所なので、そういう意味からも、特に偏りがないと考えております。","voiceIndex":89,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"住居専用地域になってくると、自分の家の隣が突如、そうなってくるかとイメージすると、こういうことも知っておきたいと思ったので、お聞きしました。わかりました。それで、今後の予想のところで、準備時期には区内の民泊数は６００件、そして、法施行により２００件から３００件の届出が出ると想定していたということですけれども、区内の民泊数は約６００件あったということなのですか。","respondent":"鈴木生活衛生課長","answer":"そういう状況の中で、ある程度、法の施行によりまして、当然、届出の手続とか、必要な設備の投資等も必要になりますので、場合によっては３割ぐらいまで減るのではないかということで、届出を実際にするのが二、三百件ではないかという想定で準備をしていたものです。","voiceIndex":91,"id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"意見","question":"わかりました。そうすると、これから続々と増えていく感じになっていくと思うのですけれども、違法民泊は把握されていましたか。無届けの事業者に対して指導を行うと今後の対応のところにもあるのですけれども、そういうところは把握されて、何件かわかりますか。","respondent":"鈴木生活衛生課長","answer":"住宅宿泊事業法の施行に伴ういろいろな状況の調査は６月１５日までできないということで、それまでは法の定めができていないので、グレーという言い方をよくされていました。","voiceIndex":93,"id":"exchange-037"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお聞きしたいのですけれども、先ほどの苦情のところで、ごみや騒音ということなのですが、施行前、施行後、件数としては入っているけれども、苦情を聞いた区としては何か対応されて、処理をしたのかという状況を１つお聞きしたい。例えば、オートロックは、結局、入るのに鍵をあける人が中にいない、そういうケースはあるのか。","respondent":"鈴木生活衛生課長","answer":"１点目の苦情の対応ですが、ごみにしても騒音にしても、区民から苦情がありますと、必ず区の職員、担当者が現地へ赴きまして、まず状況の確認をいたします。","voiceIndex":95,"id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"今みたいなところもきちんと届出のときに指導、こういうふうにしてくださいということは言って、なおかつ、その上であった場合には対応する体制という理解でよろしいでしょうか。","respondent":"鈴木生活衛生課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"は１８０日だと思うのですけれども、土日だけの届出の民泊がどれくらいあるのかを１つ教えていただきたい。そうすると、区内に６００カ所あって、３００件が相談して、これから届出ることになると、残りの３００件は届出なしの違法民泊になるのでしょうか。そして、届出なしの違法民泊に対しては、区としてはどういう対応をされるのかについても教えていただきたいと思います。","respondent":"鈴木生活衛生課長","answer":"そのどちらも、先ほど申し上げたように、警察と連携しながら対応をするというのが今後の対応の方法になると考えております。","voiceIndex":102,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１カ月やってみると、そこの地域が土日しかできないかどうかを区として見るわけですが、その報告を受けて、違反かどうかというのを地域を見てやるという形なのですか。ぜひ、そういう形でもつかんでいただきたいと思いますけれども、その点はどうでしょうか。","respondent":"鈴木生活衛生課長","answer":"今後、その辺の集計のとり方も工夫をしたいと考えております。土日の把握についても、今、ご質問のように、基本的には月ごとに報告が上がりますので、それで日数と曜日の確認をする形になります。","voiceIndex":104,"id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"苦情が２０件ということで、届出が出て、実際に営業をされているのは、共同住宅と戸建てを合わせて４４件。半分近くの件数に対しての苦情と見るのか、１件で何件も、何回も、何日も集中しているのか。ここら辺の状況はどんな感じですか。","respondent":"鈴木生活衛生課長","answer":"説明が不足しておりまして、苦情の２０件は、先ほど申し上げましたように、３月１５日の準備期間からの累計です。届出が出た４４件、６月１５日以降の１０日間ぐらい届出が出ているのですが、届出が出てからの苦情というのは、実はこの２０件には入っておりません。","voiceIndex":106,"id":"exchange-042"},{"speaker":"若林委員","kind":"意見","question":"まちの活性化という１つの大きな目的で民泊が始まって、ただ一方で、議会も区民の方々も、安全で安心な暮らし、生活も課題になっていて、いろいろな区の積極的な対応によって、今のところは苦情はないということで、安心、安全は今は確保されていると認識をいたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":108,"id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"意見","question":"施行前にクレームがついていた、さっき言ったグレーの状態のときにいろいろなトラブル、問題が起きていたということがあります。そこが今度の申請にどの程度入ってきているのかはわかりますか。","respondent":"鈴木生活衛生課長","answer":"ただ、そこについては、私たちも立ち入り検査ができなくて、情報は把握できなかったのですが、実は１つの建物で複数の個人の方が複数の部屋をそれぞれやっていらっしゃったという現状はあったので、件数としては２件になりますけれども、今後。","voiceIndex":109,"id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"確認","question":"区に言ったかどうかはわからないのだけれども、またあそこはごみがひどいと言われました。ただ、自分は今、申請を出していたかどうかがわかっていないから、あまりそこで返事ができなかったので、確認をしました。こういうケースは、ほかはあまりないのかもしれないけれども、その辺は十分注意していただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-045"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"若林委員","kind":"質問","question":"地域共生社会の実現についてで、障害者を入れた受け入れ体制、障害者を含むということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":52654,"voices":123}},{"id":"h30-20180703-8","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"建設委員会","time":"午前１０時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第一三共株式会社用地の寄付","agenda":"第一三共株式会社用地の寄付","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"寄付というのは大いに結構だと思うのですけれども、基本的に企業ですから、普通営利が活動の目的だと思うのですけれども、寄付ということですが、今回地区計画の中で集約が進んでいるという話もありましたけれども、区に提供するというところの、第一三共側がこの地区計画からなのかわかりませんが、そういったところで区から受けたメリットのようなものがやはりあると思うのですけれども。","respondent":"稲田都市開発課長","answer":"協定の第４条です。これは地区計画の地区外ということでの、地区外貢献施設というところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、用途については平成３６年までは治水対策のために使うということなのですけれども、完成後は公園ということですが、先般公園の真ん中のほうに児童相談所の設置ということで報告があったのですけれども、もしこういった用地があるのであれば、ちょっと公園の中のほうに児童相談所ができてしまうと、公園の広く使える部分というのが制限されてしまうところが残念だなと思っていまして。","respondent":"稲田都市開発課長、溝口公園課長","answer":"それから今後の公園整備等々の予定については、まだこれからというところで聞いております。今回第一三共の寄付でいただける土地のところに入れるということは１つの案としてはあったのですが、下水の構造物が大きいものが入ってくる関係で、どうしてもその上に建物が建てられないということで。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"今の児童相談所の設置場所なのですが、前回の当委員会において子供の森公園にというお話があったのです。子供の森公園は前回の議論の中でも、皆さんに親しまれているので狭くなるのはどうかという意見もあったわけです。だったらなぜ前回、そのようないろいろな複雑な問題、複雑かどうかわかりませんけれども、課題があって、ここになるというのは、なぜ同時にこれ報告はしていただけなかったのでしょうか。","respondent":"たけうち委員長、溝口公園課長","answer":"答えられますか。わかる範囲で。児童相談所の設置の考え方については、またちょっと所管が違うところもあるかもしれないので。わかる範囲で結構ですのでお答えください。所管のほうでもいろいろ検討していく中で、どこがいいのか、本当に子供の森がいいのか、またほかの場所、適地がないのか、そういったところさまざま探していく中で。","voiceIndex":10,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"先ほどのご答弁の中で、構造物があってできない状況があるということで、前回の報告の内容は受けとめますけれども、ただ、いろいろな土地を考えてという中に、この近くにこういう土地があるのに、それが後に出てくるということは、やはりちょっと説明としては、土地の広さなどから考えれば、公園の面積をやはり維持してほしいという思いがあるので、だけれどもいろいろ考えた結果。","respondent":"溝口公園課長","answer":"申しわけありません。今までも言葉の足りないところはあったかもしれませんが、そういったところの観点で説明してきたつもりでおりますし、今後も児童相談所の所管は他部署になりますけれども、公園にかかわるところですので、適時適切に報告していきたいと考えております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"２点お伺いをします。２点目が、こちら受領した土地の状態というのがどうなっているのかというのは、現在の時点でどのように把握されていますでしょうか。","respondent":"稲田都市開発課長","answer":"それから土地なのですが、まず現状なのですけれども、建物を取り壊して基礎ぐい等も撤去して、更地の状況で寄付をいただいたという状況です。今後、下水の工事、公園の工事等進んでいく中におきましては、それぞれの担当のほうで測量等、調査等をやりながら進められるものです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"横山委員","kind":"質問・要望","question":"土地の状態についてなのですけれども、ほかの公園等でよく土壌汚染などの部分でスケジュールがおくれてしまったりとかというケースが発生しているかと思うのですが、こちら児童相談所のほうの設計もありますし、公園の整備もあるということで、いろいろ複雑になってきて大変になってくるかとは思うのですけれども、予定がおくれないように、スムーズに進めていただきますよう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと１点だけ忘れました。こちらも一緒に購入すれば、土地がもっと有効に使えるのではないかと思うのですけれども、そういった検討というか、動きというものはされているのか。ぜひ可能であればこういったところも買っていく必要があるのではないかと思いますけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"確かにここに民有地があります。ただこれを今後どうするかというのは、現段階では何も今検討していないです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"安藤委員","kind":"意見","question":"主に学校などですと、隣に隣接した土地というのは結構購入しているケースが多いと思いますので、こちらも公園の隣ということになりますし、ぜひ情報収集も含めて検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"私もここをよく通るし、今朝も通ってきたのですけれども、前の児童相談所の計画地の図と、今回の寄付の図を見ると、当たり前なのですが、児童相談所ができてグラウンドがあって、今回のこの寄付用地については、しばらくは下水の工事のために使うということだったのですけれども、それが終わった後も下水道の施設をずっと置くということになるのでしょうか。","respondent":"持田河川下水道課長","answer":"地下には下水道管ですとか、そういった立坑、マンホール等が入っていく形にはなりますが、地上の部分につきましては、基本的には高さを合わせて平地にするような形で仕上げて、建物を建てるというのは少し難しいのですけれども。","voiceIndex":21,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど西本委員からもあったのですけれども、ここに児童相談所ができれば確かにおさまりがよかったとは思うのですが、そういう形で、この工事が終わった後、ちょうどふたをされてしまうような形に、今グラウンドでなっていますけれども、今後そうなった場合は公園として、グラウンドも含めて何か一体化するような考え方は出てくるのかどうか伺いたいと思います。","respondent":"溝口公園課長","answer":"今回いただいた第一三共の土地ですけれども、下水の工事が終わった後については、グラウンドの再編も含めて子供の森公園全体を改修したいというふうに考えておりますので、その中でしっかりしていきたいと考えていますし、今回児童相談所。","voiceIndex":23,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"心配し過ぎなのかもしれない質問なのですけれども、以前に西五反田のほうの小学校跡地も土壌を掘り起こしたら汚染をされていて、１回全部土を入れ替えたということがあるのですけれども、ここは公園になるので、その辺のしっかりとした事前の調査なり、検査というのはされていますよね。","respondent":"稲田都市開発課長","answer":"寄付を受けるに当たりまして、土壌の調査というのですか、それはやっております。何というのでしょう、異常はないというところで現在聞いております。それで、今後それぞれまた事業者が工事をやる中においては、またそういう土質の調査等をやっていかれるものと思います。","voiceIndex":25,"id":"exchange-011"}]},{"id":"topic-02","title":"ゆうぽうと跡地の今後の計画","agenda":"ゆうぽうと跡地の今後の計画","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"平土間式小ホールということで、フラットな床４００から５００席程度のホールということでお聞きしたのですけれども、ちょっとイメージが、何でしょう、私のほうでまだ湧かなくて、詳細をイメージできるような、何かもう少しわかりましたらご説明いただきたいということと、地元の方といろいろ協議のほうされたということなのですけれども、どのあたり。","respondent":"稲田都市開発課長","answer":"それから地元の方との協議状況がどう反映されたかですけれども、地元の方々はやはり従前のゆうぽうとの、１,８００席ほどあったのですが、ああいうものが欲しいというところで日本郵政のほうにも話をしたり、区も当然そういう話を持っていったところなのですけれども。","voiceIndex":31,"id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"きゅりあんのイベントホールのようなイメージということで、大変わかりやすいご説明ありがとうございました。地元の方、にぎわいの創出というところ気にされてお話しされているかと思いますので、引き続きそのハード面とソフト面と、協力してほかの課とも連携して盛り上げていっていただきたいというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、このゆうぽうと跡地の建築物について、品川区がかかわっていくことはできるのが平土間式小ホールのみということでよろしいのでしょうかということと、向こう側は品川区がこのホールを借りることを希望されているということなのですけれども、それ、何らかそういったコスト面の要件等で協議が整わなかった場合。","respondent":"稲田都市開発課長","answer":"その借りるコスト等の話なのですけれども、コスト、賃料というのですか、そういう話においては区が借りてくれればですので、そのコストに関しては詳細は今後詰めていって、何とか借りられるような形ができればと思います。","voiceIndex":34,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。ですから、いろいろ地元からの要望というのはあったと思うのですけれども、そうした方々の要望というのは、区としてはどのようにつかんでいて、今回どのように反映されていくのかというのはちょっと教えていただきたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、今後の歴史はまた都全体といいますか、周辺を含めまして、そういう中で考えられていくのではないかと考えております。","voiceIndex":36,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"なかなかバレエがやれるというところまではいかないのは残念ではありますけれども、こういったホールというのはまだまだ需要が足りていないと思いますので、ぜひ区としてもかかわっていただいて、区民が使いやすい、借りやすいような体制、料金も含めてできるようにご努力いただきたいというふうに要望いたします。","respondent":"稲田都市開発課長","answer":"これは変えるつもりはございませんで、日本郵政もこのにぎわい拠点ということを十分認識しておりまして、この五反田のまちづくり、にぎわいづくりに寄与していきたいというのは郵政のほうも思っているところです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"前の建物だと駐輪場は余り整備されていなかったように感じるのです。ですから、ここ周辺、五反田の周辺の駐輪、放置自転車の問題もあるので、やはりにぎわい拠点というのであれば駐輪場の整備、駐車場の整備というのは当初から区の、ここの地域の全体の実情を示して考えていただけるという方向に持っていっていただきたいと思うのですが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"駐輪場は基本的には付置義務というものがございまして、その付置義務を守りながらやるというのが建て主側の、区もそうですけれども、認識ですが、駐輪場の話など、五反田もそういう問題もありますので、それは日本郵政とも協議をしながら。","voiceIndex":40,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"五反田文化センターとの兼ね合いもあるわけであって、これをどういう使い方で、どういう人たちに使っていただいて、にぎわいを創出していくのかというのは、全体を見渡した形での交渉をしていかないと、結局何かイベントホール、きゅりあんのイベントホールも非常に予約がとれないぐらい使われているので、メリットはあるのですけれども、でも、ここにそういう施設が必要なのかどうかというところも含めて。","respondent":"稲田都市開発課長","answer":"ウィークデーでは会議等もありますし、今現在五反田は五反田バレーとも言われていますし、そういう企業、オフィスの方々が会議をするのに、平日は埋まる、私の考えですけれども、平日は埋まっていきながら、土日はちょっとした音楽もできるし。","voiceIndex":42,"id":"exchange-018"},{"speaker":"松永副委員長","kind":"提案","question":"もう１つ目が、先ほどの平土間式の小ホールについてなのですけれども、これ４００席から５００席ということで、きゅりあんのイベントホールの規模ということからすると、やはり３部屋ぐらいに分割できるような形ができるのではないかと思いますので、もしまだ詳しい内容が決まっていなければぜひそういった仕切りができるような形にしていただければということを提案します。","respondent":"稲田都市開発課長","answer":"その辺は会議スペースにも使えるということでも考えておりますので、今後日本郵政のほうと仕切り方等を入れるかどうかというところにおいても、検討、協議はしたいと思いますが、構造上いろいろあるかもしれませんし、その辺は協議していきたいと考えています。","voiceIndex":44,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"大ホールをやめてしまうということの理由が何なのかということを、いま一度確認させていただきたいのと、先ほどご答弁で東京都のお話が出たのですけれども、何かこういったことで東京都がかかわってくるということはあるのでしょうか。この２点をお願いします。","respondent":"稲田都市開発課長","answer":"ホールの上にまたオフィス等を載せるとなると、すごく大きい構造物になるということで、建設費用もコストもかかってくるというところもありますから、やはり費用対効果的な、そういうところもあって、方針的にホールはもう持たないというところだというふうに聞いております。","voiceIndex":46,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"今までいろいろと質問が出ているのですけれども、これ本来日本郵政のもので、議会でいろいろと、このまちづくりビジョンもいろいろとあるので要望は出ているのですが、この要望が、先方のものに対してうちのほうで物申すということで、どの辺まで要求、要望が通るものなのか、ちょっとお聞きします。","respondent":"稲田都市開発課長","answer":"今、委員のおっしゃったとおりでございまして、基本的には民間のものでございまして、なかなかここをどうしようかというところにあるのですけれども、区としてはにぎわい拠点としてやっているというところで、そのところを協議しながら、先方にも納得していただきながら。","voiceIndex":48,"id":"exchange-021"}]},{"id":"topic-03","title":"広町地区におけるまちづくりの推進に関する協定","agenda":"広町地区におけるまちづくりの推進に関する協定","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１点目が、都市機能集積ゾーンというものが１枚目の右下の図のところに、オレンジの色のところにあるのですけれども、こちらはどういったものなのでしょうか。国が示している指標などの中から検討していくような形なのか、もし、もう少し具体的にわかりましたら教えていただけたらと思います。","respondent":"稲田都市開発課長","answer":"この検討方針の例ですが、都市機能集積ゾーンという、この名称ですけれども、駅に近いというところもあって、まちづくりにおいて、例えば事務所とか、にぎわい施設、店舗等とか、そういうものを考えられるのではないかということで、そういう都市機能を集積しながら。","voiceIndex":55,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"いよいよ具体的に動いてきたのかなということで、大分話は煮詰まっているのではないのかというのが印象なのですけれども、まずこのまちづくり方針の策定というのは、大体いつぐらいを予定されているのか、また、その２０２１年以降の着工ということも、３年後の着工を目指すというふうにしているということで、都市計画とか、そういうものの変更、決定について、現段階で何かこう。","respondent":"稲田都市開発課長","answer":"大井町のまちづくり方針、今年度末には方針をつくっていこうかとは考えております。そのときにはちょっと区民の皆様にも、どういう手法でいくかはわかりませんけれども、ある程度お示ししながら考えていきたいとは思っております。","voiceIndex":57,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"提案","question":"現段階ではそう受けとめましたということなのですけれども、今後具体的にさまざまなことを私どもも提案をさせていただいて、また一緒に、もし考えさせていただけるところがあれば考えていきたい、このように考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"裏面の２番目のところで、「相互に協力して大規模な土地利用転換である本事業」と書いているのですけれども、先ほど説明があったように、検討方針のゾーニングの図も出ていますが、要するに現在保育園や劇団四季のある区の土地と、広町社宅のあったＪＲの土地の区役所に近い部分を交換するということだと思うのですけれども、それをどういう手法でやるのかというか、単なる等価交換という手法なのか。","respondent":"稲田都市開発課長","answer":"既に進められた地区、これから進めていこうというところがありますけれども、やはり主に動きが見えてきたところといいますか、今具体的に検討していこうというようなところが中心になると思いますので、広町地区等々が中心になりながらも。","voiceIndex":60,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろいろな手法はこれからということですけれども、ちょっと私もというか、その手法の中にいわゆる再開発というのですか、第一種市街地再開発事業という手法も入るのかということを確認させてください。むしろ私は、こうした大井町のまちづくりの推進というのであれば、その目的の中にはこういったものを入れるべきではないかと思うのですけれども、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"こういう中で具体的に行政機能やにぎわい機能や、こういうものは検討していこうというふうになっていくものでございまして、これはあくまでも大きな方針ですから、大井町の特色を出す具体的な手法とか、そういうものは今後検討されていくのではないかと考えています。","voiceIndex":62,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと先ほど伺ったのは、第一種市街地再開発事業に当たるものではないということで、その手法というのは、例えば今の北品川五丁目の再開発も、もともと区の総合体育館があったのです。ですから、そういった例もあるので、再開発という手法も検討の中に入るのですか、あり得るのですよねということで聞いたので、お聞かせ願いたいと思います。","respondent":"稲田都市開発課長","answer":"第一種市街地再開発事業におきましては、権利者の方が何人以上が集まってやっていくとか、そういう条件等々があります。今回の今考える中では、第一種市街地再開発事業には当てはまらないというのが、我々の今検討している結果です。","voiceIndex":64,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"通ってこられる方々、そうした方々の意見を踏まえて策定しないと、本当にひとり歩きして、結果として一握りの方々しか喜ばないような、あるいは一部が利益を得るような、そういったまちになってしまうのではないかというようなことを非常に危惧しているので伺っていますが、いかがでしょうか。どういった意見集約を考えているのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中におきまして、方針づくりにおきましても、区民の皆様等々にはお諮りをしていきたいというふうに考えております。ただ、具体的な手法、どのような形でというのはこれから詰めるところでございまして、まだ決まってはないというところです。","voiceIndex":66,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"まちづくりの方針をつくる手法というのは、もう直接の説明会も含め、アンケートも含め、もちろんパブリックコメントはもちろんのこと、さまざまな手法を駆使して、ぜひ皆の区民の意見を大いに取り入れて、検討していっていただきたいと思いますし、そういったものがまだ特に意見集約もされていない段階で、一定の、何というのですか、方向性を定めて進めていく、こういう今回の協定みたいなものは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"検討方針を見させていただきまして、特にその右側の図です。ひいては新しい庁舎をつくっていくということという理解でよろしいのでしょうかということがまず第１点目です。歩行者ネットワークも、これかなり長距離で伸びておりますが、これペデストリアンデッキのようなものを考えられているのでしょうかということが３点目で、以上３点、ご答弁よろしくお願いします。","respondent":"稲田都市開発課長","answer":"その道路の基盤というものは、ではどう考えるかというところになりますと、補助２６号線、それから補助１６３号線、こちらをつなげていって、しっかりとした道路ネットワークをつくるのが妥当ではないかというところで、現在検討を進めているです。","voiceIndex":70,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした世論の、区民の声や経済状況等も考えて、うまく、しかし行政機能はしっかり維持しなければいけないということを考えて、バランスのよいまちづくり、新たな行政機能づくりということをぜひお考えになっていただきたいと考えていますが、この点いかがお考えでしょうか。","respondent":"稲田都市開発課長","answer":"私どもはまちづくりの観点から、まちづくりを進めていくです。この間の本会議でも答弁がありましたけれども、庁舎も大分古くなってきているというところにおきましては、このまちづくりに合わせながら、庁舎のあり方も検討していくところだという状況です。","voiceIndex":72,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"概要のところに平成２５年度から共同検討を行ってきているということなのですが、５年間どういう検討がなされて、どういう状況で、今回協定書を取り交わしたいというＪＲ東日本からの申し入れがあったということなのですけれども、その経緯というものも含めて教えてください。","respondent":"稲田都市開発課長","answer":"平成２５年度から進められているＪＲとの共同検討です。単年度ごとに今年度やることを協定を結びながらやってきたわけですが、まず平成２５年度あたりはまちづくりのコンセプトとか、そういうイメージ等々、そういうものが話し合われたと。","voiceIndex":74,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"この議会のほうでも、時々どうなっているのかということでの質問があったと思うのですけれども、平成２５年度からいろいろなテーマを持って協議をしていたということは、もちろん公開できないものもあると思うのですが、どういう話し合いになっているのかということの経過報告というものはなされないのでしょうか。なぜなのかということです。","respondent":"稲田都市開発課長","answer":"これまでの共同検討を踏まえながら、本格的にこのまちづくりを進めたいというＪＲの意思でございまして、区もＪＲに合わせながらやっていこうかですので、ＪＲのほうも何とかこの２０２１年以降、ただいつかというのはまだ今のところ。","voiceIndex":76,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"３年間でいろいろな構想があるにせよ、具体的なものを考えていくときに区民の方々にお知らせするという経過も必要だし、いろいろな手続が必要になってくると、非常にこの２０２１年着工というのはタイト過ぎるのではないかなと。その辺の、そこはすごく乖離があるような気がするのですけれども、その辺の調整をどのようにされているのか、現状をちょっと教えてください。","respondent":"稲田都市開発課長","answer":"確かに委員おっしゃったように、短いのではないかということはあります。先ほども言いましたけれども、タイトなスケジュールであることは確かではありますが、そういう中ではありますけれども、区としてもそれに沿うような形で進められればと現在のところは思っております。","voiceIndex":78,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり新幹線が通ってとか、ですから、やはり品川区の一番の大きなメリットをつくるための１つの大きな場所だと思うのです、ここは。だけれども、ありきたりではおもしろくない。もちろん早くやっていきたい思いはありますけれども、やはり強制的にやるのではなくて、みんなでつくっていくという方向に、ぜひ持っていってほしいと思いますので、これは要望として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-035"},{"speaker":"松永副委員長","kind":"確認","question":"私からは１点だけ確認させてください。協定を締結する目的は書かれている内容のとおりだと考えています。今検討段階ということなのですけれども、今の段階で、これは５対５になるのか、それとも半々ではないのか、その辺について伺いたいと思います。","respondent":"稲田都市開発課長","answer":"その点につきましてはまだ検討段階でございまして、今後詰めていくものでございまして、何とも言えないというところです。面積的にはここに示すような割合があるですが、またこの中のどの部分をどうという話にもなってきますし、その辺は今のところこれから詰めていくです。","voiceIndex":81,"id":"exchange-036"}]},{"id":"topic-04","title":"集団回収事業における雑がみ回収の実施","agenda":"集団回収事業における雑がみ回収の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"雑がみとはというところなのですが、リサイクルマークが箱などによくついていると思います。そのリサイクルの紙と書いたものでないと雑がみにならないというわけではないのか、その辺ちょっと、あのマークというのは何なのかということをお伺いしたいのが１点です。もう一つは、今回対象を広げるのは歓迎するのですけれども、広げる動機は何だったのか、２点目にお伺いします。","respondent":"工藤品川区清掃事務所長","answer":"そういった意味で、このような新たな特定品目の項目を設けることで、より一層の集団回収の活性化につなげてまいりたいと、このような考えで今回事業を実施したところです。","voiceIndex":87,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"それをさらに集団回収にもということだと思うのですけれども、ぜひ進めていただきたいと思います。自治体によっては全てのプラごみの資源回収も実施しているところもあると聞いているのですけれども、ぜひそちらも順次資源回収の対象にしていただきたいと思っているのですが、いかがでしょうか。課題など、今どういったものが課題になっているのか、あわせてお伺いできればと思います。","respondent":"工藤品川区清掃事務所長","answer":"そういった中で、私どもといたしましては、２３区清掃主管課長会、部長会、また区長会を通じまして、国に対しまして、今プラスチック製品を製造する事業者に対しまして、事業者責任のもとで処理をしていただきたい旨の要望をしているというのが現状です。","voiceIndex":89,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"ありがとうございました。確かにごみというか、製品をつくる製造者のほうにも、そもそもごみにならない商品を開発するなどということも含めて、やはりごみを減らしていくという、そういう社会にしていくということは重要な観点だと考えていますので、引き続きそういった要望もしていただきながら、ちょっと他自治体なども研究していただいて、できるところから回収のほうも研究していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"これ、町会、自治会などということでの地域の団体ということなのですが、ごみ収集、この事業に対して協力したいけれども、ごみ収集する場所がない。結局全部の町会で取り組んでいるのでしょうかということが１つ。その中で光沢があるものなど結構入っていると思うのですけれども、それはだめなのでしょうか。その区分けはやはりわかりづらいなと思っているのですけれども。","respondent":"工藤品川区清掃事務所長","answer":"２点目です。新聞等に入っているチラシの件です。いろいろと皆さん、地域の中で私どもご説明に行った場合にも悩まれているという方、素朴な疑問、質問をよく受けるです。","voiceIndex":92,"id":"exchange-040"},{"speaker":"西本委員","kind":"提案","question":"それから町会等で１４２団体ということで、大体６０％、７０％ぐらいなのですよね。例えば、やりたいのだけれども、公園の一角を借りたいとか、集積する場所を少し収集するときに貸してもらえないかなどというような申し入れというのはないのでしょうか。そうなった場合に、やりたいのだけれども場所がないのでといった場合に、では公園の一角を何時間とかという、そういう提案などは可能なのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"やはり頻度を多くすると、いわゆる在庫というのか、出されたものを置く場所がなくなってまいるようなところもありますし、そういった相談には応じてまいりたいというふうに考えているところです。","voiceIndex":94,"id":"exchange-041"}]},{"id":"topic-05","title":"オリンピック・パラリンピック施設周辺無電柱化事業に伴う道路整備等工事","agenda":"オリンピック・パラリンピック施設周辺無電柱化事業に伴う道路整備等工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"エレベーターのほうですけれども、勝島歩道橋の向こう側のほうは平成３１年度以降に設置ということを言われていましたが、こちらオリンピックに間に合うようなスケジュールで、随時敷設されていくのでしょうかということが１つです。メリット面とコスト面と課題について、ちょっと一般論になってしまうのかもしれないのですが、伺いたいと思います。","respondent":"多並道路課長","answer":"電線共同溝のメリット等ですけれども、今回のここの会場につきましては、国や東京都のなかでもオリンピック会場周辺の無電柱化を進めていくという方針がありまして、区としてもそれに連動して、品川区としても無電柱化を進めていきたいというような考え方があります。","voiceIndex":100,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば桐ヶ谷通りとか、あるいは池上通りと桜新道をつなぐ通りですとか、幅員がさほど広くない上にそこに電柱があるような歩道というものが結構区内にありまして、そういったところでは無電柱化がより安全な歩行環境に寄与をするのではないかと思っているのですけれども、区内のそういったところもぜひ進めていく必要があるのではないかと思うのですが、現在の区の考え方といいますか。","respondent":"多並道路課長","answer":"特に今ご指摘あったように、桐ヶ谷通りも緊急輸送道路になっていますが、狭い区道の無電柱化という技術革新が非常に進まなければできないところもありますので、これについては国や都のほうで今、技術的な研究をしておりまして、特に都については。","voiceIndex":102,"id":"exchange-043"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認です。ブルーの色のところの工事その１のところの距離というか、場所なのですが、これもう少し延ばしていただいて、四つ角のところまで持ってくることはできなかったのかと思うのですけれども、途中で何かとまっているので。どうせだったらもうちょっと延ばすこともできなかったのかと思うのですが、いかがでしょうか。","respondent":"多並道路課長","answer":"今の委員のご指摘の西側の延長かと思うのですが、これは実は当初この事業、ここがホッケー会場になるということが決まってから、この無電柱化をそれまでにどうやれば間に合うかということで、いろいろ検討してまいりました。","voiceIndex":104,"id":"exchange-044"}]},{"id":"topic-06","title":"しながわ区民公園南側ゾーンおよび水処理施設改修工事","agenda":"しながわ区民公園南側ゾーンおよび水処理施設改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改修計画に反映されたという点は、どういう点になりますでしょうか。伺います。それと、いろいろ改修に当たって既存の木があると思うのですけれども、でき得る限り自然の木というのはやはり残していったほうがいいと思うのですが、その辺の配慮のようなものはいかがでしょうか。","respondent":"溝口公園課長","answer":"昨年度実施した説明会です。１回目に９月１４日に説明会を開催しておりまして、参加者数としては２４名の方が参加しております。","voiceIndex":112,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"では１点だけ伺います。","respondent":"溝口公園課長","answer":"夏休み等繁忙期になりますと、今まで閉まっていた売店、そういったところもありますので、そういったところにケータリングカーを入れられるような工夫をしてみたり、オープンスペースを多く設けたりとか、そういった工夫をしながら魅力向上に向けた取り組み。","voiceIndex":114,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"意見","question":"ハードだけではなくてソフトの面、そういうところも充実をすることでアプローチの魅力を増すということで、よくわかりました。動物のモニュメント、いつも話していますけれども、やはり造形の魅力というのは非常に大事だと思いますので、デザインについてはもう恐らく考えていらっしゃるし、発注するところも考えていらっしゃると思うのですが、本当にふさわしいものができ上がることを期待しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-047"},{"speaker":"筒井委員","kind":"確認","question":"勝島の海を３分の２に縮小し、芝生広場を設けるということなのですけれども、これやはり結構大きな変更だと思いますが、ちょっといま一度ご答弁、前の委員会でもあったかもしれませんが、もう一度確認のために、なぜ芝生広場を設けようという理由に至ったのかという点をご説明お願いいたします。","respondent":"溝口公園課長","answer":"今回の勝島の海を３分の２に縮小するというところから少しご説明させていただきたいと思います。","voiceIndex":117,"id":"exchange-048"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。ただ、平常時には憩いの場ということで、もちろん広域避難場所にもなるので、余り設備などをたくさん置けないかもしれないのですけれども、何らかの遊具とか、そういうものは置くことになるのでしょうか。ということがまず１点目です。","respondent":"溝口公園課長","answer":"これをすることによって、今現在開園から３０年以上経過して、当初の水処理施設としての機能が、全くというわけではないのですけれども、完全に機能していないところがありますので、こういった今回の改修に合わせてポンプ、または水処理の施設。","voiceIndex":119,"id":"exchange-049"},{"speaker":"筒井委員","kind":"質問・要望","question":"どうもありがとうあります。この勝島の海というのも、ある意味品川区の水辺活用の１つだと思っていますので、ぜひともこういった勝島の海も重要な品川区の水辺として捉えて、ぜひさらなる促進を図っていっていただきたいと思います。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"１つは水質がかなり改善されるということで、水辺で子どもたち、十分に遊べるような状況になるのでしょうかということが１つと、区民公園もそうなのですけれども、食事環境の改善ですね。そういう食事の。非常に今、とてもおいしいようなものもあるので、そういうものを幾つか、１個ではだめだと思うのです。やはり食ということをもう少しここの中にも入れていただきたいと思うのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"それとレストラン横にも新たに食事を提供する売店を設けようということで、今回計画しておりますので、そういった中で公園利用者も気軽に利用できる、食事が楽しめるような、そういった施設、そういったものも今回あわせて整備をしていきたいと考えていますので。","voiceIndex":122,"id":"exchange-051"}]},{"id":"topic-07","title":"浜川公園改修工事","agenda":"浜川公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点目ですけれども、改修は歓迎するというか、うれしいという声がある反面、また工事になってしまうのかというような声もあると聞いていますが、工事期間中の公園の利用というのは、基本的には全面閉鎖ということになってしまうのかどうか、ちょっと聞かせていただきたいということが１つです。近隣住民ですとか、あるいは利用者の意見の反映というのはどのようにこの場合行われたのか伺わせてください。","respondent":"溝口公園課長","answer":"工事期間中の公園の利用です。浜川公園につきましては区民公園のように広くありませんので、基本的に全面閉鎖した形で工事を進めていきたいというふうに考えているところです。","voiceIndex":129,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"説明会のようなものは、具体的には行われなかったような感じなのでしょうかと思ったのですけれども、ちょっと２５０ｍ範囲の居住者の方が主に使う公園の場合はという話がありましたが、ちょっと公園によってそういう説明会を区が主催したりする場合としない場合というのは、何か基準というものがあるのかということはお伺いしたいということが１つです。","respondent":"溝口公園課長","answer":"区民公園のように総合公園、要は区内誰でも、不特定多数の方たちが利用するような広い公園でありますと、やはり公園利用者の方、また使われている方は多岐にわたりますので、説明会という形で計画を示しながら、どういう形で整備していくのか。","voiceIndex":131,"id":"exchange-053"},{"speaker":"安藤委員","kind":"意見","question":"最後のところなのですけれども、こういった余り大きくないところで公園改修というものはやはりあると思うのです。これからも。町会のほうはその集まりに行ったのかどうかとか、ちょっと具体的にこのような形で今回声を聞いたのだというところをお聞かせいただきたかったので、もう一度だけお願いします。","respondent":"溝口公園課長","answer":"そういったものも踏まえて今回設計を進めてきて、今回のご報告に至ったというのが現状です。","voiceIndex":133,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"キャッチボール場なのですが、これは網などがあるものですか。それから休養施設、「ベンチ、ウッドデッキ等」と書いてありますが、これ全体的にベンチなどでどれだけの方々が休むことができるのか。多分子どもたちもたくさん来るだろうと思うのですけれども、その数によってはちょっと少ないかもしれないと感じているのですが、いかがでしょうか。","respondent":"溝口公園課長","answer":"桜についても、地域では名所になっているところですので、そういったものもしっかり新たに植えさせていただいて、引き続き桜の名所として使えるような公園というふうに、使っていただけるような整備を考えているところです。","voiceIndex":135,"id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどからキャッチボール場のことについて、かなり質問等、ご答弁でも強調されているのですけれども、わざわざここにも「下水道工事の影響で撤去したものを復旧」ということで、特別だよというようなニュアンスが出ているのですが、キャッチボール場を復旧するということは非常にいいことだとは思うのですけれども、全体の品川区内の公園の考え方として、キャッチボール場というのが。","respondent":"溝口公園課長","answer":"すみません。キャッチボール場のある公園ですけれども、品川区内２２公園、西霧ヶ谷公園ですとか、今回整備します浜川公園、そういったところでキャッチボールが楽しめる公園があります。","voiceIndex":140,"id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問","question":"私からちょっと何点かなのですが、まず今まであったものについて伺いたいと思います。よく私も通るのですが、この交差点付近のところによく自転車をとめて、小学校とか幼稚園の送り迎えをされている保護者の皆様方がいらっしゃるのですけれども、その辺も含めてどう対応していくのかということについて伺いたいと思います。","respondent":"溝口公園課長","answer":"続きまして駐輪場です。資料裏面の計画平面図をご覧いただきたいと思います。その上の部分に一応駐輪スペースを設けておりまして、今まで６台分しかとめていられなかったものが、一応１８台とめられるような計画で設計を進めて、今回ご報告させていただいているところです。","voiceIndex":142,"id":"exchange-057"}]},{"id":"topic-08","title":"大井町駅前パブリックスペース（公衆便所）設計コンペティション","agenda":"大井町駅前パブリックスペース（公衆便所）設計コンペティション","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと公開コンペということですけれども、このコンペで選定する選定者はどなたで何人ぐらいなのか、これが日本建築家協会が入るということになるのか、せっかくですから公募区民など入れてはいかがかと思うのですけれども、いかがでしょうか。","respondent":"溝口公園課長","answer":"そういったものにもしっかり向き合った形での改修計画を立てて、実施に移していきたいというふうに考えているものです。","voiceIndex":151,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとあわせまして、このような建設ですとか、運営事業者選定などについて、公共施設などにかかわる、こういった公開コンペをした例というのが、ちょっとこの所管でこれ、これまであったのかというのが、あったら教えていただきたいと思うのですけれども、よろしくお願いします。","respondent":"溝口公園課長","answer":"ただ、ほかで聞きますと、やはりまちなかでいきますといろいろなことを考えていく中で、事業者ではなく提案内容を審査して、いろいろ自分たちのまちづくりを今後どうしていくのか考えるのに業者を選定したり。","voiceIndex":153,"id":"exchange-059"},{"speaker":"安藤委員","kind":"意見","question":"昨年の行革委員会だったのですけれども、私、その中で世田谷区の庁舎の建て替えの問題について視察に行ったのですが、そのときにかなり公開性の高いやり方をしていて、やはりこうした区政に住民の方が参加してもらったり、関心を持ってもらったり、まちづくりも含めてそういったことを促していくという観点から、ぜひこういった試みは今回やるということで、それを歓迎したいと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":155,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"スペースですが、これ高さとか、面積というのは、今の現状のままでのということなのでしょうか。それと、このトイレだけではなくて、やはり大井町のこの周辺の景観もいろいろあると思うのです。だからその建物自体はいいかもしれないけれども、まち全体を見たときに何か違うのだというふうになりはしないかなという感じがあるのですけれども、いかがでしょうか。","respondent":"溝口公園課長","answer":"審査の過程では、日本建築家協会だけでなく品川区の方も２名選定委員になりますので、当然周辺に余り合わないようなものをつくれば、それは選定段階でしっかり、選定していく中で選ばれていくものについては。","voiceIndex":156,"id":"exchange-061"},{"speaker":"あくつ委員","kind":"提案","question":"そういうものを今回コンペの材料、設計プラスそういうものも提案ということは入らないのでしょうか。","respondent":"溝口公園課長","answer":"やはり魅力的な施設をつくることによって、今回コンペティションという形で、ちょっと変わった形での提案をいただく中で、さらにこれがその先のネーミングライツですとか、そういったものにもつながっていくような取り組みになればと考えて。","voiceIndex":158,"id":"exchange-062"},{"speaker":"あくつ委員","kind":"提案","question":"わかりました。そういう提案がされるかもしれないしというところで、でも一応デザイン優先というところで、デザイン、機能優先ということで。そういう形でそういうものができ上がれば、今後そういうものを民間の力を活用して、経費削減というところでそういったところもお考えいただきたい、研究されているということでしたけれども、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":160,"id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"今回非常に珍しいコンペティションという方式でやられるということなのですけれども、非常におもしろいとも思いますし、あと京浜東北線のホームから、このトイレとか結構見えるので、重要な位置にあるトイレだと考えていますが、今回コンペティション方式をこのトイレに採用しようとした理由というのは何でしょうか。ご答弁よろしくお願いします。","respondent":"溝口公園課長","answer":"もう一つは、大きなところでもう一つあるのが、工期的になかなか、今年単年度で設計して工事の発注まで行う計画をしておりましたので、そういった中で短期間のうちでよりよい提案をいただきながら、取捨選択してその先に進めていくと考えたときには。","voiceIndex":161,"id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。ただ、やはり大井町は重要だということが１つの理由だというようなご答弁ありましたけれども、先ほどの広町のまちづくりとか、あと大井町全体のまちづくりというものもあります。つくられる方のイメージとかもあるのでしょうけれども、区としてはこうあってほしいなどというイメージというものはあるのでしょうか。","respondent":"溝口公園課長","answer":"大井町全体のところでいきますと、１つはやはりまちづくりでいきますと、まちづくりマスタープランが大きな方針となって、その下に大井町駅周辺のまちづくりのビジョンがありますので、やはりそういったところをしっかりコンセプトを踏まえてつくっていく。","voiceIndex":163,"id":"exchange-065"},{"speaker":"筒井委員","kind":"質問・要望","question":"区のホームページから資料を今見ているのですけれども、予定工事費がもう６,０００万円以下ということになって記載されているのですが、この値段というのはやはり普通にトイレをつくる建築費と比べて高いものなのかどうか、ちょっとそこを確認したいので、ご答弁よろしくお願いします。","respondent":"溝口公園課長","answer":"当然それを見積もる際には、予算要求する際には、ある程度の内容を想定した額で計算しておりますので、そんなに過度に高いものというふうには考えておりませんが、初めに既に工事費については予算計上されているものですから、その諸条件を与えた中での建築ということで。","voiceIndex":165,"id":"exchange-066"},{"speaker":"横山委員","kind":"質問・要望","question":"そこで質問の期間が、受け付けが７月１７日から回答が２０日ということで設定されているのですけれども、この応募者の方々が質問を投げかけたり、それを区のほうが返していったりということで、区が真にどういうことを求めているのかというところを設計者の方々とやりとりしていくというプロセスがとても重要なのではないかと思うのですけれども、そのあたりのお考えをお聞かせください。","respondent":"溝口公園課長","answer":"そういった中では１人の方に１対１で返すわけではなくて、ある程度まとまった段階でうちのホームページで公表していくとか、応募者全員に返すとか、皆さんが共通認識を持った中で進めていけるように、そういった回答の仕方をしていくということで今考えておりますので。","voiceIndex":167,"id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"その寄せられたご質問をいろいろなほかの応募者の方にシェアしていただいたりとか、なるべく区の考え方ですとか、方針というところ、細かく、何でしょう、ヒントといいますか、設計者の方に区が何を求めているのかというヒントのようなものを質問、回答していくことでより深めていけたらすごくいいのかなと思いますので、そのような形でぜひ進めていただけたらと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-068"}]},{"id":"topic-09","title":"しながわ水族館イルカショー等の中止","agenda":"しながわ水族館イルカショー等の中止","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大体イルカの妊娠、出産までの期間というのはどれぐらいが通常なのでしょうか。伺います。","respondent":"溝口公園課長","answer":"今、現在水族館側のほうで想定しているのは、８月の１０日前後を出産予定日といいますか、出産するであろうというところで見込んです。","voiceIndex":174,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"すみません。今の質問に続いてなのですが、８月１０日前後ということで、そうすると出産後の育児休暇ではないのですけれども、どのぐらいの期間があれば、子育てもあると思うのですが、それはどのぐらいと考えればいいのでしょうか。","respondent":"溝口公園課長","answer":"その後徐々にいろいろ開放しながら、また子どもの様子等を見ながら、いろいろなものをオープンしていくというような形になっていきますので、やはり大体３カ月ぐらいは今までどおりというわけにはいかずに、何かしらショーを中止したりですとか。","voiceIndex":176,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"十分に様子を見ていただきながら進めていただきたいのですが、せっかく出産ということも含めて、新しい仲間ができるのですけれども、それを何でしょうか、名前をつけるであるとか、何かいろいろなイベントにつながると思うのですが、そういうことは考えておられないのでしょうか。","respondent":"溝口公園課長","answer":"さまざま、いろいろ水族館側でも考えているようですけれども、まずは出産のほうに全力を傾けたいということなので、出産後、またどういう形で皆さんにお披露目していくのか、また名前をどういう形で募集していくのかも含めて。","voiceIndex":178,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"これ、すごく楽しみなことですよね。ですから、多分ワクワクする部分の１つだと思うので、やはり生まれたと聞いて、あっ、よかったとなって、今度見に行きたいと楽しみになるところがあると思うのです。なので、水族館のほうと一緒に考えて、生まれる前から告知をしていただいて、今楽しいことがあるというか、ワクワク感というか、それを皆さんに宣伝していけるようによろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-072"}]},{"id":"topic-10","title":"防災行政無線設備更新工事","agenda":"防災行政無線設備更新工事","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"お伺いしたいのが、今回３０番から、３１番からですね。大井ふ頭のほうのバースのところに、コンテナも含めてですか、コンテナセンター、こちら設置を新しくされた理由をまず聞かせてください。","respondent":"古巻防災課長","answer":"こちら３１番以降になりますけれども、港湾部のほうについての新設になりますが、こちら東京都の港湾局からも要請がありました部分なのですけれども、今まで港湾部につきましては一切防災無線のスピーカー、屋外子局の設置がなくて。","voiceIndex":189,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。アナログとデジタルの並行稼働の期間があるというのは、全てデジタルがそろうまでは並行で稼働するということでいいのかどうか。それと、今回設置を行うということで、今までは既存の、アナログの子局があって、そこに並列してデジタルのものを立てる。アナログに関しては最後は抜いていくという、そういうイメージなのか、ちょっとそこの構造がよくわからなかったので教えてください。","respondent":"古巻防災課長","answer":"アナログとデジタルの並行稼働の考え方ですけれども、やはり更新、徐々に行っていきます関係で、子局がアナログのもの、それから新設というか、更新が終わったものについてはデジタルのものということで、それぞれ対応する子局が。","voiceIndex":191,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問","question":"いわゆる海辺のあたりについては、やはりアナログの電波を飛ばして、どちらも同じ内容で、デジタルもアナログも飛ばせるということで、やはり個別の受信機、品川でいえばいわゆる防災ラジオがあるので、もしこれ、可能ならば、法律上許されるのであれば、同じ内容を電波で飛ばすのだったら、アナログとデジタルをそのままずっと飛ばしていれば。","respondent":"古巻防災課長","answer":"ですから、防災ラジオにつきましては、確かにアナログがそのまま続けられれば既存のものをそのまま使えるというようなことではありますけれども、そこも含めましてというか、防災ラジオというか、何か子局を補完するような仕組みについては、アナログ。","voiceIndex":193,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。お考えいただいているということで安心をいたしました。品川の何というか、地域のコミュニティＦＭですか、あれも補完するようなお話もありましたが、防災課のほうで防災ラジオの補完的な対応についてもお考えいただいているということで、ぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-076"}]},{"id":"topic-11","title":"の４、その他を議題に供します。 初めに(1)の所管質問","agenda":"の４、その他を議題に供します。 初めに(1)の所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今委員長が言ったとおりなのですが、６月２９日に石田秀男議員から、北品川駅の駅前広場について質問がされました。住民からの請願なども上がっていた案件です。それぞれどのように具体的に配慮していくというお考えなのか、内容を伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"北品川駅前広場計画の検討状況についてご説明いたします。本計画につきましては、昨年１２月１７、１８日に都市計画案の説明会を行いまして、公告縦覧を行ってあります。当委員会へは昨年１１月２９日に説明会の開催案内、それから計画内容についてのご報告をしています。","voiceIndex":201,"id":"exchange-077"},{"speaker":"安藤委員","kind":"確認","question":"改めて案が縦覧に供されて意見書が受け付けられるという形になるのか確認させてください。あわせまして、計画案が改めて作成されるということですので、住民の意見をやはりこの計画案の作成段階でしっかり反映させていくという都市計画法の第１６条に規定されている公聴会、これも今回こういった今までの経過もありますので、しっかり行っていく必要があるのではないと思うのですけれども、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"公聴会の開催につきましては、前期の委員会のほうでも説明させていただきました。この説明会をもちまして、より詳しく説明をさせていただいた上で質疑応答という形をとりたいと考えていますので、公聴会というよりも改めて説明会の中で議論をさせていただきたいと考えています。","voiceIndex":205,"id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私は代わりにならないと思うのですけれども、それを説明会はやるからいいのだというふうにおっしゃるのであれば、その説明会で出された意見を区はどのように受けとめるのか、その場で出された意見というものをどのように反映していくお考えなのか、その辺をしっかり聞かせていただかないと、到底納得いかないのですが、いかがでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"計画の中身への反映という部分につきましては、地域の住民との話し合いについて今年度進めてまいりたいと思っておりまして、そういった経過を踏まえて説明会というものを改めて開催する予定でおりますので、そういった経過を踏んでいきたいというふうに考えてあります。","voiceIndex":207,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"最後意見ですけれども、都市計画法の第１６条の国の運用指針では、説明会はやはり説明会ですと。ですからそのような性格があるのだということを書いた上で、よほどイレギュラーの場合以外は公聴会を開催するべきであるというふうに、国の、国交省の指針で書いていますので、ぜひそういった運用指針もしっかり踏まえた上で、公聴会というものを開催していただくような検討を強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"確認","question":"今回、この前の一般質問の中で、それについてまたしっかりと考えていくということでの品川区としてのお考えが出たことについては、非常によかったなとは思うのですけれども、そもそもこの広場、駅前広場についての計画というのは、京浜急行の立体化に合わせて、これは品川区として考えているものであって、これを今考えるとおっしゃっているのですけれども、その立体化とタイミングが合わないと。","respondent":"東野まちづくり立体化担当課長","answer":"本計画、駅前広場の計画につきましては、京急本線の連続立体交差事業の関連案件として、都市計画案の説明等々を行っているところです。","voiceIndex":210,"id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"住民の声を聞いて見直すということは、本当に画期的、先ほど画期的という、安藤委員の発言がありましたけれども、何というのですか、その分大変なご苦労が区当局にはかかると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"１点だけ、やはり気になっているところとしては、前回の請願ですか、議論の中でも、地域の皆様方の状況を把握してということだったのですが、そもそも今回の話の流れといいますか、進め方に関しての、これからのこともありますので、進め方について何か、反省までいかないかもしれませんけれども、気づいたこととか、住民の皆さんとの交渉の仕方であるとかということで。","respondent":"東野まちづくり立体化担当課長","answer":"駅前広場計画をつくるに当たりまして、委員会のほうでも説明させていただきました都市計画の運用指針であるとか、それから区でいきますとマスタープラン、それからまちづくりビジョン、そういったものを上位計画として進めてきたところです。","voiceIndex":213,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"今回のようなことというのは結構あり得ますよね、いろいろ進めていく中で。でも、それが説明の仕方であったりとか、進め方であったりとか、順番とかによって、それが裏目に出てしまうということが多々あると思うので、今回ボタンのかけ違いもいろいろあったのかなという思いもあるので、ぜひとも次回から、いろいろなところに関係してきますので、参考にしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":70978,"voices":233}}]);
